  border-color: var(--accent, #34d399);
  color: #06231c;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  color: var(--ink);
  background: var(--bg);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body.app-booting .shell {
  visibility: hidden;
}

body.app-booting.app-boot-ready .shell {
  visibility: visible;
}

body.app-booting::before {
  content: "IELTS Studio\A sketching your practice desk";
  position: fixed;
  z-index: 9999;
  inset: 0;
  display: grid;
  place-items: center;
  white-space: pre;
  text-align: center;
  color: #142033;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 255, 255, 0.94) 0 0, transparent 172px),
    linear-gradient(118deg, transparent 0 42%, rgba(47, 128, 109, 0.12) 42% 42.35%, transparent 42.35%),
    linear-gradient(145deg, transparent 0 55%, rgba(42, 89, 132, 0.10) 55% 55.3%, transparent 55.3%),
    repeating-linear-gradient(0deg, rgba(26, 40, 54, 0.035) 0 1px, transparent 1px 19px),
    repeating-linear-gradient(90deg, rgba(26, 40, 54, 0.025) 0 1px, transparent 1px 23px),
    linear-gradient(180deg, #f7faf8, #edf4f1);
  font-family: "Bradley Hand ITC", "Segoe Print", "Comic Sans MS", Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: clamp(23px, 2.2vw, 33px);
  font-weight: 760;
  line-height: 1.46;
  letter-spacing: 0;
  pointer-events: none;
  text-shadow:
    0 1px 0 rgba(255, 255, 255, 0.88),
    0.5px 0 rgba(20, 32, 51, 0.18),
    -0.4px 0 rgba(20, 32, 51, 0.12);
  animation: bootSketchPaper 1400ms ease-out both;
}

body.app-booting::after {
  content: "";
  position: fixed;
  z-index: 10000;
  left: 50%;
  top: calc(50% + 70px);
  width: min(252px, 48vw);
  height: 12px;
  background:
    linear-gradient(90deg, rgba(19, 93, 83, 0.10), rgba(19, 93, 83, 0.92), rgba(43, 96, 150, 0.86)) 0 3px / 100% 2px no-repeat,
    linear-gradient(90deg, rgba(43, 96, 150, 0.18), rgba(43, 96, 150, 0.66), rgba(19, 93, 83, 0.06)) 0 8px / 100% 1px no-repeat,
    linear-gradient(115deg, transparent 0 78%, rgba(41, 62, 81, 0.34) 78% 82%, transparent 82%) 0 0 / 34px 10px repeat-x;
  filter: drop-shadow(0 10px 18px rgba(26, 87, 80, 0.13));
  transform: translateX(-50%);
  pointer-events: none;
  clip-path: inset(0 82% 0 0 round 999px);
  animation: bootPencilStroke 1500ms cubic-bezier(0.2, 0.78, 0.2, 1) forwards;
}

body.app-booting.app-boot-ready::before,
body.app-booting.app-boot-ready::after {
  animation: bootOverlayFade 240ms ease forwards;
}

body.app-booting.app-boot-ready::after {
  clip-path: inset(0 0 0 0 round 999px);
}

html.boot-theme-dark,
html.boot-theme-dark body {
  background: #071119;
  color-scheme: dark;
}

html.boot-theme-dark body.app-booting::before,
body.theme-dark.app-booting::before {
  color: #ecf8f3;
  background:
    radial-gradient(circle at 50% 46%, rgba(20, 38, 52, 0.90) 0 0, transparent 176px),
    linear-gradient(118deg, transparent 0 42%, rgba(58, 218, 181, 0.16) 42% 42.35%, transparent 42.35%),
    linear-gradient(145deg, transparent 0 55%, rgba(124, 179, 244, 0.14) 55% 55.3%, transparent 55.3%),
    repeating-linear-gradient(0deg, rgba(223, 244, 238, 0.045) 0 1px, transparent 1px 19px),
    repeating-linear-gradient(90deg, rgba(223, 244, 238, 0.035) 0 1px, transparent 1px 23px),
    linear-gradient(180deg, #071119, #0d1a26);
  text-shadow:
    0 1px 0 rgba(0, 0, 0, 0.72),
    0.5px 0 rgba(236, 248, 243, 0.18),
    -0.4px 0 rgba(236, 248, 243, 0.10);
}

html.boot-theme-dark body.app-booting::after,
body.theme-dark.app-booting::after {
  color: rgba(210, 232, 226, 0.64);
  background:
    linear-gradient(90deg, rgba(60, 220, 182, 0.08), rgba(60, 220, 182, 0.96), rgba(96, 165, 250, 0.90)) 0 3px / 100% 2px no-repeat,
    linear-gradient(90deg, rgba(96, 165, 250, 0.18), rgba(96, 165, 250, 0.76), rgba(60, 220, 182, 0.08)) 0 8px / 100% 1px no-repeat,
    linear-gradient(115deg, transparent 0 78%, rgba(214, 236, 232, 0.40) 78% 82%, transparent 82%) 0 0 / 34px 10px repeat-x;
  filter: drop-shadow(0 12px 26px rgba(0, 0, 0, 0.34));
}

@keyframes bootSketchPaper {
  0% {
    opacity: 0;
    filter: blur(0.8px);
  }
  18% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    filter: blur(0);
  }
}

@keyframes bootPencilStroke {
  0% {
    opacity: 0;
    clip-path: inset(0 92% 0 0 round 999px);
  }
  14% {
    opacity: 1;
  }
  68% {
    clip-path: inset(0 23% 0 0 round 999px);
  }
  100% {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 999px);
  }
}

@keyframes bootOverlayFade {
  to {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  body.app-booting::after {
    opacity: 1;
    clip-path: inset(0 0 0 0 round 999px);
    animation: none;
  }

  body.app-booting.app-boot-ready::before,
  body.app-booting.app-boot-ready::after {
    animation: bootOverlayFade 1ms ease forwards;
  }
}

button, input, select { font: inherit; }
button {
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

button,
a,
input,
select,
textarea {
  transition-property: background, border-color, color, box-shadow, transform, opacity;
  transition-duration: var(--motion-fast);
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
}

h1, h2, h3, h4, p { margin: 0; }

/* Touch-friendly active states */
button:active {
  transform: scale(0.98);
}

.shell {
  min-height: 100vh;
}

.nav {
  position: fixed;
  left: 0;
  top: 0;
  width: var(--sidebar-width);
  height: 100vh;
  height: 100dvh;
  overflow-y: auto;
  background: var(--nav);
  color: #eef5f3;
  padding: calc(18px + var(--safe-top)) 12px calc(18px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
  z-index: 100;
  -webkit-overflow-scrolling: touch;
  transition: background var(--motion-base), color var(--motion-base), border-color var(--motion-base);
}

.nav-resize-handle {
  position: fixed;
  left: calc(var(--sidebar-width) - 4px);
  top: 0;
  width: 8px;
  height: 100vh;
  height: 100dvh;
  z-index: 160;
  cursor: col-resize;
  background: transparent;
  touch-action: none;
}

.nav-resize-handle::after {
  content: "";
  position: absolute;
  top: calc(50% - 34px);
  left: 3px;
  width: 2px;
  height: 68px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 38%, transparent);
  opacity: 0;
  transition: opacity var(--motion-fast), transform var(--motion-fast);
}

.nav-resize-handle:hover::after,
body.nav-resizing .nav-resize-handle::after {
  opacity: 1;
  transform: scaleX(1.35);
}

body.nav-resizing {
  cursor: col-resize;
  user-select: none;
}

body.nav-resizing .nav,
body.nav-resizing .workspace,
body.nav-resizing .global-topbar,
body.nav-resizing .topbar,
body.nav-resizing .writing-topbar-actions {
  transition: none !important;
}

.nav-top,
.nav-primary,
.nav-bottom {
  display: grid;
  /* Single column that tracks the (resizable) sidebar width. Without an explicit
     template the implicit column is sized `auto` (= max-content), so options keep
     their full width and overflow/clip on the right when the bar is dragged
     narrower. minmax(0, 1fr) lets the options shrink and wrap to fit. */
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
}

.nav-top {
  min-height: 0;
}

.nav-top-left {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
}

.nav-top-right {
  display: none;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.nav-primary {
  overflow-y: auto;
}

.nav-bottom {
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.nav-secondary {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 6px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 18px;
  font-weight: 800;
  line-height: 1.12;
  margin-bottom: 6px;
}

.brand-mark {
  width: 26px;
  height: 26px;
  flex: 0 0 26px;
  border-radius: 7px;
  display: block;
  padding: 3px;
  background: linear-gradient(180deg, rgba(255, 253, 246, 0.98), rgba(232, 224, 210, 0.96));
  border: 1px solid rgba(255, 255, 255, 0.62);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.18);
}

body.theme-dark .brand-mark,
body.theme-dark.font-academic .brand-mark,
body.theme-dark.font-popular .brand-mark {
  background: linear-gradient(180deg, #fffdf6, #e9dfcf);
  border-color: rgba(255, 255, 255, 0.74);
  box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.18), 0 8px 18px rgba(0, 0, 0, 0.28);
}

.status, .muted {
  color: var(--muted);
  font-size: 13px;
}

.nav .status {
  color: #b8c7c4;
  margin-bottom: 6px;
}

.nav-lock-hint {
  position: absolute;
  left: 12px;
  right: 12px;
  z-index: 2;
  padding: 9px 10px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(245, 158, 11, 0.65);
  background: rgba(255, 247, 237, 0.98);
  color: #9a3412;
  font-size: 12px;
  line-height: 1.45;
  box-shadow: var(--shadow-md);
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity var(--motion-base), transform var(--motion-base);
  pointer-events: none;
}

.nav-lock-hint.hidden {
  display: none;
}

.nav-lock-hint.toast-show {
  opacity: 1;
  transform: translateY(0);
}

.nav-lock-hint.toast-hide {
  opacity: 0;
  transform: translateY(-6px);
}

.nav-button {
  position: relative;
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: #eef5f3;
  text-align: left;
  padding: 0 12px;
  display: flex;
  align-items: center;
  text-decoration: none;
}

.nav-review-dot {
  position: absolute;
  top: 50%;
  right: 18px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #ef4444;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.14);
  transform: translateY(-50%);
  animation: navReviewDotIn 0.42s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

.nav-review-dot::after {
  content: attr(data-count);
  position: absolute;
  right: -20px;
  top: -16px;
  min-width: 16px;
  height: 16px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  padding: 0 4px;
  background: #b91c1c;
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  animation: navReviewCountIn 0.46s cubic-bezier(0.34, 1.56, 0.64, 1) 0.05s both;
}

/* Review badges pop in on each nav render instead of hard-cutting into view. */
@keyframes navReviewDotIn {
  0% { opacity: 0; transform: translateY(-50%) scale(0); }
  100% { opacity: 1; transform: translateY(-50%) scale(1); }
}

@keyframes navReviewCountIn {
  0% { opacity: 0; transform: scale(0.35) translateY(3px); }
  60% { opacity: 1; }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .nav-review-dot,
  .nav-review-dot::after {
    animation: none;
  }
}

.nav-divider {
  height: 1px;
  margin: 5px 6px;
  background: rgba(238, 245, 243, 0.28);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.06);
}

body.font-academic .nav-divider {
  background: rgba(43, 31, 26, 0.18);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.72);
}

body.font-popular .nav-divider {
  background: rgba(31, 31, 31, 0.18);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
}

.settings-nav-button {
  width: 100%;
}

.font-tool {
  display: grid;
  gap: 8px;
}

.font-tool-label,
.nav-user span {
  color: #aebfbc;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.font-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  padding: 6px;
  min-height: 52px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.07);
  position: relative;
  align-items: center;
}

.font-options::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 6px;
  width: calc((100% - 24px) / 3);
  height: calc(100% - 12px);
  background: #eef5f3;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  transition: transform var(--motion-base);
  z-index: 0;
}

.font-options.academic::before {
  transform: translateX(calc(100% + 6px));
}

.font-options.popular::before {
  transform: translateX(calc((100% + 6px) * 2));
}

.font-option {
  min-width: 0;
  min-height: 40px;
  height: 40px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: #dce8e5;
  padding: 0;
  display: grid;
  place-items: center;
  transition: color var(--motion-fast);
  position: relative;
  z-index: 1;
}

.font-option svg {
  width: 20px;
  height: 20px;
  display: block;
}

.font-option.active {
  color: #132026;
  background: transparent;
  border-color: transparent;
}

.nav-user {
  display: grid;
  gap: 6px;
}

.nav-user input {
  width: 100%;
  min-height: 38px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
  color: #eef5f3;
  padding: 0 10px;
}

.nav-user input:focus {
  outline: 2px solid rgba(20, 184, 166, 0.35);
  border-color: rgba(20, 184, 166, 0.65);
}

.nav-user-mobile {
  display: none;
}

.nav-button:disabled,
.nav-button.locked {
  opacity: 0.45;
  cursor: not-allowed;
}

:root {
