  --tone-p2-bg: rgba(30, 64, 175, 0.95);
  --tone-p2-fg: #dbeafe;
  --tone-p2-surface: #e8efff;
  --tone-p2-border: #2563eb;
  --tone-p3-bg: rgba(109, 40, 217, 0.95);
  --tone-p3-fg: #ede9fe;
