.workspace.writing-workspace {
  grid-template-rows: minmax(0, 1fr);
  padding-top: calc(10px + 48px + var(--safe-top));
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
}

.shell.auth-shell {
  grid-template-columns: 1fr;
}

.shell.account-shell .workspace {
  grid-template-rows: minmax(0, 1fr);
  padding: calc(58px + var(--safe-top)) clamp(24px, 4vw, 56px) calc(20px + var(--safe-bottom));
  overflow: hidden;
}

.shell.account-shell .global-topbar {
  display: flex;
}

.shell.auth-shell .global-topbar,
.shell.auth-shell .nav,
.shell.auth-shell .topbar {
  display: none !important;
}

.shell.auth-shell .busy-bar {
  inset: 0;
}

.shell.auth-shell .workspace {
  margin-left: 0;
  padding: 0;
  height: 100vh;
  height: 100dvh;
  min-height: 100vh;
  min-height: 100dvh;
  overflow: auto;
  display: block;
  background:
    radial-gradient(circle at 12% 12%, rgba(16, 163, 127, 0.08), transparent 34%),
    linear-gradient(135deg, #f7f7f8 0%, #eef5f2 100%);
}

.topbar {
  display: grid;
  grid-template-columns: minmax(180px, auto) minmax(0, 1fr);
  align-items: start;
  gap: 18px;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  min-width: 0;
  justify-self: end;
}

.workspace.writing-workspace .topbar {
  align-items: center;
}

.writing-topbar-actions {
  flex: 0 1 auto;
  width: auto;
  display: grid;
  grid-template-columns: auto auto auto;
  gap: 8px;
  justify-content: end;
  pointer-events: auto;
}

body.view-writing .global-topbar > .writing-topbar-actions:not(.hidden) {
  position: fixed;
  left: 20px;
  right: calc(220px + 28px);
  top: 6px;
  display: grid;
  grid-template-columns: auto minmax(0, 520px) auto;
  justify-content: center;
  justify-self: auto;
  margin-left: 0;
}

.writing-topbar-actions .writing-task-switch {
  flex: 0 0 auto;
  min-height: 40px;
  grid-template-columns: repeat(2, minmax(72px, 1fr));
  align-self: center;
}

.writing-topbar-actions .writing-task-option {
  min-height: 30px;
  padding: 0 10px;
}

.writing-topbar-actions .writing-picker-button {
  width: 520px;
  max-width: min(520px, 56vw);
  min-height: 40px;
  height: auto;
  border-radius: 9px;
  padding: 7px 8px 7px 10px;
  box-shadow: none;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px;
}

.writing-topbar-actions .writing-picker-button strong {
  display: block;
  max-width: 100%;
  font-size: 13px;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.writing-topbar-actions .writing-picker-chip {
  min-height: 24px;
  padding: 0 6px;
  font-size: 10px;
}

.writing-topbar-actions .writing-picker-chevron {
  display: none;
}

.topbar-random-button {
  min-height: 40px;
  padding: 0 13px;
  white-space: nowrap;
  border: 1px solid rgba(15, 118, 110, 0.22);
  border-radius: 999px;
  background: linear-gradient(180deg, #ffffff 0%, #eef8f6 100%);
  color: #0f766e;
  box-shadow: 0 8px 18px rgba(15, 118, 110, 0.11);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 850;
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}

.topbar-random-button svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.topbar-random-button:hover {
  border-color: rgba(15, 118, 110, 0.42);
  background: linear-gradient(180deg, #ffffff 0%, #e4f4f1 100%);
  box-shadow: 0 10px 22px rgba(15, 118, 110, 0.16);
  transform: translateY(-1px);
}

.topbar-random-button:active {
  transform: translateY(0);
  box-shadow: 0 5px 12px rgba(15, 118, 110, 0.12);
}

.user-avatar {
  width: 42px;
  height: 42px;
  border-radius: 20px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 700;
  font-size: 17px;
}

h1 {
  font-size: 34px;
  line-height: 1.08;
}

.topbar p {
  margin-top: 8px;
  color: var(--muted);
  font-size: 16px;
}

.practice-header-progress {
  justify-self: end;
  align-self: start;
  width: 78px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding: 0 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 26%, var(--line));
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--panel) 86%, var(--accent) 14%);
  color: var(--ink);
  box-shadow: var(--shadow-xs);
  font-size: 18px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
}

.hidden { display: none !important; }

.editor-prewarm-host {
  position: fixed;
  left: -10000px;
  top: -10000px;
  width: 320px;
  height: 120px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 22px;
}

.practice-panel {
  width: min(100%, 1580px);
  margin: 0 auto;
  min-height: 0;
  height: 100%;
  align-self: stretch;
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr);
  gap: 0;
  padding: 18px;
}

.practice-panel.p3-launch-mode {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 18px;
  padding-bottom: max(22px, calc(22px + var(--safe-bottom)));
}

.corpus-entry-button,
.p1-corpus-entry {
  --corpus-accent: var(--p1-corpus-accent);
  --corpus-accent-dark: var(--p1-corpus-accent-dark);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 46px;
  border: 1px solid color-mix(in srgb, var(--corpus-accent) 52%, transparent);
  border-radius: var(--radius-pill);
  background: linear-gradient(180deg, var(--corpus-accent), var(--corpus-accent-dark));
  color: #fff !important;
  padding: 0 20px;
  font-size: 16px;
  font-weight: 760;
  white-space: nowrap;
  box-shadow: 0 10px 22px color-mix(in srgb, var(--corpus-accent-dark) 20%, transparent);
}

.p1-corpus-peek-button {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  padding: 0;
  line-height: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, #d97706 48%, transparent);
  border-radius: var(--radius-pill);
  background: #f6c453;
  color: #78350f;
  box-shadow: 0 10px 22px rgba(217, 119, 6, 0.22);
}

.p1-corpus-peek-button:hover {
  background: #f3b83d;
  transform: translateY(-1px);
}

.p1-corpus-peek-button svg {
  width: 20px;
  height: 20px;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transform: none;
}

.p2-corpus-entry {
  --corpus-accent: var(--p2-corpus-accent);
  --corpus-accent-dark: var(--p2-corpus-accent-dark);
}

.corpus-entry-button span,
.p1-corpus-entry span,
.corpus-entry-button svg,
.p1-corpus-entry svg {
  color: #fff !important;
  stroke: currentColor;
}

.corpus-entry-button span,
.p1-corpus-entry span {
  display: inline-flex;
  align-items: center;
  line-height: 1.15;
}

.corpus-entry-button:hover,
.p1-corpus-entry:hover {
  background: linear-gradient(180deg, color-mix(in srgb, var(--corpus-accent) 88%, #fff), var(--corpus-accent-dark));
  transform: translateY(-1px);
}

.corpus-entry-button svg,
.p1-corpus-entry svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.p1-corpus-panel,
.p2-corpus-panel,
.language-takeaway-panel,
.corpus-home-panel {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  border: 0;
  background: transparent;
  padding: 0;
}

.home-panel,
.corpus-home-panel,
.language-takeaway-panel {
  color: var(--ink);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.88), rgba(248, 250, 252, 0.92)),
    var(--bg);
}

/* ── Corpus home shell ─────────────────────────────── */
.corpus-home-shell {
  display: grid;
  align-content: start;
  gap: 14px;
  max-width: 900px;
  margin: 0 auto;
  padding: 28px 28px 32px;
}

/* compact kicker + title + subtitle row */
.corpus-home-kicker-bar {
  display: grid;
  gap: 4px;
  padding: 0 2px;
}

.corpus-home-title {
  margin: 0;
  color: var(--ink);
  font-size: 26px;
  font-weight: 820;
  line-height: 1.1;
  letter-spacing: 0;
}

.corpus-home-sub {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
}

/* P1 + P2 two-column cards */
.corpus-top-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.corpus-top-cards .corpus-home-card {
  min-height: 128px;
}

/* ── Review lane (LT / WT / SP) ─────────────────────── */
.corpus-review-lane {
  display: grid;
  grid-template-columns: minmax(120px, 0.22fr) minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  padding: 20px 22px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: var(--radius-lg);
  background: rgba(255, 255, 255, 0.78);
  box-shadow: var(--shadow-xs);
}

.corpus-review-lane-head span {
  display: block;
  color: var(--accent-dark, #2f806d);
  font-size: 11px;
  font-weight: 820;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.corpus-review-lane-head strong {
  display: block;
  color: var(--ink);
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: clamp(18px, 1.6vw, 24px);
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1.2;
}

.corpus-review-links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 1px solid rgba(126, 139, 153, 0.16);
  border-radius: 14px;
  overflow: hidden;
  background: #fff;
}

.corpus-review-link {
  min-height: 78px;
  display: grid;
  align-content: center;
  gap: 5px;
  padding: 14px 18px;
  color: #182033;
  text-decoration: none;
  background: #fff;
  transition: background 140ms ease;
}

.corpus-review-link + .corpus-review-link {
  border-left: 1px solid rgba(126, 139, 153, 0.12);
}

.corpus-review-link:hover {
  background: rgba(47, 128, 109, 0.055);
}

.corpus-review-link:focus-visible {
  outline: 3px solid rgba(47, 128, 109, 0.28);
  outline-offset: -2px;
}

.corpus-review-link b {
  color: #2f806d;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.corpus-review-link span {
  font-size: 17px;
  font-weight: 820;
  color: #172033;
}

.corpus-review-link small {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.4;
}

.corpus-home-card {
  position: relative;
  min-height: 168px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: var(--radius-md);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.88)),
    var(--panel);
  padding: 20px;
  text-align: left;
  display: grid;
  grid-template-rows: auto auto 1fr;
  gap: 10px;
  align-content: start;
  color: var(--ink);
  text-decoration: none;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: transform var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast);
}

.corpus-home-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: #2563eb;
  opacity: 0.7;
}

.corpus-home-card:hover {
  transform: translateY(-2px);
  border-color: rgba(37, 99, 235, 0.28);
  box-shadow: var(--shadow-md);
}

.corpus-home-card:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.18);
  outline-offset: 2px;
}

.corpus-card-mark {
  width: fit-content;
  min-height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.06em;
}

.corpus-card-p1 .corpus-card-mark {
  color: #1d4ed8;
  background: #eff6ff;
}

.corpus-card-p1::before {
  background: #2563eb;
}

.corpus-card-p2 .corpus-card-mark {
  color: #3730a3;
  background: #eef2ff;
}

.corpus-card-p2::before {
  background: #4f46e5;
}

.language-card .corpus-card-mark {
  color: #0f766e;
  background: #ecfdf5;
}

.language-card::before {
  background: #0f766e;
}

.writing-takeaway-card .corpus-card-mark {
  color: #9333ea;
  background: #f3e8ff;
}

.writing-takeaway-card::before {
  background: #9333ea;
}

.corpus-home-card strong {
  font-size: 22px;
  line-height: 1.18;
}

.corpus-home-card small {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.58;
}

.language-takeaway-panel {
  min-height: 0;
  overflow: hidden;
}

.language-book-shell {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  padding: 18px 28px 28px;
  background:
    radial-gradient(circle at 8% 4%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 28%),
    radial-gradient(circle at 94% 10%, rgba(34, 197, 94, 0.12), transparent 26%);
}

.language-book-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 16%, var(--line));
  border-radius: 14px;
  padding: 12px 16px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.86)),
    #fff;
  box-shadow: 0 16px 42px rgba(15, 23, 42, 0.08);
}

.language-book-head h2 {
  margin: 0;
  font-size: clamp(24px, 2.5vw, 34px);
  letter-spacing: 0;
}

.language-book-head p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.language-book-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.language-book-actions span {
  color: var(--muted);
  font-size: 13px;
  white-space: nowrap;
}

.language-action-button {
  min-height: 34px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 820;
  box-shadow: 0 10px 22px color-mix(in srgb, var(--accent) 18%, transparent);
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.language-action-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 28px color-mix(in srgb, var(--accent) 24%, transparent);
}

.language-action-button.secondary {
  background: #fff;
  color: var(--accent-dark);
}

.language-hide-toggle {
  min-height: 34px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 760;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.06);
}

.language-hide-toggle:hover {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
}

.language-hide-toggle[aria-pressed="true"] {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.language-hide-toggle svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.language-takeaway-list {
  min-height: 0;
  overflow-y: auto;
  display: grid;
  align-content: start;
  grid-template-columns: repeat(2, minmax(240px, 1fr));
  gap: 16px;
  padding: 4px 4px 22px;
}

.language-book-empty {
  grid-column: 1 / -1;
}

.language-takeaway-card-wrap {
  position: relative;
  min-height: 148px;
}

.takeaway-speech-status {
  grid-column: 1 / -1;
  min-height: 18px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 760;
  line-height: 1.3;
}

.takeaway-speech-status.is-error {
  color: var(--danger);
}

.language-takeaway-card {
  width: 100%;
  height: 100%;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 16px;
  padding: 20px 62px 22px 22px;
  display: grid;
  grid-template-rows: minmax(48px, auto) minmax(34px, auto);
  align-content: start;
  gap: 16px;
  text-align: left;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94)),
    #fff;
  color: var(--ink);
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.92);
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
}

.takeaway-delete-button,
.corpus-delete-button,
.corpus-menu-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  box-sizing: border-box;
  padding: 0;
  border: 1px solid rgba(100, 116, 139, 0.22);
  border-radius: 9px;
  color: #64748b;
  background: #fff;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.takeaway-delete-button,
.language-takeaway-card-wrap > .corpus-menu-button {
  /* Icon-only button: MUST be a square, never a rectangle. Every dimension is
     pinned with !important so no stray min-height, asymmetric padding, or
     auto-height rule anywhere in the cascade can stretch it tall. */
  position: absolute !important;
  top: 8px !important;
  right: 8px !important;
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  min-height: 28px !important;
  max-width: 28px !important;
  max-height: 28px !important;
  aspect-ratio: 1 / 1 !important;
  padding: 0 !important;
  border-radius: 8px !important;
  flex: 0 0 auto !important;
  box-sizing: border-box !important;
}

/* Keep the kebab glyph proportional to the smaller square button. */
.language-takeaway-card-wrap > .corpus-menu-button svg {
  width: 15px !important;
  height: 15px !important;
}

.p2-material-actions .corpus-menu-button {
  align-self: center;
  justify-self: center;
  width: 40px;
  height: 40px;
}

.takeaway-delete-button:hover,
.takeaway-delete-button:focus-visible,
.corpus-delete-button:hover,
.corpus-delete-button:focus-visible {
  background: rgba(239, 68, 68, 0.08);
  border-color: rgba(239, 68, 68, 0.18);
  color: var(--danger);
  outline: none;
}

.corpus-menu-button:hover,
.corpus-menu-button:focus-visible,
.corpus-menu-button[aria-expanded="true"] {
  background: #f1f5f9;
  border-color: rgba(100, 116, 139, 0.34);
  color: #334155;
  outline: none;
}

.takeaway-delete-button span,
.corpus-delete-button span,
.corpus-menu-button span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  text-align: center;
  font-size: 22px;
  line-height: 1;
  font-weight: 900;
}

.takeaway-delete-button svg,
.corpus-delete-button svg,
.corpus-menu-button svg,
.p2-follow-up-edit-button svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.corpus-card-action-menu {
  position: absolute;
  top: 44px;
  right: 10px;
  z-index: 4000;
  width: 96px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.16);
  padding: 5px;
}

.p2-material-actions .corpus-card-action-menu {
  top: calc(100% - 2px);
  right: 8px;
}

.p2-category-entry-card.is-menu-open,
.p2-topic-card.is-menu-open,
.p2-material-row.is-menu-open {
  z-index: 60;
  overflow: visible;
}

.p2-material-row.is-menu-open .p2-material-actions {
  z-index: 61;
}

.corpus-card-action-menu button {
  width: 100%;
  min-height: 34px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--ink);
  padding: 0 10px;
  text-align: left;
  font-size: 14px;
  font-weight: 720;
  line-height: 1;
}

.corpus-card-action-menu button:hover,
.corpus-card-action-menu button:focus-visible {
  background: #f1f5f9;
  outline: none;
}

.corpus-card-action-menu button.danger {
  color: var(--danger);
}

.corpus-card-action-menu button.danger:hover,
.corpus-card-action-menu button.danger:focus-visible {
  background: rgba(239, 68, 68, 0.08);
}

.language-takeaway-card:hover {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  box-shadow: 0 22px 52px rgba(15, 23, 42, 0.15);
  transform: translateY(-2px);
}

.language-takeaway-card strong,
.takeaway-source {
  font-size: clamp(18px, 1.45vw, 25px);
  line-height: 1.22;
  overflow-wrap: anywhere;
}

.takeaway-chinese {
  min-height: 28px;
  color: var(--ink);
  font-size: clamp(15px, 1.05vw, 18px);
  line-height: 1.42;
  overflow-wrap: anywhere;
}

.language-takeaway-card-wrap.is-concealed .takeaway-source {
  color: var(--muted);
  border-radius: 9px;
  min-height: 34px;
  background: repeating-linear-gradient(
    135deg,
    color-mix(in srgb, var(--muted) 13%, transparent),
    color-mix(in srgb, var(--muted) 13%, transparent) 7px,
    color-mix(in srgb, var(--muted) 5%, transparent) 7px,
    color-mix(in srgb, var(--muted) 5%, transparent) 14px
  );
  text-indent: -9999px;
  user-select: none;
}

.takeaway-review-panel {
  min-height: 82px;
  position: sticky;
  bottom: 0;
  z-index: 12;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--line));
  border-radius: 18px;
  padding: 14px 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 8%, #fff), rgba(255, 255, 255, 0.88)),
    #fff;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
}

.takeaway-review-panel.is-active {
  border-color: color-mix(in srgb, #22c55e 36%, var(--line));
  background:
    linear-gradient(135deg, rgba(34, 197, 94, 0.13), rgba(255, 255, 255, 0.9)),
    #fff;
}

.takeaway-review-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.takeaway-review-copy span {
  color: color-mix(in srgb, var(--accent) 80%, #475569);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.takeaway-review-copy strong {
  color: var(--ink);
  font-size: 20px;
  font-weight: 920;
  line-height: 1.16;
}

.takeaway-review-copy small {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
}

.takeaway-review-start {
  position: relative;
  min-width: 104px;
  min-height: 44px;
  border: 1px solid color-mix(in srgb, #22c55e 50%, var(--line));
  border-radius: 999px;
  background: linear-gradient(180deg, #22c55e, #16a34a);
  color: #fff;
  font-size: 15px;
  font-weight: 900;
  box-shadow: 0 14px 30px rgba(22, 163, 74, 0.22);
  cursor: pointer;
}

.takeaway-review-start:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  filter: grayscale(0.35);
}

.takeaway-review-start-badge {
  position: absolute;
  top: -9px;
  right: -9px;
  min-width: 18px;
  height: 16px;
  padding: 0 5px;
  border-radius: 999px;
  background: #ef4444;
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.14);
  pointer-events: none;
}

.language-takeaway-card-wrap.is-review-due .language-takeaway-card {
  border-color: color-mix(in srgb, #f59e0b 48%, var(--line));
}

.language-takeaway-card-wrap.is-reviewing .language-takeaway-card {
  border-color: color-mix(in srgb, #22c55e 48%, var(--line));
  box-shadow: 0 20px 54px rgba(34, 197, 94, 0.16), 0 12px 32px rgba(15, 23, 42, 0.1);
}

.language-takeaway-card-wrap.is-review-current .language-takeaway-card {
  border-width: 2px;
  border-color: #22c55e;
  transform: translateY(-2px);
}

@keyframes takeawayDuePulse {
  0%, 100% { box-shadow: 0 14px 34px rgba(15, 23, 42, 0.08), 0 0 0 rgba(245, 158, 11, 0); }
  50% { box-shadow: 0 18px 48px rgba(15, 23, 42, 0.12), 0 0 0 4px rgba(245, 158, 11, 0.12); }
}

.language-takeaway-card-wrap.is-review-due .language-takeaway-card {
  animation: takeawayDuePulse 2.2s ease-in-out infinite;
}

/* ── Thinking pixel-brain mascot on the "current" review card ──
   Sits in the card's bottom-right and loops two acts only: scratch-think (with a
   thought bubble) → lightbulb idea. The balloon + fly-off run once on A / D. */
.takeaway-review-mascot {
  position: absolute;
  right: 10px;
  bottom: 10px;
  width: 44px;
  height: 44px;
  pointer-events: none;
  overflow: visible;
  z-index: 4;
}

.tk-brain-icon {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.tk-brain-body {
  fill: #f6bcca;
  stroke: #c46d87;
  stroke-width: 1.4;
  stroke-linejoin: miter;
  shape-rendering: crispEdges;
}

.tk-brain-fold {
  fill: none;
  stroke: #b15775;
  stroke-width: 1.2;
  stroke-linecap: butt;
  opacity: 0.85;
}

.tk-brain-eye { fill: #3a2530; shape-rendering: crispEdges; }
.tk-brain-limb,
.tk-brain-hand { fill: #7c4f5d; shape-rendering: crispEdges; }

.tk-brain-limb-stroke {
  fill: none;
  stroke: #7c4f5d;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.tk-brain-arm-think,
.tk-brain-arm-idea,
.tk-brain-arm-hold,
.tk-brain-hand-right,
.tk-brain-cloud,
.tk-brain-bulb,
.tk-brain-balloon,
.tk-brain-balloon-bob { transform-box: fill-box; }

/* Shared base: hold arm + balloon hidden until a context shows them; the two
   arms/hand/cloud/bulb get their behaviour from a context (.takeaway-review-mascot
   loops; .follow-up-mascot scratches then resolves). */
.tk-brain-arm-hold { opacity: 0; }
.tk-brain-balloon { opacity: 0; transform-origin: bottom center; }
.tk-brain-balloon-bob { transform-origin: bottom center; }
.tk-brain-hand-right { transform-origin: bottom center; }
.tk-brain-cloud { transform-origin: center; }
.tk-brain-bulb { transform-origin: center bottom; }

/* Takeaway review idle loop (5s): act 1 think → act 2 idea. */
.takeaway-review-mascot .tk-brain-arm-think { animation: tkBrainArmThink 5s ease-in-out infinite; }
.takeaway-review-mascot .tk-brain-arm-idea { animation: tkBrainArmIdea 5s ease-in-out infinite; }
.takeaway-review-mascot .tk-brain-hand-right { animation: tkBrainScratch 5s ease-in-out infinite; }
.takeaway-review-mascot .tk-brain-cloud { animation: tkBrainCloud 5s ease-in-out infinite; }
.takeaway-review-mascot .tk-brain-bulb { animation: tkBrainBulb 5s ease-in-out infinite; }
.takeaway-review-mascot .tk-brain-bulb-ray { animation: tkBrainBulbRay 5s ease-in-out infinite; }

.tk-brain-cloud-puff {
  fill: #ffffff;
  stroke: #111827;
  stroke-width: 0.8;
  stroke-linejoin: round;
}

.tk-brain-cloud-dots rect {
  fill: #1f2937;
  opacity: 0;
  /* Square dots pop in left→right, hold, then vanish together, repeat. All three
     share one 1.5s timeline (no per-dot delay) so the disappear stays in sync. */
  animation: tkBrainSeqDot1 1.5s steps(1, end) infinite;
}
.tk-brain-cloud-dots rect:nth-child(2) { animation-name: tkBrainSeqDot2; }
.tk-brain-cloud-dots rect:nth-child(3) { animation-name: tkBrainSeqDot3; }

.tk-brain-bulb-glass { fill: #fde68a; stroke: #f59e0b; stroke-width: 0.8; }
.tk-brain-bulb-base { fill: #9ca3af; }
.tk-brain-bulb-ray {
  stroke: #f59e0b;
  stroke-width: 0.9;
  stroke-linecap: round;
}

.tk-brain-balloon-body {
  fill: var(--tk-balloon-color, #22c55e);
  stroke: rgba(0, 0, 0, 0.16);
  stroke-width: 0.5;
}
.tk-brain-balloon-knot { fill: color-mix(in srgb, var(--tk-balloon-color, #22c55e) 82%, #000); }
.tk-brain-balloon-string {
  fill: none;
  stroke: #94a3b8;
  stroke-width: 0.7;
  stroke-linecap: round;
}

@keyframes tkBrainArmThink {
  0%, 44% { opacity: 1; }
  48% { opacity: 0; }
  95% { opacity: 0; }
  100% { opacity: 1; }
}

@keyframes tkBrainArmIdea {
  0%, 48% { opacity: 0; }
  52% { opacity: 1; }
  95% { opacity: 1; }
  99% { opacity: 0; }
  100% { opacity: 0; }
}

@keyframes tkBrainScratch {
  0% { transform: rotate(0deg); }
  6% { transform: rotate(16deg); }
  12% { transform: rotate(-12deg); }
  18% { transform: rotate(16deg); }
  24% { transform: rotate(-12deg); }
  30% { transform: rotate(14deg); }
  36% { transform: rotate(-10deg); }
  42% { transform: rotate(6deg); }
  46%, 100% { transform: rotate(0deg); }
}

@keyframes tkBrainThinkDot {
  0%, 55%, 100% { transform: translateY(0); }
  28% { transform: translateY(-1.5px); }
}

/* Sequential square-dot loader: dot1→dot2→dot3 appear, all hold, then disappear
   together; the trailing hidden stretch is the pause before the next round. */
@keyframes tkBrainSeqDot1 {
  0%, 100% { opacity: 0; }
  12%, 74% { opacity: 1; }
  80% { opacity: 0; }
}
@keyframes tkBrainSeqDot2 {
  0%, 30% { opacity: 0; }
  32%, 74% { opacity: 1; }
  80%, 100% { opacity: 0; }
}
@keyframes tkBrainSeqDot3 {
  0%, 50% { opacity: 0; }
  52%, 74% { opacity: 1; }
  80%, 100% { opacity: 0; }
}

@keyframes tkBrainCloud {
  0% { opacity: 0; transform: scale(0.3) translateY(3px); }
  8% { opacity: 1; transform: scale(1.06) translateY(0); }
  12% { transform: scale(1); }
  40% { opacity: 1; transform: scale(1); }
  46% { opacity: 0; transform: scale(0.5) translateY(-2px); }
  100% { opacity: 0; transform: scale(0.3); }
}

@keyframes tkBrainBulb {
  0%, 50% { opacity: 0; transform: scale(0.2) translateY(3px); }
  56% { opacity: 1; transform: scale(1.3) translateY(0); }
  60% { transform: scale(0.92); }
  64% { transform: scale(1.08); }
  68% { transform: scale(1); }
  92% { opacity: 1; transform: scale(1); }
  97% { opacity: 0; transform: scale(0.7) translateY(-3px); }
  100% { opacity: 0; transform: scale(0.2); }
}

@keyframes tkBrainBulbRay {
  0%, 54% { opacity: 0; }
  58% { opacity: 1; }
  62% { opacity: 0.3; }
  66% { opacity: 1; }
  92% { opacity: 0.8; }
  96%, 100% { opacity: 0; }
}

/* One-shot fly-off on A / D: idle acts stop, the held balloon shows, the whole
   figure floats up out of the card top and fades — no return. */
.takeaway-review-mascot.is-flying .tk-brain-arm-think,
.takeaway-review-mascot.is-flying .tk-brain-arm-idea,
.takeaway-review-mascot.is-flying .tk-brain-cloud,
.takeaway-review-mascot.is-flying .tk-brain-bulb,
.takeaway-review-mascot.is-flying .tk-brain-bulb-ray {
  animation: none;
  opacity: 0;
}
.takeaway-review-mascot.is-flying .tk-brain-hand-right { animation: none; }
.takeaway-review-mascot.is-flying .tk-brain-arm-hold { opacity: 1; }
.takeaway-review-mascot.is-flying .tk-brain-balloon {
  opacity: 1;
  animation: tkBrainBalloonSway 1.1s ease-in-out infinite;
}
.takeaway-review-mascot.is-flying .tk-brain-icon {
  animation: tkBrainFlyAway 0.9s cubic-bezier(0.45, 0, 0.7, 0.35) forwards;
}
.takeaway-review-mascot.is-flying-a .tk-brain-balloon-body { fill: #22c55e; }
.takeaway-review-mascot.is-flying-a .tk-brain-balloon-knot { fill: color-mix(in srgb, #22c55e 82%, #000); }
.takeaway-review-mascot.is-flying-d .tk-brain-balloon-body { fill: #ef4444; }
.takeaway-review-mascot.is-flying-d .tk-brain-balloon-knot { fill: color-mix(in srgb, #ef4444 82%, #000); }

@keyframes tkBrainBalloonSway {
  0%, 100% { transform: rotate(-3deg); }
  50% { transform: rotate(3deg); }
}

@keyframes tkBrainFlyAway {
  0% { transform: translateY(0) scale(1); opacity: 1; }
  10% { transform: translateY(3px) scale(1.05); opacity: 1; }
  35% { opacity: 1; }
  100% { transform: translateY(-175px) scale(0.92); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .takeaway-review-mascot .tk-brain-icon,
  .takeaway-review-mascot .tk-brain-hand-right,
  .takeaway-review-mascot .tk-brain-cloud,
  .takeaway-review-mascot .tk-brain-cloud-dots rect,
  .takeaway-review-mascot .tk-brain-bulb,
  .takeaway-review-mascot .tk-brain-bulb-ray,
  .takeaway-review-mascot .tk-brain-arm-think,
  .takeaway-review-mascot .tk-brain-arm-idea,
  .takeaway-review-mascot .tk-brain-arm-hold { animation: none; }
  .takeaway-review-mascot .tk-brain-cloud-dots rect { opacity: 1; }
  .takeaway-review-mascot .tk-brain-cloud,
  .takeaway-review-mascot .tk-brain-bulb,
  .takeaway-review-mascot .tk-brain-balloon,
  .takeaway-review-mascot .tk-brain-arm-idea,
  .takeaway-review-mascot .tk-brain-arm-hold { opacity: 0; }
  .takeaway-review-mascot .tk-brain-arm-think { opacity: 1; }
}

/* ── Thinking pixel-brain under the question card while a P1/P3 pressure-mode
   follow-up is being generated. It just scratches its head (thought bubble up)
   until the question arrives; on success it lights the bulb, grabs a balloon and
   floats up out of frame — no return (that turn is ready). ── */
.follow-up-mascot {
  position: absolute;
  left: 0;
  right: 0;
  /* Sit higher (less negative) and a touch smaller than before, per request. */
  bottom: -34px;
  margin: 0 auto;
  width: 90px;
  height: 90px;
  pointer-events: none;
  z-index: 3;
  overflow: visible;
  animation: fuMascotIn 0.4s ease-out;
}

.follow-up-mascot .tk-brain-icon {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

/* Loading: keep scratching, thought bubble visible; everything else hidden. */
.follow-up-mascot .tk-brain-arm-think { opacity: 1; }
.follow-up-mascot .tk-brain-arm-idea,
.follow-up-mascot .tk-brain-bulb,
.follow-up-mascot .tk-brain-bulb-ray { opacity: 0; }
.follow-up-mascot .tk-brain-hand-right { animation: fuScratch 1.8s ease-in-out infinite; }
.follow-up-mascot .tk-brain-cloud { opacity: 1; animation: fuCloudBob 3s ease-in-out infinite; }

/* Success: bulb pops (got it) → grab balloon → float up and gone. */
.follow-up-mascot.is-resolving .tk-brain-hand-right { animation: none; }
.follow-up-mascot.is-resolving .tk-brain-arm-think { animation: none; opacity: 0; }
.follow-up-mascot.is-resolving .tk-brain-cloud { animation: none; opacity: 0; }
.follow-up-mascot.is-resolving .tk-brain-arm-idea { animation: fuIdeaArm 0.6s ease-out forwards; }
.follow-up-mascot.is-resolving .tk-brain-bulb { animation: fuBulbPop 0.65s ease-out forwards; }
.follow-up-mascot.is-resolving .tk-brain-bulb-ray { animation: fuBulbRay 0.65s ease-out forwards; }
.follow-up-mascot.is-resolving .tk-brain-arm-hold { animation: fuHoldArm 1s ease-out 0.5s forwards; }
.follow-up-mascot.is-resolving .tk-brain-balloon { animation: fuBalloonGrab 1s ease-out 0.5s forwards; }
.follow-up-mascot.is-resolving .tk-brain-balloon-bob { animation: tkBrainBalloonSway 1.1s ease-in-out 0.6s infinite; }
.follow-up-mascot.is-resolving .tk-brain-icon { animation: fuFlyAway 0.95s cubic-bezier(0.45, 0, 0.7, 0.35) 0.6s forwards; }

@keyframes fuMascotIn {
  0% { opacity: 0; transform: translateY(8px) scale(0.8); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes fuScratch {
  0%, 100% { transform: rotate(-12deg); }
  25% { transform: rotate(15deg); }
  50% { transform: rotate(-9deg); }
  75% { transform: rotate(15deg); }
}

@keyframes fuCloudBob {
  /* Bake a bigger (scale) + raised (translateY) thought bubble into the bob so it
     reads clearly above the brain during 生成追问. */
  0%, 100% { transform: translateY(-2.6px) scale(1.26); }
  50% { transform: translateY(-3.8px) scale(1.26); }
}

@keyframes fuIdeaArm {
  0% { opacity: 0; }
  15% { opacity: 1; }
  72% { opacity: 1; }
  100% { opacity: 0; }
}

@keyframes fuBulbPop {
  0% { opacity: 0; transform: scale(0.2) translateY(3px); }
  35% { opacity: 1; transform: scale(1.3) translateY(0); }
  50% { transform: scale(0.95); }
  62% { transform: scale(1.06); }
  72% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8) translateY(-3px); }
}

@keyframes fuBulbRay {
  0%, 18% { opacity: 0; }
  35% { opacity: 1; }
  50% { opacity: 0.4; }
  65% { opacity: 1; }
  80% { opacity: 0.6; }
  100% { opacity: 0; }
}

@keyframes fuHoldArm {
  0% { opacity: 0; }
  25% { opacity: 1; }
  100% { opacity: 1; }
}

@keyframes fuBalloonGrab {
  0% { opacity: 0; transform: scale(0.4) translateY(3px); }
  30% { opacity: 1; transform: scale(1.12) translateY(0); }
  45% { transform: scale(0.98); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes fuFlyAway {
  0% { transform: translateY(0) scale(1); opacity: 1; }
  10% { transform: translateY(4px) scale(1.05); opacity: 1; }
  35% { opacity: 1; }
  100% { transform: translateY(-240px) scale(0.9); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .follow-up-mascot,
  .follow-up-mascot .tk-brain-hand-right,
  .follow-up-mascot .tk-brain-cloud,
  .follow-up-mascot .tk-brain-cloud-dots rect { animation: none; }
  .follow-up-mascot .tk-brain-cloud-dots rect { opacity: 1; }
}

.takeaway-review-panel-actions {
  display: inline-grid;
  grid-template-columns: auto minmax(100px, 1fr) minmax(100px, 1fr);
  gap: 10px;
  align-items: center;
}

/* 定位 button: reuses the A/D grade pill styling but rendered as a circle. Jumps
   to the visually topmost card still to practise. A faint "W" watermark sits
   behind the crosshair so the icon reads as "locate" and the backdrop signals
   it's bound to the W key. */
.takeaway-review-grade.is-locate {
  width: 42px;
  min-width: 42px;
  height: 42px;
  min-height: 42px;
  padding: 0;
  border-radius: 50%;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
  color: var(--accent, #2563eb);
}
.takeaway-review-grade.is-locate::before {
  content: "W";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "JetBrains Mono", "SFMono-Regular", ui-monospace, monospace;
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -1px;
  color: currentColor;
  opacity: 0.26;
  pointer-events: none;
}
.takeaway-review-grade.is-locate svg {
  position: relative;
  z-index: 1;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.takeaway-review-grade {
  min-height: 42px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 18px;
  font-weight: 950;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
  cursor: pointer;
}

.takeaway-review-grade span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.takeaway-review-grade.is-mastered {
  border-color: rgba(34, 197, 94, 0.35);
  color: #15803d;
}

.takeaway-review-grade.is-again {
  border-color: rgba(239, 68, 68, 0.28);
  color: #dc2626;
}

.takeaway-review-grade:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  filter: grayscale(0.25);
}

.topbar-review-panel {
  position: static;
  width: min(460px, 42vw);
  min-height: 38px;
  height: 38px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  padding: 4px 6px 4px 12px;
  border-radius: 999px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.10);
  overflow: visible;
}

.topbar-review-panel.is-active {
  grid-template-columns: minmax(0, 1fr) auto;
}

.topbar-review-panel .takeaway-review-copy {
  gap: 0;
}

.topbar-review-panel .takeaway-review-copy span {
  display: none;
}

.topbar-review-panel .takeaway-review-copy strong {
  min-width: 0;
  overflow: hidden;
  font-size: 13px;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topbar-review-panel .takeaway-review-copy small {
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topbar-review-panel .takeaway-review-start {
  min-width: 66px;
  min-height: 30px;
  height: 30px;
  padding: 0 12px;
  font-size: 13px;
  box-shadow: none;
}

.takeaway-review-exit {
  width: 56px;
  height: 56px;
  min-width: 56px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
  color: #fff;
  box-shadow: 0 10px 22px rgba(220, 38, 38, 0.24);
  cursor: pointer;
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.takeaway-review-exit svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.8;
  stroke-linecap: round;
}

.takeaway-review-exit:hover {
  background: linear-gradient(180deg, #f87171 0%, #ef4444 100%);
  box-shadow: 0 10px 20px rgba(220, 38, 38, 0.28);
  transform: translateY(-1px);
}

.takeaway-review-exit:active {
  transform: scale(0.94);
}

.topbar-review-panel .takeaway-review-panel-actions {
  grid-template-columns: repeat(2, 52px);
  gap: 5px;
}

.topbar-review-panel .takeaway-review-grade {
  min-height: 30px;
  height: 30px;
  border-radius: 999px;
  gap: 4px;
  font-size: 14px;
}

.topbar-review-panel .takeaway-review-grade.needs-card {
  opacity: 0.82;
  filter: grayscale(0.12);
  box-shadow: inset 0 0 0 1px rgba(83, 66, 55, 0.08);
}

.topbar-review-panel .takeaway-review-grade span {
  display: none;
}

.takeaway-review-toast {
  position: absolute;
  left: 50%;
  top: calc(100% + 7px);
  z-index: 20;
  min-width: 240px;
  max-width: 420px;
  padding: 9px 14px;
  border: 1.5px solid rgba(83, 66, 55, 0.22);
  border-radius: 12px 14px 12px 15px;
  background: rgba(255, 250, 236, 0.98);
  color: #3b2b22;
  font-size: 13px;
  font-weight: 820;
  text-align: center;
  box-shadow: 3px 4px 0 rgba(83, 66, 55, 0.06), 0 14px 30px rgba(83, 66, 55, 0.12);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -4px);
  transition: opacity 180ms ease, transform 180ms ease;
}

.takeaway-review-toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.spelling-drill-home-card {
  --corpus-card-accent: #0f766e;
}

/* ═════════════════════════════════════════════════════════════════════
   Spelling Drill — Nocturne Reader edition
   Deep night green × warm cream × terracotta accent.
   ═════════════════════════════════════════════════════════════════════ */

@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght,SOFT@9..144,400;9..144,600;9..144,800;9..144,900&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400&family=Caveat:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");

.spelling-drill-panel {
  /* ── Light defaults (clean white / ink) ─────────────────────────── */
  --nr-bg:       #ffffff;
  --nr-bg-2:     #f4f4f5;
  --nr-ink:      #1a2430;
  --nr-ink-dim:  rgba(26, 36, 48, 0.60);
  --nr-ink-mute: rgba(26, 36, 48, 0.35);
  --nr-line:     rgba(26, 36, 48, 0.10);
  --nr-clay:     #3b7dd8;
  --nr-clay-soft:#6099e4;
  --nr-sage:     #2d7a55;
  --nr-rose:     #c0392b;
  --nr-noise-opacity: 0.04;
  --nr-noise-blend: multiply;
  --nr-halo-1: transparent;
  --nr-halo-2: transparent;

  --nr-serif-display: "Fraunces", "Songti SC", "Source Han Serif SC", Georgia, serif;
  --nr-serif-body:    "Newsreader", "Songti SC", "Source Han Serif SC", Georgia, serif;
  --nr-hand:          "Caveat", "Newsreader", "Songti SC", "Source Han Serif SC", cursive;
  --nr-mono:          "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  background: var(--nr-bg);
  color: var(--nr-ink);
  position: relative;
  overflow: hidden;
}

/* ── Dark variant (driven by global body.theme-dark) ─────────────── */
body.theme-dark .spelling-drill-panel {
  --nr-bg:       #0d1b1e;
  --nr-bg-2:     #122428;
  --nr-ink:      #f5ede0;
  --nr-ink-dim:  rgba(245, 237, 224, 0.62);
  --nr-ink-mute: rgba(245, 237, 224, 0.38);
  --nr-line:     rgba(245, 237, 224, 0.14);
  --nr-clay:     #d97757;
  --nr-clay-soft:#e9a98a;
  --nr-sage:     #94c5a6;
  --nr-rose:     #e26d6d;
  --nr-noise-opacity: 0.22;
  --nr-noise-blend: overlay;
  --nr-halo-1: rgba(217, 119, 87, 0.16);
  --nr-halo-2: rgba(148, 197, 166, 0.08);
}
body.theme-dark .spelling-drill-panel {
  background: var(--nr-bg) !important;
}

/* Paper-grain noise + lamp halo. Pure CSS, no images. */
.spelling-drill-panel::before {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  background-image:
    radial-gradient(900px 520px at 22% -10%, var(--nr-halo-1), transparent 60%),
    radial-gradient(700px 600px at 110% 12%, var(--nr-halo-2), transparent 60%);
  z-index: 0;
}
.spelling-drill-panel::after {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  opacity: var(--nr-noise-opacity);
  mix-blend-mode: var(--nr-noise-blend);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.3  0 0 0 0 0.25  0 0 0 0 0.2  0 0 0 0.55 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  background-size: 180px 180px;
  z-index: 0;
}

.spelling-drill-panel > * { position: relative; z-index: 1; }

/* ── Full-height layout via pure GRID STRETCH ──────────────────────
   No percentage-height chains, no flex:1 fragility. Every level is a
   grid whose child stretches to fill. Parent (.language-takeaway-panel)
   already has a definite height, so 1fr tracks resolve cleanly. */
.spelling-drill-panel {
  height: 100%;                   /* fill the definite-height parent (888px block) */
  display: grid;
  grid-template-rows: 1fr;        /* shell stretches to fill the panel */
  min-height: 0;
}
.spelling-drill-shell {
  display: grid;
  grid-template-rows: auto 1fr;   /* row0 = header, row1 = card area */
  justify-items: center;          /* center content horizontally */
  /* align-items defaults to STRETCH → card fills row1 vertically */
  width: 100%;
  min-height: 0;
  margin: 0;
  padding: 28px 24px 40px;
  background: transparent;
  border: none;
  box-shadow: none;
  gap: 20px;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--nr-ink-mute) transparent;
}
.spelling-drill-shell::-webkit-scrollbar { width: 8px; }
.spelling-drill-shell::-webkit-scrollbar-track { background: transparent; }
.spelling-drill-shell::-webkit-scrollbar-thumb {
  background: var(--nr-line);
  border-radius: 999px;
}
.spelling-drill-shell::-webkit-scrollbar-thumb:hover { background: var(--nr-ink-mute); }
.spelling-drill-shell > * {
  width: 100%;
  max-width: 760px;
}

/* Card container: grid row1, stretches. Holds .nr-card / .nr-stage. */
#spellingPracticeCard {
  min-height: 0;
  display: grid;
  grid-template-rows: 1fr;        /* single child stretches to fill */
}

/* Library list: same stretching row when library view is active */
#spellingDrillList {
  min-height: 0;
  overflow-y: auto;
}

/* CRITICAL: id-level display rules above override the `hidden` attribute's
   UA display:none. Restore hiding explicitly so view-switching works. */
#spellingPracticeCard[hidden],
#spellingDrillList[hidden] {
  display: none !important;
}

/* Head: title + scope tabs */
.spelling-drill-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  border: 0;
  padding: 0;
  background: transparent;
}
.spelling-drill-head > div:first-child h2 {
  font-family: var(--nr-serif-display);
  font-weight: 900;
  font-variation-settings: "SOFT" 50, "opsz" 96;
  font-size: 26px;
  line-height: 1.05;
  letter-spacing: -0.01em;
  color: var(--nr-ink);
  margin: 0 0 4px;
}
.spelling-drill-head > div:first-child h2::after {
  /* Hand-drawn underline */
  content: "";
  display: block;
  width: 58px;
  height: 6px;
  margin-top: 4px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 86 8'><path d='M2 5 Q 18 1, 34 4 T 66 4 T 84 3' fill='none' stroke='%23d97757' stroke-width='2' stroke-linecap='round'/></svg>");
  background-repeat: no-repeat;
}
.spelling-drill-head > div:first-child p {
  font-family: var(--nr-serif-body);
  font-style: italic;
  font-size: 14px;
  color: var(--nr-ink-dim);
  margin: 0;
  max-width: 36ch;
}

.spelling-drill-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
}
#spellingDrillStats {
  font-family: var(--nr-mono);
  font-size: 11px;
  letter-spacing: 0.03em;
  color: var(--nr-ink-mute);
  text-transform: uppercase;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.nr-stat b {
  color: var(--nr-ink);
  font-weight: 600;
  margin-right: 2px;
}
.nr-stat-dot { color: var(--nr-ink-mute); }

/* Scope tabs */
.spelling-scope-switch {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--nr-line);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.18);
}
.spelling-scope-switch button {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--nr-ink-dim);
  font-family: var(--nr-serif-body);
  font-size: 13px;
  letter-spacing: 0.04em;
  padding: 7px 16px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 32px;
  transition: color .2s ease, background .2s ease;
}
.spelling-scope-switch button:hover { color: var(--nr-ink); }
.spelling-scope-switch button.is-active {
  background: var(--nr-ink);
  color: var(--nr-bg);
  font-weight: 600;
}

.spelling-drill-status {
  font-family: var(--nr-serif-body);
  font-size: 13px;
  color: var(--nr-ink-dim);
  min-height: 18px;
  font-style: italic;
}
.spelling-drill-status.error { color: var(--nr-rose); font-style: normal; }

/* Layout — no split. Card centred, library overlays. */
.spelling-drill-layout {
  display: block;
  position: relative;
  min-height: 0;
}
.spelling-practice-card,
.spelling-word-list {
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 0;
}
.spelling-word-list[hidden],
.spelling-practice-card[hidden] { display: none; }

/* ─── Drill card ─────────────────────────────────────────────────── */
.nr-card {
  /* Grid distributes the 4 sections across the full height:
     row0 head (top) · row1 prompt (1fr, fills middle) · row2 body · row3 meta (bottom) */
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr auto auto;
}
@keyframes nr-card-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

.nr-card-head {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
}
.nr-progress {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 12px;
}
.nr-progress-track {
  flex: 1;
  height: 6px;
  background: var(--nr-line);
  border-radius: 999px;
  overflow: hidden;
}
.nr-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--nr-clay-soft), var(--nr-clay));
  border-radius: 999px;
  transition: width .5s cubic-bezier(.2,.7,.2,1);
  min-width: 6px;
  /* Clay is now blue in light mode; dark mode keeps its own clay vars */
}
.nr-progress-text {
  font-family: var(--nr-mono);
  font-size: 11px;
  color: var(--nr-ink-dim);
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.nr-progress-text b { color: var(--nr-ink); font-weight: 600; }
.nr-requeue { color: var(--nr-clay); font-style: normal; margin-left: 4px; }

.nr-lib-btn {
  appearance: none;
  border: 1px solid var(--nr-line);
  background: transparent;
  color: var(--nr-ink-dim);
  font-family: var(--nr-serif-body);
  font-size: 12px;
  padding: 7px 12px;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  transition: color .2s, border-color .2s;
}
.nr-lib-btn:hover { color: var(--nr-ink); border-color: var(--nr-ink-dim); }

/* Prompt — the hero */
/* Prompt grows to fill the middle — centers word + pill vertically */
.nr-prompt {
  flex: 1 1 0%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  margin: 0;
  padding: 20px 0;
  gap: 12px;
}
.nr-gloss {
  font-family: var(--nr-serif-display);
  font-weight: 800;
  font-variation-settings: "SOFT" 30, "opsz" 144;
  font-size: clamp(30px, 5.2vw, 44px);
  line-height: 1.08;
  letter-spacing: -0.015em;
  color: var(--nr-ink);
  margin: 0 0 8px;
  animation: nr-gloss-in .5s cubic-bezier(.2,.7,.2,1) both .08s;
}
@keyframes nr-gloss-in {
  from { opacity: 0; transform: translateY(8px); letter-spacing: 0; }
  to   { opacity: 1; transform: translateY(0); letter-spacing: -0.015em; }
}

.nr-wrong-pill {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  padding: 4px 14px 5px;
  border: 1px dashed rgba(176, 69, 69, 0.5);
  border-radius: 999px;
  background: rgba(176, 69, 69, 0.06);
  margin-bottom: 6px;
}
.nr-wrong-tag {
  font-family: var(--nr-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nr-rose);
  opacity: 0.85;
}
.nr-wrong-text {
  font-family: var(--nr-hand);
  font-size: 24px;
  font-weight: 600;
  color: var(--nr-ink);
  text-decoration: line-through;
  text-decoration-color: var(--nr-rose);
  text-decoration-thickness: 2px;
  letter-spacing: 0.5px;
}

/* Optional first-letter hint (only shown after user clicks "首字母") */
.nr-hint-letter {
  font-family: var(--nr-serif-body);
  font-style: italic;
  font-size: 13px;
  color: var(--nr-ink-dim);
  margin: 12px 0 0;
}
.nr-hint-letter b {
  font-family: var(--nr-hand);
  font-style: normal;
  font-size: 26px;
  color: var(--nr-clay);
  margin-left: 6px;
  font-weight: 700;
  letter-spacing: 0.05em;
  vertical-align: -2px;
}

/* Fallback prompt when no Chinese gloss — reads as a hint, NEVER leaks the word */
.nr-gloss.is-fallback {
  font-family: var(--nr-serif-body);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(18px, 3vw, 24px);
  color: var(--nr-ink-dim);
  letter-spacing: 0;
}

/* Stable slot — input and answer use the exact same dimensions so siblings
   below (stage dots, tools) never shift when Enter is pressed. */
.nr-slot {
  margin: 4px auto 0;
  max-width: 460px;
  width: 100%;
  min-height: 144px;
  display: grid;
  grid-template-rows: auto auto auto;
  align-content: start;
  justify-items: center;
  row-gap: 8px;
  text-align: center;
}

.nr-form { padding: 4px 6px; }
.nr-form-spacer {
  /* Reserves the vertical slot the answer block will later occupy */
  display: block;
  height: 70px;
  width: 1px;
}
.nr-input {
  width: 100%;
  appearance: none;
  background: transparent;
  border: 0;
  border-bottom: 1.5px solid var(--nr-ink-mute);
  color: var(--nr-ink);
  font-family: var(--nr-hand);
  font-size: 40px;
  font-weight: 500;
  padding: 4px 6px 8px;
  letter-spacing: 0.5px;
  text-align: center;
  transition: border-color .25s ease;
  caret-color: var(--nr-clay);
  outline: none;
  line-height: 1.2;
  grid-row: 1;
}
.nr-input::placeholder {
  color: var(--nr-ink-mute);
  font-family: var(--nr-serif-body);
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0;
  font-size: 15px;
}
.nr-input:focus { border-bottom-color: var(--nr-clay); }
.nr-input:focus::placeholder { opacity: 0.5; }

/* Meta row: stage + tools */
.nr-drill-body {
  flex-shrink: 0;
  width: 100%;
}

.nr-meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-top: auto;   /* push to bottom of flex card */
  padding-top: 14px;
  border-top: 1px solid var(--nr-line);
  flex-wrap: wrap;
  flex-shrink: 0;
}
.nr-stage-track {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--nr-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nr-ink-mute);
}
.nr-stage-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  border: 1px solid var(--nr-ink-mute);
}
.nr-stage-dot.is-on {
  background: var(--nr-sage);
  border-color: var(--nr-sage);
}
.nr-stage-text { margin-left: 6px; }

.nr-tools {
  display: inline-flex;
  gap: 4px;
  flex-wrap: wrap;
}
.nr-tool {
  appearance: none;
  background: transparent;
  border: 0;
  color: var(--nr-ink-dim);
  font-family: var(--nr-serif-body);
  font-size: 12px;
  font-style: italic;
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 6px;
  min-height: 28px;
  transition: color .2s, background .2s;
}
.nr-tool:hover { color: var(--nr-ink); background: rgba(245, 237, 224, 0.06); }

/* Inline answer — drops into the same .nr-slot the input occupied. */
.nr-answer {
  border-bottom: 1.5px solid var(--nr-line);
  padding: 4px 6px 14px;
  animation: nr-answer-in .35s cubic-bezier(.2,.7,.2,1) both;
}
@keyframes nr-answer-in {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}
.nr-answer-line {
  font-family: var(--nr-hand);
  font-size: 40px;
  font-weight: 500;
  letter-spacing: 0.5px;
  line-height: 1.2;
  margin: 0;
  text-align: center;
  word-break: break-all;
  grid-row: 1;
  width: 100%;
}
.nr-answer.is-correct .nr-answer-line { color: var(--nr-sage); }
.nr-answer.is-wrong   .nr-answer-line { color: var(--nr-rose); }

/* Per-letter colour (overrides parent line colour) */
.nr-letter { display: inline-block; }
.nr-letter.is-ok  { color: var(--nr-sage); }
.nr-letter.is-bad {
  color: var(--nr-rose);
  text-decoration: underline wavy;
  text-decoration-color: var(--nr-rose);
  text-underline-offset: 6px;
  text-decoration-thickness: 1.5px;
}
.nr-letter.is-miss {
  color: var(--nr-ink-mute);
  opacity: 0.55;
}

.nr-answer-correct {
  font-family: var(--nr-serif-body);
  font-size: 14px;
  color: var(--nr-ink-dim);
  margin: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 10px;
  grid-row: 2;
  min-height: 32px;
}
.nr-answer-correct--placeholder { visibility: hidden; }

/* ── Wrong-state retry group ──────────────────────────────────────── */
/* Container that stacks the original wrong answer + retry input/result */
.nr-answer-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
/* Retry input form inside the wrong-state group */
.nr-retry-form {
  padding: 2px 6px;
  border-top: 1px dashed var(--nr-line);
  padding-top: 8px;
}
/* Retry answer line (same Caveat size as main answer line, but separated) */
.nr-retry-line {
  font-family: var(--nr-hand);
  font-size: clamp(28px, 4.5vw, 40px);
  line-height: 1.25;
  padding: 6px 6px 2px;
  border-top: 1px dashed var(--nr-line);
}
.nr-answer-tag {
  font-family: var(--nr-mono);
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--nr-ink-mute);
}
.nr-answer-word {
  font-family: var(--nr-hand);
  font-size: 30px;
  font-weight: 600;
  color: var(--nr-sage);
  letter-spacing: 0.3px;
  line-height: 1;
}

.nr-next-btn {
  appearance: none;
  margin: 0;
  grid-row: 3;
  background: transparent;
  border: 1px solid var(--nr-ink-mute);
  color: var(--nr-ink);
  font-family: var(--nr-serif-body);
  font-size: 13px;
  padding: 8px 18px;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  transition: background .2s, border-color .2s, color .2s;
}
.nr-next-btn:hover { background: var(--nr-ink); color: var(--nr-bg); border-color: var(--nr-ink); }
.nr-next-btn:focus-visible { outline: 2px solid var(--nr-clay); outline-offset: 3px; }
.nr-next-btn kbd {
  font-family: var(--nr-mono);
  font-size: 11px;
  padding: 1px 6px;
  border: 1px solid currentColor;
  border-radius: 4px;
  opacity: 0.7;
}

/* ─── Loading / empty / done stages ──────────────────────────────── */
.nr-stage {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  flex: 1;           /* fills #spellingPracticeCard when shown */
  min-height: 320px;
  gap: 14px;
  padding: 24px;
}

.nr-stage-empty .nr-empty-add {
  position: absolute;
  top: 18px;
  right: 18px;
}

.nr-stage-empty .nr-empty-add svg {
  pointer-events: none;
}

.nr-spinner {
  display: inline-flex;
  gap: 6px;
}
.nr-spinner span {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--nr-clay);
  animation: nr-bounce 1s infinite ease-in-out;
}
.nr-spinner span:nth-child(2) { animation-delay: .15s; }
.nr-spinner span:nth-child(3) { animation-delay: .3s; }
@keyframes nr-bounce {
  0%, 80%, 100% { transform: scale(.5); opacity: .4; }
  40% { transform: scale(1); opacity: 1; }
}
.nr-meta {
  font-family: var(--nr-serif-body);
  font-style: italic;
  color: var(--nr-ink-dim);
  font-size: 14px;
}

.nr-empty-mark, .nr-done-seal svg {
  color: var(--nr-clay-soft);
  width: 88px;
  height: 88px;
}
.nr-empty-title, .nr-done-title {
  font-family: var(--nr-serif-display);
  font-weight: 700;
  font-size: 26px;
  margin: 4px 0 0;
  color: var(--nr-ink);
}
.nr-empty-sub, .nr-done-meta {
  font-family: var(--nr-serif-body);
  font-size: 14px;
  color: var(--nr-ink-dim);
  max-width: 28em;
}
.nr-done-meta b { color: var(--nr-ink); font-weight: 600; }

.nr-empty-actions {
  display: flex;
  gap: 10px;
  margin-top: 8px;
  flex-wrap: wrap;
  justify-content: center;
}
.nr-btn {
  appearance: none;
  border: 0;
  font-family: var(--nr-serif-body);
  font-size: 14px;
  padding: 10px 20px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 38px;
  transition: transform .2s, background .2s, color .2s;
}
.nr-btn-primary {
  background: var(--nr-clay);
  color: var(--nr-bg);
  font-weight: 600;
}
.nr-btn-primary:hover { background: var(--nr-clay-soft); transform: translateY(-1px); }
.nr-btn-ghost {
  background: transparent;
  border: 1px solid var(--nr-line);
  color: var(--nr-ink-dim);
}
.nr-btn-ghost:hover { color: var(--nr-ink); border-color: var(--nr-ink-dim); }

/* ─── Library overlay ────────────────────────────────────────────── */
.spelling-word-list {
  position: relative;
  animation: nr-card-in .35s cubic-bezier(.2,.7,.2,1) both;
}
.nr-lib-head {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--nr-line);
}
.nr-lib-back {
  appearance: none;
  background: transparent;
  border: 1px solid var(--nr-line);
  color: var(--nr-ink-dim);
  font-family: var(--nr-serif-body);
  font-size: 13px;
  padding: 6px 12px;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 30px;
  transition: color .2s, border-color .2s;
}
.nr-lib-back:hover { color: var(--nr-ink); border-color: var(--nr-ink-dim); }
.nr-lib-title {
  font-family: var(--nr-serif-display);
  font-size: 18px;
  color: var(--nr-ink);
  font-weight: 600;
}
.nr-lib-group { margin-bottom: 28px; }
.nr-lib-group-title {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--nr-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--nr-ink-mute);
  margin: 0 0 12px;
  font-weight: 500;
}
.nr-lib-group-title em {
  font-family: var(--nr-serif-body);
  font-style: normal;
  font-size: 11px;
  color: var(--nr-ink-dim);
}
.nr-lib-list { list-style: none; margin: 0; padding: 0; }
.nr-lib-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px solid var(--nr-line);
}
.nr-lib-main { flex: 1; display: grid; gap: 2px; min-width: 0; }
.nr-lib-word {
  font-family: var(--nr-hand);
  font-weight: 600;
  font-size: 26px;
  color: var(--nr-ink);
  letter-spacing: 0.3px;
  line-height: 1.1;
}
.nr-lib-gloss {
  font-family: var(--nr-serif-body);
  font-size: 13px;
  color: var(--nr-ink-dim);
}
.nr-lib-wrong {
  font-family: var(--nr-hand);
  font-size: 16px;
  color: var(--nr-ink-mute);
  text-decoration: line-through;
  text-decoration-color: rgba(226, 109, 109, 0.6);
  text-decoration-thickness: 1.5px;
  letter-spacing: 0.2px;
}
.nr-lib-side {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.nr-lib-stage {
  font-family: var(--nr-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--nr-ink-mute);
  margin-right: 6px;
}
.nr-lib-act {
  appearance: none;
  border: 1px solid var(--nr-line);
  background: transparent;
  color: var(--nr-ink-dim);
  width: 28px; height: 28px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  transition: color .2s, border-color .2s, background .2s;
}
.nr-lib-act:hover { color: var(--nr-ink); border-color: var(--nr-ink-dim); }
.nr-lib-act.is-danger:hover { color: var(--nr-rose); border-color: var(--nr-rose); }
.nr-lib-master-btn {
  width: auto;
  min-width: 88px;
  padding: 0 12px;
  border-radius: 999px;
  font-size: 12px;
  color: #2563eb;
  border-color: rgba(37, 99, 235, 0.28);
  background: rgba(37, 99, 235, 0.08);
}
.nr-lib-master-btn:hover {
  color: #1d4ed8;
  border-color: rgba(37, 99, 235, 0.48);
  background: rgba(37, 99, 235, 0.14);
}
.nr-lib-mastered {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 12px;
  color: #047857;
  background: rgba(4, 120, 87, 0.1);
  border: 1px solid rgba(4, 120, 87, 0.22);
}
.nr-lib-empty {
  font-family: var(--nr-serif-body);
  font-style: italic;
  color: var(--nr-ink-dim);
  text-align: center;
  padding: 80px 16px;
}

/* ─── Responsive ─────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .spelling-drill-shell { padding: 20px 16px 40px; gap: 18px; }
  .spelling-drill-head > div:first-child h2 { font-size: 30px; }
  .nr-gloss { font-size: clamp(34px, 9vw, 48px); }
  .nr-mask-char { font-size: 18px; min-width: 14px; }
  .nr-input { font-size: 18px; }
  .nr-card-head { margin-bottom: 22px; }
}

/* Spelling Drill rewrite v2: compact app-card workspace, overrides Nocturne stage. */
.spelling-drill-panel {
  --sd-bg: var(--bg);
  --sd-card: var(--panel);
  --sd-card-soft: color-mix(in srgb, var(--panel) 92%, var(--bg));
  --sd-ink: var(--ink);
  --sd-muted: var(--muted);
  --sd-faint: color-mix(in srgb, var(--muted) 72%, transparent);
  --sd-line: var(--line);
  --sd-accent: var(--accent);
  --sd-accent-strong: var(--accent-dark);
  --sd-accent-soft: color-mix(in srgb, var(--accent) 12%, transparent);
  --sd-good: #15803d;
  --sd-bad: #dc2626;
  --sd-warn: #b45309;
  --sd-shadow: var(--shadow-xs);
  height: 100% !important;
  min-height: 0 !important;
  overflow: hidden !important;
  color: var(--sd-ink) !important;
  background: var(--sd-bg) !important;
}

body.theme-dark .spelling-drill-panel {
  --sd-bg: var(--bg);
  --sd-card: color-mix(in srgb, var(--dark-panel-top) 76%, var(--dark-panel-bottom));
  --sd-card-soft: var(--dark-surface);
  --sd-ink: var(--ink);
  --sd-muted: var(--muted);
  --sd-faint: color-mix(in srgb, var(--muted) 72%, transparent);
  --sd-line: var(--dark-border);
  --sd-accent: var(--dark-primary);
  --sd-accent-strong: var(--dark-primary-strong);
  --sd-accent-soft: var(--dark-primary-soft);
  --sd-good: #86efac;
  --sd-bad: #fca5a5;
  --sd-warn: #fdba74;
  --sd-shadow: var(--dark-shadow);
  background:
    linear-gradient(135deg, var(--dark-bg-start), var(--dark-bg-end)) !important;
}

.spelling-drill-panel::before,
.spelling-drill-panel::after {
  content: none !important;
  display: none !important;
}

.spelling-drill-shell {
  width: min(1040px, 100%) !important;
  height: 100% !important;
  min-height: 0 !important;
  margin: 0 auto !important;
  padding: 18px 22px 22px !important;
  display: grid !important;
  grid-template-rows: auto auto minmax(0, 1fr) !important;
  align-content: stretch !important;
  gap: 12px !important;
  justify-items: stretch !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

.spelling-drill-shell > * {
