/* Single source of truth for the drill word size: the typed input and the
   post-Enter answer line MUST stay visually identical. Change it here only —
   .nr-answer-line is defined in several later blocks that all reference it. */
:root {
  --sd-word-size: clamp(22px, 2.2vw, 30px);
  --sd-word-weight: 760;
}

.nr-input {
  width: 100% !important;
  min-height: 50px !important;
  border: 2px solid color-mix(in srgb, var(--sd-accent) 30%, var(--sd-line)) !important;
  border-radius: var(--radius-md) !important;
  background: var(--sd-card-soft) !important;
  color: var(--sd-ink) !important;
  padding: 0 20px !important;
  text-align: center !important;
  font-family: inherit !important;
  font-size: var(--sd-word-size) !important;
  font-weight: var(--sd-word-weight) !important;
  letter-spacing: 0 !important;
}

.nr-input::placeholder {
  color: var(--sd-faint) !important;
  font-family: inherit !important;
  font-size: 15px !important;
  font-weight: 650 !important;
}

.nr-input:focus {
  outline: none !important;
  border-color: var(--sd-accent) !important;
  box-shadow: 0 0 0 4px var(--sd-accent-soft) !important;
}

.nr-result-slot {
  grid-template-rows: 124px 42px !important;
  align-items: center !important;
}

.nr-answer {
  min-height: 124px !important;
  height: 124px !important;
  border: 1px solid var(--sd-line) !important;
  border-radius: var(--radius-md) !important;
  background: var(--sd-card-soft) !important;
  padding: 10px 12px !important;
  display: grid !important;
  align-content: center !important;
  justify-items: center !important;
  overflow: visible !important;
}

