/* Spelling Drill final layout: app-card structure with fixed vertical slots. */
.spelling-drill-panel {
  --sd-bg: var(--bg);
  --sd-card: var(--panel);
  --sd-card-soft: color-mix(in srgb, var(--panel) 94%, var(--bg));
  --sd-ink: var(--ink);
  --sd-muted: var(--muted);
  --sd-faint: color-mix(in srgb, var(--muted) 68%, transparent);
  --sd-line: var(--line);
  --sd-accent: var(--accent);
  --sd-accent-strong: var(--accent-dark);
  --sd-accent-soft: color-mix(in srgb, var(--accent) 12%, transparent);
  --sd-good: #15803d;
  --sd-bad: #dc2626;
  --sd-warn: #b45309;
  height: 100% !important;
  min-height: 0 !important;
  overflow: hidden !important;
  background: var(--sd-bg) !important;
  color: var(--sd-ink) !important;
}

body.theme-dark .spelling-drill-panel {
  --sd-bg: var(--bg);
  --sd-card: var(--dark-surface);
  --sd-card-soft: color-mix(in srgb, var(--dark-surface) 84%, var(--dark-bg-start));
  --sd-ink: var(--ink);
  --sd-muted: var(--muted);
  --sd-faint: color-mix(in srgb, var(--muted) 64%, transparent);
  --sd-line: var(--dark-border);
  --sd-accent: var(--dark-primary);
  --sd-accent-strong: var(--dark-primary-strong);
  --sd-accent-soft: var(--dark-primary-soft);
  --sd-good: #86efac;
  --sd-bad: #fca5a5;
  --sd-warn: #fdba74;
}

.spelling-drill-panel::before,
.spelling-drill-panel::after {
  content: none !important;
  display: none !important;
}

.spelling-drill-shell {
  width: 100% !important;
  max-width: none !important;
  height: 100% !important;
  min-height: 0 !important;
  margin: 0 auto !important;
  padding: 0 18px 20px !important;
  display: grid !important;
  grid-template-rows: 54px 0 minmax(0, 1fr) !important;
  gap: 10px !important;
  overflow: hidden !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

.spelling-drill-shell > * {
  width: 100% !important;
  max-width: none !important;
}

.spelling-drill-head {
  min-height: 54px !important;
  padding: 8px 14px !important;
  display: grid !important;
  grid-template-columns: minmax(140px, 1fr) minmax(0, auto) !important;
  align-items: center !important;
  gap: 16px !important;
  border: 1px solid var(--sd-line) !important;
  border-radius: 16px !important;
  background: var(--sd-card) !important;
  box-shadow: var(--shadow-xs) !important;
}

.spelling-drill-head > div:first-child {
  min-width: 0 !important;
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
}

.spelling-drill-head > div:first-child h2 {
  margin: 0 !important;
  color: var(--sd-ink) !important;
  font: 820 22px/1.12 inherit !important;
  letter-spacing: 0 !important;
  white-space: nowrap !important;
}

.spelling-drill-head > div:first-child h2::after {
  content: none !important;
  display: none !important;
}

.spelling-drill-head > div:first-child p {
  display: none !important;
}

.spelling-drill-actions {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  gap: 10px !important;
  min-width: 0 !important;
  max-width: 100% !important;
  overflow: hidden !important;
}

#spellingDrillStats {
  display: flex !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  justify-content: flex-end !important;
  gap: 6px !important;
  min-width: 0 !important;
  flex: 1 1 auto !important;
  overflow: hidden !important;
