.language-takeaway-trigger {
  position: fixed;
  z-index: 500;
  width: 34px;
  height: 34px;
  min-height: 34px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent) 78%, #fff);
  background: var(--accent);
  color: #fff;
  padding: 0;
  display: grid;
  place-items: center;
  font-size: 14px;
  font-weight: 850;
  line-height: 1;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.22);
}

.language-takeaway-popup {
  position: fixed;
  z-index: 510;
  width: min(560px, calc(100vw - 24px));
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel);
  box-shadow: 0 22px 70px rgba(15, 23, 42, 0.28);
  padding: 16px 18px;
  display: grid;
  gap: 12px;
}

.language-takeaway-popup header {
  cursor: move;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.language-takeaway-popup header button {
  width: 32px;
  height: 32px;
  min-height: 32px;
  padding: 0;
  border-radius: 999px;
}

.language-takeaway-head-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 0 0 auto;
}

.language-takeaway-popup header .language-takeaway-practice-btn {
  width: auto;
  min-width: 112px;
  height: 32px;
  min-height: 32px;
  padding: 0 12px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent, #2563eb) 28%, var(--line));
  background: color-mix(in srgb, var(--accent, #2563eb) 10%, var(--panel));
  color: color-mix(in srgb, var(--accent, #2563eb) 76%, var(--ink));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 850;
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease;
}

.language-takeaway-popup header .language-takeaway-practice-btn svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.language-takeaway-popup header .language-takeaway-practice-btn:hover {
  background: color-mix(in srgb, var(--accent, #2563eb) 16%, var(--panel));
  border-color: color-mix(in srgb, var(--accent, #2563eb) 48%, var(--line));
}

.language-takeaway-popup header .language-takeaway-practice-btn:active {
  transform: translateY(1px) scale(0.98);
}

/* Circular browser-TTS button that replaced the close button. Reuses the
   header-button circle; speaker icon is drawn with currentColor strokes. */
.language-takeaway-tts-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  background: var(--panel-2, var(--panel));
  color: var(--accent, #2563eb);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.1s ease;
}
.language-takeaway-tts-btn svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.language-takeaway-tts-btn svg path:first-child {
  fill: currentColor;
  stroke: none;
}
.language-takeaway-tts-btn:hover {
  background: color-mix(in srgb, var(--accent, #2563eb) 12%, var(--panel));
}
.language-takeaway-tts-btn:active { transform: scale(0.94); }
.language-takeaway-tts-btn:disabled {
  cursor: progress;
}
.language-takeaway-tts-btn.is-loading {
  position: relative;
  color: color-mix(in srgb, var(--accent, #2563eb) 58%, var(--muted));
  background: color-mix(in srgb, var(--accent, #2563eb) 10%, var(--panel));
}
.language-takeaway-tts-btn.is-loading::after {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid color-mix(in srgb, var(--accent, #2563eb) 18%, transparent);
  border-top-color: currentColor;
  border-radius: inherit;
  animation: takeaway-tts-spin 0.72s linear infinite;
}
.language-takeaway-tts-btn.is-loading svg {
  opacity: 0.42;
}
.language-takeaway-tts-btn.is-speaking {
  background: color-mix(in srgb, var(--accent, #2563eb) 18%, var(--panel));
  animation: takeaway-tts-pulse 1s ease-in-out infinite;
}
@keyframes takeaway-tts-spin {
  to { transform: rotate(360deg); }
}
@keyframes takeaway-tts-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent, #2563eb) 40%, transparent); }
  50% { box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent, #2563eb) 0%, transparent); }
}

.takeaway-pronunciation-dialog {
  position: fixed;
  inset: 0;
  z-index: 560;
  display: grid;
  place-items: center;
  padding: 24px;
}

.takeaway-pronunciation-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.26);
  backdrop-filter: blur(2px);
}

.takeaway-pronunciation-card {
  position: relative;
  z-index: 1;
  width: min(620px, calc(100vw - 28px));
  max-height: calc(100vh - 48px);
  overflow: auto;
  border: 1px solid color-mix(in srgb, var(--accent, #2563eb) 18%, var(--line));
  border-radius: 18px;
  background:
    radial-gradient(circle at 86% 8%, color-mix(in srgb, var(--accent, #2563eb) 12%, transparent), transparent 32%),
    var(--panel);
  box-shadow: 0 26px 70px rgba(15, 23, 42, 0.34);
  padding: 18px;
  display: grid;
  gap: 14px;
}

.takeaway-pronunciation-card header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.takeaway-pronunciation-card header span,
.takeaway-pronunciation-target small,
.takeaway-pronunciation-transcript small {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.takeaway-pronunciation-card h3 {
  margin: 2px 0 0;
  font-size: 22px;
  line-height: 1.15;
}

.takeaway-pronunciation-close {
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--panel-2, var(--panel));
  color: var(--ink);
  display: grid;
  place-items: center;
  padding: 0;
  cursor: pointer;
}

.takeaway-pronunciation-close svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.1;
  stroke-linecap: round;
}

.takeaway-pronunciation-target {
  border: 1px solid color-mix(in srgb, var(--accent, #2563eb) 18%, var(--line));
  border-radius: 14px;
  background: color-mix(in srgb, var(--accent, #2563eb) 6%, var(--panel));
  padding: 13px 14px;
}

.takeaway-pronunciation-target p {
  margin: 6px 0 0;
  color: var(--ink);
  font-size: 18px;
  font-weight: 760;
  line-height: 1.5;
}

.takeaway-pronunciation-result {
  display: grid;
  gap: 12px;
}

.takeaway-pronunciation-scores {
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
}

.takeaway-pronunciation-score-main {
  min-height: 112px;
  border-radius: 16px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent, #2563eb) 22%, var(--panel)), color-mix(in srgb, #10b981 16%, var(--panel)));
  border: 1px solid color-mix(in srgb, var(--accent, #2563eb) 22%, var(--line));
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
}

.takeaway-pronunciation-score-main strong {
  font-size: 36px;
  line-height: 1;
}

.takeaway-pronunciation-score-main span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.takeaway-pronunciation-score-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.takeaway-pronunciation-score-grid span {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel-2, var(--panel));
  padding: 12px 8px;
  color: var(--muted);
  display: grid;
  place-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 800;
}

.takeaway-pronunciation-score-grid b {
  color: var(--ink);
  font-size: 22px;
  line-height: 1;
}

.takeaway-pronunciation-words {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.takeaway-pronunciation-word {
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--panel-2, var(--panel));
  color: var(--ink);
  padding: 6px 10px;
  font-size: 14px;
  font-weight: 850;
  line-height: 1;
}

.takeaway-pronunciation-word.is-good {
  border-color: color-mix(in srgb, #10b981 42%, var(--line));
  background: color-mix(in srgb, #10b981 13%, var(--panel));
  color: color-mix(in srgb, #047857 78%, var(--ink));
}

.takeaway-pronunciation-word.is-close {
  border-color: color-mix(in srgb, #f59e0b 46%, var(--line));
  background: color-mix(in srgb, #f59e0b 14%, var(--panel));
  color: color-mix(in srgb, #b45309 78%, var(--ink));
}

.takeaway-pronunciation-word.is-missed {
  border-color: color-mix(in srgb, #ef4444 42%, var(--line));
  background: color-mix(in srgb, #ef4444 11%, var(--panel));
  color: color-mix(in srgb, #b91c1c 78%, var(--ink));
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}

.takeaway-pronunciation-transcript {
  border: 1px dashed var(--line);
  border-radius: 12px;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--panel-2, var(--panel)) 82%, transparent);
}

.takeaway-pronunciation-transcript p {
  margin: 4px 0 0;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.45;
}

.takeaway-pronunciation-status {
  min-height: 20px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
}

.takeaway-pronunciation-status.is-error {
  color: #b91c1c;
}

.takeaway-pronunciation-status.is-listening::before {
  content: "";
  width: 8px;
  height: 8px;
  margin-right: 7px;
  border-radius: 999px;
  display: inline-block;
  background: #ef4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4);
  animation: takeaway-listening-dot 1.1s ease-in-out infinite;
}

@keyframes takeaway-listening-dot {
  0%, 100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.42); }
  50% { box-shadow: 0 0 0 7px rgba(239, 68, 68, 0); }
}

.takeaway-pronunciation-card footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.takeaway-pronunciation-secondary,
.takeaway-pronunciation-record {
  min-height: 40px;
  border-radius: 999px;
  border: 1px solid var(--line);
  padding: 0 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-weight: 850;
  cursor: pointer;
  box-sizing: border-box;
}

.takeaway-pronunciation-secondary {
  background: var(--panel-2, var(--panel));
  color: var(--ink);
}

.takeaway-pronunciation-record {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  box-shadow: 0 12px 26px color-mix(in srgb, var(--accent) 26%, transparent);
}

.takeaway-pronunciation-record.is-recording {
  background: #ef4444;
  border-color: #ef4444;
  box-shadow: 0 12px 26px rgba(239, 68, 68, 0.26);
}

.takeaway-pronunciation-secondary svg,
.takeaway-pronunciation-record svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

@media (max-width: 640px) {
  .language-takeaway-popup header {
    align-items: flex-start;
  }

  .language-takeaway-head-actions {
    gap: 6px;
  }

  .language-takeaway-popup header .language-takeaway-practice-btn {
    min-width: 0;
    padding: 0 9px;
    font-size: 12px;
  }

  .takeaway-pronunciation-dialog {
    padding: 12px;
    align-items: end;
  }

  .takeaway-pronunciation-card {
    max-height: calc(100vh - 24px);
    padding: 15px;
    border-radius: 16px;
  }

  .takeaway-pronunciation-scores {
    grid-template-columns: minmax(0, 1fr);
  }

  .takeaway-pronunciation-score-main {
    min-height: 86px;
  }

  .takeaway-pronunciation-score-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .takeaway-pronunciation-card footer {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .takeaway-pronunciation-secondary,
  .takeaway-pronunciation-record {
    width: 100%;
  }
}

.language-takeaway-popup label {
  display: grid;
  gap: 0;
}

.language-takeaway-popup textarea {
  width: 100%;
  resize: none;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 13px;
  color: var(--ink);
  font: inherit;
  font-weight: 650;
  line-height: 1.5;
}

/* English source: bigger and auto-grows to show the whole selection (no inner
   scroll), so the popup never has to scroll its body. */
#languageTakeawaySource {
  min-height: 96px;
  max-height: 42vh;
  font-size: 17px;
  overflow: hidden;
  padding-top: 9px;
}

/* Chinese keeps reserved space so the popup doesn't jump in size once the
   translation arrives. */
#languageTakeawayChinese {
  min-height: 84px;
  font-size: 15px;
  overflow: auto;
}

/* Read-only dictionary card: shown instead of the Chinese textarea while a
   single-word lookup is active. Renders bracketed ECDICT domain codes ([经]…)
   as pill tags so the field of each sense reads clearly. */
.language-takeaway-dict-display {
  min-height: 84px;
  max-height: 42vh;
  overflow: auto;
  padding: 10px 13px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  display: flex;
  flex-direction: column;
  gap: 7px;
  transition: opacity 0.16s ease;
}
.language-takeaway-dict-display.is-dictionary-transitioning {
  opacity: 0;
}
.language-takeaway-dict-display.is-dictionary-editable {
  cursor: text;
  background: color-mix(in srgb, var(--panel) 96%, #ffffff);
}
.language-takeaway-dict-display.is-dictionary-editable:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 13%, transparent);
}
/* Block (not flex) so the tag, its trailing colon and the sense text read as
   one continuous line — flex gap would scatter them. */
.dict-sense-line {
  display: block;
  font-weight: 650;
  line-height: 1.7;
}
.dict-sense-line.dict-sense-en {
  font-weight: 600;
  line-height: 1.5;
  color: color-mix(in srgb, var(--ink) 88%, transparent);
}
.dict-domain-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.34em;
  padding: 0.15em 0.56em 0.18em;
  border: 1px solid color-mix(in srgb, var(--accent) 26%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 15%, var(--panel));
  color: color-mix(in srgb, var(--accent) 76%, var(--ink));
  font-size: 0.86em;
  font-weight: 820;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
  vertical-align: 0.08em;
  user-select: all;
  box-shadow: inset 0 1px 0 color-mix(in srgb, #ffffff 42%, transparent);
}
.dict-domain-tag[contenteditable="false"] {
  user-select: all;
}
.dict-domain-tag-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.1em;
  min-width: 1.1em;
  font-size: 0.92em;
  line-height: 1;
}
.dict-domain-tag-text {
  line-height: 1;
}
.dict-domain-tag-colon {
  color: color-mix(in srgb, var(--accent) 78%, var(--ink));
  opacity: 1;
  font-weight: 760;
}
.nr-gloss .dict-domain-tag {
  font-size: clamp(13px, 0.48em, 18px);
  vertical-align: 0.16em;
}
.nr-gloss .dict-domain-tag-colon {
  font-size: clamp(16px, 0.58em, 22px);
}
.nr-lib-gloss .dict-domain-tag {
  font-size: 0.92em;
}
body.theme-dark .language-takeaway-dict-display {
  background: var(--dark-input);
  border-color: var(--dark-border);
}
body.theme-dark .language-takeaway-dict-display.is-dictionary-editable {
  background: color-mix(in srgb, var(--dark-input) 92%, #020617);
}
body.theme-dark .dict-domain-tag {
  border-color: color-mix(in srgb, var(--accent) 30%, rgba(255, 255, 255, 0.14));
  background: color-mix(in srgb, var(--accent) 18%, #0b1117);
  color: color-mix(in srgb, var(--accent) 55%, #ffffff);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 1px 6px rgba(0, 0, 0, 0.18);
}

body.theme-dark .dict-domain-tag-colon {
  color: color-mix(in srgb, var(--accent) 62%, #ffffff);
}

.language-takeaway-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.language-takeaway-actions-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.language-takeaway-actions-left > span {
  color: var(--muted);
  font-size: 12px;
}

/* + button: add a single English word to spelling training. */
.language-takeaway-spelling-btn {
  flex: 0 0 auto;
  width: 40px;
  height: 40px;
  min-width: 40px;
  min-height: 40px;
  box-sizing: border-box;
  padding: 0;
  display: inline-grid;
  place-items: center;
  position: relative;
  border: 1px solid color-mix(in srgb, var(--accent, #2563eb) 40%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent, #2563eb) 10%, var(--panel));
  color: var(--accent, #2563eb);
  cursor: pointer;
  overflow: hidden;
  transition: background 0.15s ease, transform 0.1s ease, color 0.15s ease, border-color 0.15s ease;
}
.language-takeaway-spelling-btn .lt-spell-icon {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transform: scale(0.92);
  transition: opacity 140ms ease, transform 140ms ease;
  pointer-events: none;
}
.language-takeaway-spelling-btn .lt-spell-icon svg {
  display: block;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.language-takeaway-spelling-btn:not([data-spelling-state="busy"]):not([data-spelling-state="check"]) .lt-spell-icon-add,
.language-takeaway-spelling-btn[data-spelling-state="plus"] .lt-spell-icon-add,
.language-takeaway-spelling-btn[data-spelling-state="check"] .lt-spell-icon-check,
.language-takeaway-spelling-btn[data-spelling-state="busy"] .lt-spell-icon-loading {
  opacity: 1;
  transform: scale(1);
}
.language-takeaway-spelling-btn:hover { background: color-mix(in srgb, var(--accent, #2563eb) 18%, var(--panel)); }
.language-takeaway-spelling-btn:active { transform: scale(0.92); }
.language-takeaway-spelling-btn.is-busy {
  cursor: progress;
}
.language-takeaway-spelling-btn .lt-spell-icon-loading {
  inset: auto;
  top: 50%;
  left: 50%;
  margin: -9px 0 0 -9px;
  display: block;
  width: 18px;
  height: 18px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 2.4px solid color-mix(in srgb, currentColor 24%, transparent);
  border-top-color: currentColor;
  animation: takeawayAddSpin 760ms linear infinite;
}
@keyframes takeawayAddSpin {
  to { transform: rotate(360deg); }
}
.language-takeaway-spelling-btn.is-added {
  background: #16a34a;
  border-color: #15803d;
  color: #fff;
}
body.theme-dark .language-takeaway-spelling-btn {
  border-color: color-mix(in srgb, #7aa2ff 42%, transparent);
  background: color-mix(in srgb, #7aa2ff 16%, var(--panel));
  color: #cdddff;
}
body.theme-dark .language-takeaway-spelling-btn.is-added {
  background: #15803d;
  border-color: #166534;
  color: #fff;
}
.language-takeaway-action-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(128px, 1fr));
  align-items: center;
  justify-content: end;
  gap: 10px;
  width: min(100%, 282px);
}

.language-takeaway-action-buttons:has(.language-takeaway-dict-toggle:not(.hidden)) {
  grid-template-columns: 54px minmax(118px, 1fr) minmax(118px, 1fr);
  gap: 8px;
  width: min(100%, 336px);
}

.language-takeaway-action-buttons button {
  width: 100%;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: nowrap;
}

.language-takeaway-action-buttons .language-takeaway-dict-toggle {
  --dict-toggle-w: 54px;
  --dict-toggle-h: 28px;
  --dict-toggle-pad: 3px;
  --dict-toggle-thumb: 22px;
  --dict-toggle-travel: calc(var(--dict-toggle-w) - var(--dict-toggle-thumb) - (var(--dict-toggle-pad) * 2));
  box-sizing: border-box !important;
  width: var(--dict-toggle-w) !important;
  height: var(--dict-toggle-h) !important;
  min-width: var(--dict-toggle-w) !important;
  min-height: var(--dict-toggle-h) !important;
  padding: 0 !important;
  border-radius: 999px !important;
  border: 1px solid color-mix(in srgb, var(--line) 78%, transparent) !important;
  background: color-mix(in srgb, var(--panel) 92%, #ffffff) !important;
  box-shadow:
    inset 0 1px 2px rgba(15, 23, 42, 0.08),
    0 3px 10px rgba(15, 23, 42, 0.08) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  overflow: hidden !important;
  color: var(--muted) !important;
  position: relative !important;
  z-index: 2 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
  transform: none !important;
}

.language-takeaway-action-buttons .language-takeaway-dict-toggle:hover,
.language-takeaway-action-buttons .language-takeaway-dict-toggle:active,
.language-takeaway-action-buttons .language-takeaway-dict-toggle:focus-visible {
  transform: none !important;
}

.language-takeaway-action-buttons .language-takeaway-dict-toggle.hidden {
  display: none !important;
}

.language-takeaway-dict-toggle .dict-toggle-rail {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  width: 100%;
  height: 100%;
}

.language-takeaway-dict-toggle .dict-toggle-label {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  font-size: 9.5px;
  font-weight: 850;
  line-height: 1;
  letter-spacing: 0;
  padding-top: 0;
  color: color-mix(in srgb, var(--muted) 82%, transparent);
  pointer-events: none;
  transition: color 160ms ease;
}

.language-takeaway-dict-toggle .dict-toggle-thumb {
  position: absolute;
  z-index: 1;
  top: var(--dict-toggle-pad);
  left: var(--dict-toggle-pad);
  width: var(--dict-toggle-thumb);
  height: var(--dict-toggle-thumb);
  border-radius: 999px;
  background: linear-gradient(135deg, #14b8a6, #0ea5e9);
  box-shadow:
    0 4px 10px rgba(20, 184, 166, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.32);
  transform: translateX(0);
  transition: transform 190ms cubic-bezier(0.2, 0.8, 0.2, 1), background 160ms ease;
}

.language-takeaway-dict-toggle[data-dictionary-mode="en"] .dict-toggle-thumb {
  transform: translateX(var(--dict-toggle-travel));
}

.language-takeaway-dict-toggle[data-dictionary-mode="zh"] .dict-toggle-label-zh,
.language-takeaway-dict-toggle[data-dictionary-mode="en"] .dict-toggle-label-en {
  color: #ffffff;
}

body.theme-dark .language-takeaway-action-buttons .language-takeaway-dict-toggle {
  border-color: rgba(74, 95, 111, 0.68) !important;
  background: #0b1117 !important;
  box-shadow:
    inset 0 1px 2px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(13, 95, 82, 0.08) !important;
}

body.theme-dark .language-takeaway-dict-toggle .dict-toggle-label {
  color: rgba(203, 213, 225, 0.64);
}

body.theme-dark .language-takeaway-dict-toggle .dict-toggle-thumb {
  background: linear-gradient(135deg, #0d5f52, #11466a);
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

body.theme-dark .language-takeaway-dict-toggle[data-dictionary-mode="zh"] .dict-toggle-label-zh,
body.theme-dark .language-takeaway-dict-toggle[data-dictionary-mode="en"] .dict-toggle-label-en {
  color: #ffffff;
}

/* Language Takeaway compact controls: keep the spelling glyph truly centered and
   prevent the global .is-busy pseudo spinner from drawing a second ring. */
.language-takeaway-actions-left .language-takeaway-spelling-btn {
  width: 34px !important;
  height: 34px !important;
  min-width: 34px !important;
  min-height: 34px !important;
  padding: 0 !important;
  display: inline-grid !important;
  place-items: center !important;
  align-self: center !important;
  justify-self: center !important;
  overflow: hidden !important;
}

.language-takeaway-actions-left .language-takeaway-spelling-btn.hidden {
  display: none !important;
}

.language-takeaway-spelling-btn.is-busy::after {
  content: none !important;
  display: none !important;
}

.language-takeaway-spelling-btn .lt-spell-icon {
  inset: 0 !important;
  display: grid !important;
  place-items: center !important;
  transform-origin: center !important;
}

.language-takeaway-spelling-btn .lt-spell-icon svg {
  width: 16px !important;
  height: 16px !important;
}

.language-takeaway-spelling-btn .lt-spell-icon-loading {
  top: 50% !important;
  left: 50% !important;
  width: 16px !important;
  height: 16px !important;
  margin: -8px 0 0 -8px !important;
  border: 0 !important;
  animation: none !important;
}

.language-takeaway-spelling-btn .lt-spell-icon-loading::before {
  content: "";
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, currentColor 28%, transparent);
  border-top-color: currentColor;
  border-right-color: transparent;
  animation: takeawaySpellSpin 720ms linear infinite;
  transform-origin: 50% 50%;
}

@keyframes takeawaySpellSpin {
  to { transform: rotate(360deg); }
}

/* Final P1 intensity controls and header pixel-flow treatment. */
.exam-status.p1-pixel-flow {
  isolation: isolate;
  overflow: hidden;
}

.exam-status.p1-pixel-flow::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--panel) 88%, transparent), transparent 48%, color-mix(in srgb, var(--panel) 84%, transparent)),
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 82%, transparent), color-mix(in srgb, var(--panel) 96%, transparent));
}

.exam-status.p1-pixel-flow .p2-pixel-flow-canvas {
  z-index: 1;
  opacity: 0;
  transition: opacity 520ms ease;
}

.exam-status.p1-pixel-flow.p1-pixel-flow-visible .p2-pixel-flow-canvas {
  opacity: 0.74;
}

.exam-status.p1-pixel-flow #examStatusText,
.exam-status.p1-pixel-flow .exam-actions,
.exam-status.p1-pixel-flow .p2-corpus-prep {
  position: relative;
  z-index: 3;
}

.exam-actions .p1-mode-switch {
  flex: 0 0 auto;
  width: 214px;
  min-width: 214px;
  max-width: 214px;
  transition:
    width 260ms ease,
    min-width 260ms ease,
    max-width 260ms ease,
    opacity 220ms ease,
    transform 220ms ease,
    margin 220ms ease,
    padding 220ms ease;
}

.exam-actions .p1-mode-switch .p3-mode-option {
  min-height: 36px !important;
  padding: 0 10px !important;
  font-size: 13px !important;
}

.practice-panel.p1-started .p1-mode-switch,
.exam-actions .p1-mode-switch.is-collapsed {
  width: 0 !important;
  min-width: 0 !important;
  max-width: 0 !important;
  opacity: 0 !important;
  transform: translateX(10px) scale(0.96);
  pointer-events: none;
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  border-width: 0 !important;
  overflow: hidden !important;
}

.practice-panel.p3-starting #practiceGrid {
  opacity: 0;
  pointer-events: none;
}

body.theme-dark .exam-status.p1-pixel-flow::before {
  background:
    linear-gradient(90deg, rgba(8, 14, 24, 0.9), rgba(8, 14, 24, 0.34) 48%, rgba(8, 14, 24, 0.86)),
    linear-gradient(180deg, rgba(8, 14, 24, 0.72), rgba(8, 14, 24, 0.95));
}

