.expression-replacement-edit,
.expression-replacement-delete,
.expression-replacement-add,
.expression-replacement-speak {
  min-height: 34px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink);
  padding: 0 11px;
  font-size: 13px;
  font-weight: 780;
  cursor: pointer;
}

.expression-replacement-add,
.expression-replacement-speak {
  position: relative;
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  padding: 0;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  line-height: 1;
}

.expression-replacement-add {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
  color: var(--accent-dark);
  font-size: 20px;
  font-family: var(--ui-font, inherit);
  font-weight: 760;
  line-height: 1;
}

.expression-replacement-add.is-busy {
  color: transparent;
  opacity: 1;
}

.expression-replacement-add.is-busy::after {
  position: absolute;
  inset: 50% auto auto 50%;
  width: 18px;
  height: 18px;
  margin: -9px 0 0 -9px;
  border-width: 2px;
  color: var(--accent-dark);
}

.expression-replacement-add.is-added {
  color: var(--accent-dark);
}

.expression-replacement-speak {
  color: #2563eb;
  background: color-mix(in srgb, #2563eb 6%, var(--panel));
  border-color: rgba(37, 99, 235, 0.22);
}

.expression-replacement-speak svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.expression-replacement-edit {
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  color: var(--accent-dark);
}

.expression-replacement-delete {
  color: var(--danger);
}

.expression-replacement-field {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.expression-replacement-field span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 820;
  letter-spacing: 0;
}

.expression-replacement-field input,
.expression-replacement-field textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  line-height: 1.42;
  padding: 9px 10px;
  outline: none;
}

.expression-replacement-field textarea {
  min-height: 58px;
  max-height: 112px;
  resize: vertical;
}

.expression-replacement-chip-editor {
  min-height: 132px;
  max-height: 168px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fff;
  padding: 5px 7px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.expression-replacement-chip-list {
  display: contents;
}

.expression-replacement-chip {
  height: 24px;
  min-height: 24px;
  max-width: min(100%, 220px);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 7%, #fff);
  color: var(--ink);
  padding: 0 4px 0 9px;
  font-size: 12px;
  font-weight: 760;
}

.expression-replacement-chip > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.expression-replacement-chip button {
  width: 18px !important;
  height: 18px !important;
  min-width: 18px !important;
  min-height: 18px !important;
  flex: 0 0 18px;
  border: 0;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.08);
  color: var(--muted);
  display: inline-grid;
  place-items: center;
  padding: 0;
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
}

.expression-replacement-chip button:hover,
.expression-replacement-chip button:focus-visible {
  background: rgba(15, 23, 42, 0.14);
  outline: none;
}

.expression-replacement-chip-add {
  width: 26px;
  height: 26px;
  min-width: 26px;
  min-height: 26px;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 9%, #fff);
  color: var(--accent-dark);
  display: inline-grid;
  place-items: center;
  padding: 0;
  font-size: 18px;
  font-weight: 850;
  line-height: 1;
  cursor: pointer;
}

.expression-replacement-chip-editor input[data-expression-replacement-chip-input] {
  width: min(240px, 100%);
  flex: 1 1 180px;
  min-width: 130px;
  border: 0;
  background: transparent;
  padding: 4px 2px;
  box-shadow: none;
}

.expression-replacement-field input:focus,
.expression-replacement-field textarea:focus {
  border-color: color-mix(in srgb, var(--accent) 52%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 13%, transparent);
}

.expression-replacement-chip-editor:focus-within {
  border-color: color-mix(in srgb, var(--accent) 52%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 13%, transparent);
}

.expression-replacement-edit-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

#languageTakeawayStatus {
  min-height: 18px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 700;
}

.language-status-spinner {
  width: 14px;
  height: 14px;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--accent) 18%, transparent);
  border-top-color: var(--accent);
  animation: takeawaySpin 760ms linear infinite;
}

@keyframes takeawaySpin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }

  .language-status-spinner {
    animation: none;
  }

  .topbar-back-button:hover,
  .corpus-home-card:hover,
  .p1-topic-card:hover,
  .p2-topic-card:hover,
  .history-item:hover,
  .writing-prompt-choice:hover,
  .icon-button:hover {
    transform: none;
  }
}

.p1-corpus-shell,
.p2-corpus-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 16px;
  height: 100%;
}

.p2-corpus-shell {
  gap: 16px;
}

.p1-corpus-head,
.p2-corpus-head {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  min-height: 96px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.96);
  padding: 20px 24px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), 0 4px 16px rgba(15, 23, 42, 0.06), 0 1px 3px rgba(15, 23, 42, 0.04);
}

.p1-corpus-head-copy,
.p2-corpus-head-copy {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.corpus-head-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  min-width: min(420px, 46%);
}

.corpus-agent-button {
  flex: 0 0 auto;
  height: 38px;
  min-height: 38px;
  padding: 0 14px;
  border-color: rgba(180, 83, 9, 0.20);
  background: linear-gradient(180deg, #fff7ed 0%, #ffedd5 100%);
  color: #7c2d12;
  box-shadow: 0 10px 22px rgba(180, 83, 9, 0.10);
}

.corpus-agent-button:hover {
  border-color: rgba(180, 83, 9, 0.42);
  background: linear-gradient(180deg, #fffbeb 0%, #fed7aa 100%);
}

.p1-corpus-head .corpus-agent-button span,
.p2-corpus-head .corpus-agent-button span {
  display: inline;
  min-height: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  padding: 0;
  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
  box-shadow: none;
}

.corpus-page-kicker {
  color: var(--corpus-accent, #2563eb);
  font-size: 11px;
  font-weight: 860;
  line-height: 1.2;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.p1-corpus-head h2,
.p2-corpus-head h2 {
  margin: 0;
  color: #0f172a;
  font-size: 24px;
  line-height: 1.12;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.p1-corpus-head p,
.p2-corpus-head p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.45;
}

.p1-corpus-head span,
.p2-corpus-head span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  border: 1px solid rgba(37, 99, 235, 0.22);
  border-radius: 999px;
  background: linear-gradient(180deg, #f0f7ff 0%, #e8f2ff 100%);
  color: #1e40af;
  padding: 0 16px;
  font-size: 13px;
  font-weight: 820;
  line-height: 1;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), 0 1px 3px rgba(37, 99, 235, 0.1);
}

.p1-corpus-head .corpus-page-kicker,
.p2-corpus-head .corpus-page-kicker {
  min-height: 0;
  display: inline;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--corpus-accent, #2563eb);
  padding: 0;
  box-shadow: none;
  font-size: 11px;
  font-weight: 860;
  justify-content: start;
}

.p1-corpus-topics,
.p2-corpus-topics {
  min-height: 0;
  overflow-y: auto;
  display: grid;
  align-items: stretch;
  align-content: start;
  grid-auto-rows: max-content;
  gap: 16px;
  padding: 0 6px 6px 0;
}

.p1-corpus-topics {
  grid-template-columns: repeat(3, minmax(280px, 1fr));
}

/* Full-width fence between the rotating topics and the long-term retained ones. */
.p1-topic-divider {
  grid-column: 1 / -1;
  width: 100%;
  height: 0;
  margin: 4px 0;
  border: 0;
  border-top: 2px dashed color-mix(in srgb, var(--ink) 22%, transparent);
}
body.theme-dark .p1-topic-divider {
  border-top-color: color-mix(in srgb, var(--ink) 26%, transparent);
}

.p2-corpus-topics {
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
  padding: 0 4px 6px 0;
}

.p1-corpus-topics:has(.corpus-loading-state),
.p2-corpus-topics:has(.corpus-loading-state) {
  grid-template-columns: minmax(0, 1fr);
  align-content: center;
  padding: 0;
}

.p2-category-entry-grid,
.p2-seasonal-card-grid {
  display: grid;
  gap: 14px;
}

.p2-category-entry-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  grid-auto-rows: auto;
  gap: 14px;
}

.p2-category-entry-grid > .p2-category-entry-card {
  width: 100%;
  min-width: 0;
  height: 100%;
}

.p2-seasonal-card-section {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.p2-seasonal-section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 14px;
  padding: 2px 2px 0;
}

.p2-seasonal-section-head h3 {
  margin: 3px 0 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.15;
}

.p2-seasonal-section-head > span {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  border: 1px solid rgba(37, 99, 235, 0.16);
  border-radius: 999px;
  background: #eff6ff;
  color: #1d4ed8;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
}

.p2-seasonal-card-grid {
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  grid-auto-rows: max-content;
}

/* ── P2 seasonal card — per-category color variables ── */
.p2-seasonal-card[data-p2-bank-card-category="person"]  { --cat-color: #7c3aed; --cat-light: #ede9fe; --cat-mid: #c4b5fd; }
.p2-seasonal-card[data-p2-bank-card-category="place"]   { --cat-color: #059669; --cat-light: #d1fae5; --cat-mid: #6ee7b7; }
.p2-seasonal-card[data-p2-bank-card-category="event"]   { --cat-color: #d97706; --cat-light: #fef3c7; --cat-mid: #fcd34d; }
.p2-seasonal-card[data-p2-bank-card-category="object"]  { --cat-color: #0284c7; --cat-light: #e0f2fe; --cat-mid: #7dd3fc; }
.p2-seasonal-card[data-p2-bank-card-category="special"] { --cat-color: #db2777; --cat-light: #fce7f3; --cat-mid: #f9a8d4; }

.p2-seasonal-card {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 14px;
  min-height: 256px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-left: 5px solid var(--cat-color, var(--p2-corpus-accent));
  border-radius: 12px;
  background: #fff;
  padding: 16px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.06), 0 10px 26px rgba(15, 23, 42, 0.05);
  transition: transform 200ms ease, box-shadow 200ms ease, border-color 200ms ease;
}

.p2-seasonal-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 50%, transparent);
  box-shadow:
    0 3px 8px rgba(15, 23, 42, 0.06),
    0 18px 40px color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 10%, rgba(15, 23, 42, 0.08));
}

.p2-seasonal-card header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  background: transparent;
  padding: 0;
}

.p2-seasonal-card h3 {
  margin: 5px 0 0;
  color: #0f172a;
  font-size: 17px;
  line-height: 1.24;
  font-weight: 820;
}

.p2-seasonal-card-kicker {
  color: var(--cat-color, var(--p2-corpus-accent-dark));
  font-size: 12px;
  font-weight: 850;
  line-height: 1;
  text-transform: uppercase;
}

.p2-seasonal-card-state {
  flex: 0 0 auto;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 999px;
  background: #f8fafc;
  color: #64748b;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.p2-seasonal-card-state.is-ready {
  border-color: color-mix(in srgb, var(--cat-color, #2563eb) 20%, transparent);
  background: color-mix(in srgb, var(--cat-light, #eff6ff) 70%, #fff);
  color: var(--cat-color, #1d4ed8);
}

/* ── Category filter bar ── */
.p2-cat-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 0 4px;
}
.p2-cat-filter-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 32px;
  padding: 0 13px;
  border: 1.5px solid rgba(148, 163, 184, 0.28);
  border-radius: 999px;
  background: #f8fafc;
  color: #64748b;
  font-size: 13px;
  font-weight: 720;
  cursor: pointer;
  transition: all 160ms ease;
}
.p2-cat-filter-btn span {
  font-size: 11px;
  font-weight: 760;
  opacity: 0.72;
}
.p2-cat-filter-btn:hover {
  border-color: color-mix(in srgb, var(--filter-color, var(--p2-corpus-accent)) 50%, transparent);
  color: var(--filter-color, var(--p2-corpus-accent));
  background: color-mix(in srgb, var(--filter-color, var(--p2-corpus-accent)) 6%, #fff);
}
.p2-cat-filter-btn.active {
  border-color: var(--filter-color, var(--p2-corpus-accent));
  background: color-mix(in srgb, var(--filter-color, var(--p2-corpus-accent)) 10%, #fff);
  color: var(--filter-color, var(--p2-corpus-accent));
  font-weight: 800;
}
.p2-cat-filter-btn.active span { opacity: 1; }

/* ── Seasonal card body — relative container for floating button ── */
.p2-seasonal-body {
  position: relative;
  min-height: 0;
}

.p2-seasonal-cue {
  display: grid;
  gap: 9px;
  color: #334155;
  font-size: 14px;
  line-height: 1.45;
  padding-right: 58px;
}

/* ── Direct-practice FAB — fixed circle centered on the cue body ── */
.p2-seasonal-practice-btn {
  position: absolute;
  right: 0;
  top: 50%;
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  aspect-ratio: 1;
  padding: 0;
  display: inline-grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 28%, var(--line));
  border-radius: 50%;
  background: color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 10%, var(--panel));
  color: var(--cat-color, var(--p2-corpus-accent));
  cursor: pointer;
  transform: translateY(-50%);
  transition: transform 150ms cubic-bezier(0.34, 1.2, 0.64, 1), box-shadow 150ms ease;
  box-shadow:
    0 2px 8px color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 16%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
.p2-seasonal-practice-icon {
  width: 18px;
  height: 18px;
  display: block;
  margin: 0;
}
/* hide text — icon-only FAB */
.p2-seasonal-practice-btn > span:not(.p2-seasonal-practice-icon) { display: none; }
.p2-seasonal-practice-btn:hover {
  border-color: var(--cat-color, var(--p2-corpus-accent));
  background: color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 18%, var(--panel));
  transform: translateY(-50%) scale(1.08);
  box-shadow:
    0 4px 14px color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 24%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.24);
}
.p2-seasonal-practice-btn:active {
  transform: translateY(-50%) scale(0.94);
}

.p2-seasonal-cue strong {
  color: #0f172a;
  font-size: 14px;
  font-weight: 760;
}

.p2-seasonal-cue ul {
  margin: 0;
  padding-left: 18px;
}

.p2-seasonal-cue p {
  margin: 0;
}

.p2-seasonal-card footer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.p2-seasonal-action {
  min-height: 42px;
  border: 1px solid rgba(37, 99, 235, 0.16);
  border-radius: 8px;
  background: #fff;
  color: #2563eb;
  font-size: 14px;
  font-weight: 820;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.p2-seasonal-action.primary,
.p2-seasonal-action.is-ready {
  background: #eff6ff;
  color: #1d4ed8;
}

.p2-seasonal-action:hover,
.p2-seasonal-action:focus-visible {
  border-color: rgba(37, 99, 235, 0.34);
  background: #dbeafe;
  outline: none;
}

/* ── Seasonal card: P3 follow-up completion progress (mirrors P1 topic progress,
   but keyed to each card's category accent --cat-color) ── */
.p2-seasonal-p3-progress {
  display: flex;
  align-items: center;
  gap: 10px;
}
.p2-seasonal-p3-progress-label {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 800;
  color: var(--cat-color, var(--p2-corpus-accent));
  letter-spacing: 0.01em;
}
.p2-seasonal-p3-progress-track {
  position: relative;
  flex: 1 1 auto;
  height: 8px;
  background: #f1f5f9;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 999px;
  overflow: hidden;
}
.p2-seasonal-p3-progress-track > span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--cat-color, var(--p2-corpus-accent)), color-mix(in srgb, var(--cat-color, var(--p2-corpus-accent)) 62%, #6ee7b7));
  transition: width 480ms cubic-bezier(0.34, 1.1, 0.64, 1);
}
.p2-seasonal-p3-progress-count {
  flex: 0 0 auto;
  min-width: 34px;
  text-align: right;
  font-size: 12px;
  font-weight: 840;
  color: var(--cat-color, var(--p2-corpus-accent));
  font-variant-numeric: tabular-nums;
}
.p2-seasonal-p3-progress[data-progress="100"] .p2-seasonal-p3-progress-count::after {
  content: " ✓";
}

@media (max-width: 1420px) {
  .p2-seasonal-card-grid {
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  }
}

@media (max-width: 1180px) {
  .p2-category-entry-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .p2-seasonal-card-grid {
