.p1-topic-card,
.p2-topic-card {
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 16px;
  background: #fff;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 4px 8px rgba(15, 23, 42, 0.04),
    0 12px 24px rgba(15, 23, 42, 0.05);
  overflow: hidden;
  min-height: 0;
  transition: transform 220ms cubic-bezier(0.34, 1.2, 0.64, 1), box-shadow 220ms ease, border-color 220ms ease;
}

.p1-topic-card:hover {
  transform: translateY(-4px) scale(1.005);
  border-color: color-mix(in srgb, var(--p1-corpus-accent) 42%, transparent);
  box-shadow:
    0 2px 4px rgba(15, 23, 42, 0.04),
    0 8px 20px color-mix(in srgb, var(--p1-corpus-accent) 10%, rgba(15, 23, 42, 0.07)),
    0 24px 48px rgba(15, 23, 42, 0.09);
}
.p2-topic-card:hover {
  transform: translateY(-4px) scale(1.005);
  border-color: rgba(37, 99, 235, 0.28);
  box-shadow:
    0 2px 4px rgba(15, 23, 42, 0.04),
    0 8px 20px rgba(15, 23, 42, 0.07),
    0 24px 48px rgba(15, 23, 42, 0.09);
}

.p2-topic-card {
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 4px 8px rgba(15, 23, 42, 0.04),
    0 12px 24px rgba(15, 23, 42, 0.05);
  height: 100%;
}

.p2-category-entry-card {
  min-height: 170px;
}

/* ── Per-category visual identity (P2 分类卡专属色) ── */
.p2-category-entry-card[data-category="person"]  { --cat-color: #7c3aed; --cat-light: #ede9fe; --cat-mid: #c4b5fd; }
.p2-category-entry-card[data-category="place"]   { --cat-color: #059669; --cat-light: #d1fae5; --cat-mid: #6ee7b7; }
.p2-category-entry-card[data-category="event"]   { --cat-color: #d97706; --cat-light: #fef3c7; --cat-mid: #fcd34d; }
.p2-category-entry-card[data-category="object"]  { --cat-color: #0284c7; --cat-light: #e0f2fe; --cat-mid: #7dd3fc; }
.p2-category-entry-card[data-category="special"] { --cat-color: #db2777; --cat-light: #fce7f3; --cat-mid: #f9a8d4; }
.p2-category-entry-card[data-category="brainstorm"] { --cat-color: #4f46e5; --cat-light: #eef2ff; --cat-mid: #a5b4fc; }

.p1-topic-card header,
.p2-topic-card header {
  display: flex;
