/* P1 topic count badge — uses accent color */
.p1-topic-count {
  min-width: 48px;
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 999px;
  background: var(--p1-corpus-accent);
  color: #fff;
  font-size: 12px;
  font-weight: 840;
  line-height: 1;
  padding: 0 10px;
  box-shadow: 0 1px 4px color-mix(in srgb, var(--p1-corpus-accent) 44%, transparent);
}

/* P1 progress bar — tall, readable, with % label */
.p1-topic-progress {
  position: relative;
  height: 10px;
  background: #f1f5f9;
  border-radius: 999px;
  overflow: visible;
  border: 1px solid rgba(148, 163, 184, 0.18);
  /* inset from card edges; right gap keeps the ::after % label inside the card */
  margin: 8px 48px 8px 14px;
}
.p1-topic-progress span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--p1-corpus-accent), color-mix(in srgb, var(--p1-corpus-accent) 68%, #6ee7b7));
  transition: width 480ms cubic-bezier(0.34, 1.1, 0.64, 1);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--p1-corpus-accent) 50%, transparent);
}
/* Percentage label right-aligned */
.p1-topic-progress::after {
  content: attr(data-progress) "%";
  position: absolute;
  right: -4px;
  top: 50%;
  transform: translate(100%, -50%);
  font-size: 10px;
  font-weight: 820;
  color: var(--p1-corpus-accent);
  line-height: 1;
  white-space: nowrap;
  padding-left: 6px;
}
/* Fully done: shorter label that fits within the right margin */
.p1-topic-progress[data-progress="100"]::after {
  content: "✓ 全部";
  color: var(--p1-corpus-accent);
  font-weight: 900;
}

.p1-topic-question-list,
.p2-topic-material-list {
