}

.p2-bank-brainstorm-field input::placeholder {
  color: #94a3b8;
}

.p2-bank-brainstorm-field input:focus {
  border-color: rgba(79, 70, 229, 0.52);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.09);
}

.p2-brainstorm-dialog .p2-brainstorm-dialog-card {
  width: min(1180px, calc(100vw - 42px));
  max-width: 1180px;
  height: min(780px, calc(100vh - 48px));
  min-height: 560px;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 12px;
  padding: 18px;
}

/* Refined entrance: the scrim fades in and the card eases up from slightly
   below + scaled-down, so opening the dialog feels intentional, not abrupt. */
.p2-brainstorm-dialog:not(.hidden) {
  animation: p2BrainstormScrimIn 220ms ease both;
}

.p2-brainstorm-dialog:not(.hidden) .p2-brainstorm-dialog-card {
  animation: p2BrainstormCardIn 320ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Returning from the body editor: reveal the underlying dialog instantly, no
   open-from-scratch entrance. */
.p2-brainstorm-dialog.no-entrance:not(.hidden),
.p2-brainstorm-dialog.no-entrance:not(.hidden) .p2-brainstorm-dialog-card {
  animation: none;
}

@keyframes p2BrainstormScrimIn {
  from { background: rgba(15, 23, 42, 0); }
  to { background: rgba(15, 23, 42, 0.48); }
}

@keyframes p2BrainstormCardIn {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* One-shot staggered fade-up for the rows, gated behind .is-entering (added on
   open, removed shortly after) so filtering/searching stays instant. */
.p2-brainstorm-list.is-entering .p2-brainstorm-row {
  animation: p2BrainstormRowIn 360ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(1) { animation-delay: 20ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(2) { animation-delay: 44ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(3) { animation-delay: 68ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(4) { animation-delay: 92ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(5) { animation-delay: 116ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(6) { animation-delay: 140ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(7) { animation-delay: 164ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(8) { animation-delay: 188ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(9) { animation-delay: 212ms; }
.p2-brainstorm-list.is-entering .p2-brainstorm-row:nth-child(n+10) { animation-delay: 236ms; }

@keyframes p2BrainstormRowIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .p2-brainstorm-dialog:not(.hidden),
  .p2-brainstorm-dialog:not(.hidden) .p2-brainstorm-dialog-card,
  .p2-brainstorm-list.is-entering .p2-brainstorm-row {
    animation: none;
  }
}

