  line-height: 1;
  transition: border-color 150ms ease, background 150ms ease,
    color 150ms ease, transform 150ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

#p2BrainstormSearchPrev:not(:disabled):hover,
#p2BrainstormSearchNext:not(:disabled):hover {
  transform: translateY(-1px);
  border-color: rgba(79, 70, 229, 0.45);
  color: #4338ca;
}

#p2BrainstormSearchPrev:not(:disabled):active,
#p2BrainstormSearchNext:not(:disabled):active {
  transform: translateY(0) scale(0.94);
}

#p2BrainstormSearchPrev:disabled,
#p2BrainstormSearchNext:disabled {
  cursor: default;
  opacity: 0.42;
}

.p2-brainstorm-dialog-subtitle {
  margin: 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.45;
}

.p2-brainstorm-list {
  min-height: 0;
  overflow: auto;
  overflow-anchor: none;
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 4px 8px 12px 0;
}

.p2-brainstorm-row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(380px, 0.95fr) minmax(380px, 1.05fr);
  gap: 16px;
  align-items: start;
  min-height: 72px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 12px;
  background: linear-gradient(180deg, #fff 0%, #fbfdff 100%);
  padding: 12px 14px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
  overflow: visible;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.p2-brainstorm-row:has(.p2-brainstorm-left.is-expanded) {
  z-index: 12;
  border-color: rgba(79, 70, 229, 0.28);
  box-shadow:
    0 0 0 3px rgba(79, 70, 229, 0.06),
    0 10px 24px rgba(15, 23, 42, 0.08);
}

.p2-brainstorm-row:focus-within {
  border-color: rgba(79, 70, 229, 0.42);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.09);
}

.p2-brainstorm-row.is-search-match {
  border-color: rgba(20, 184, 166, 0.34);
  background: linear-gradient(180deg, #f2fffc 0%, #fff 100%);
}

.p2-brainstorm-row.is-search-current {
  border-color: rgba(15, 118, 110, 0.58);
  box-shadow:
    0 0 0 3px rgba(20, 184, 166, 0.13),
    0 12px 28px rgba(15, 23, 42, 0.1);
}

/* 左侧容器：题干行 + 可展开的 cue 详情 */
.p2-brainstorm-left {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-radius: 10px;
}

/* 整行都可点击展开 cue 浮层（输入框/按钮除外） */
.p2-brainstorm-row.is-clickable {
  cursor: pointer;
}

.p2-brainstorm-row.is-clickable:hover .p2-brainstorm-stem,
.p2-brainstorm-row.is-clickable:focus-visible .p2-brainstorm-stem {
  color: #3730a3;
}

.p2-brainstorm-row.is-clickable:focus-visible {
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.p2-brainstorm-question {
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  color: #1e293b;
  font-size: 13.5px;
  font-weight: 640;
  line-height: 1.42;
}

.p2-brainstorm-stem {
  padding-top: 3px;
}

/* 展开的 cue 详情区 */
.p2-brainstorm-cue-detail {
  position: absolute;
  left: 54px;
  right: auto;
  top: calc(100% - 8px);
  z-index: 20;
  width: min(370px, calc(50% - 64px));
  max-height: 220px;
  overflow: auto;
  margin: 0;
  padding: 12px 14px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 12px;
  background: #fff;
  color: #64748b;
  font-size: 12.5px;
  font-weight: 480;
  line-height: 1.5;
  box-shadow:
    0 16px 34px rgba(15, 23, 42, 0.14),
    0 0 0 1px rgba(255, 255, 255, 0.86) inset;
}

/* Flip-up variant: opens above the row when there isn't room below, so a
   bottom-row popover never spills past the list and inflates its scroll. */
.p2-brainstorm-cue-detail {
  transform-origin: top left;
}

.p2-brainstorm-cue-detail.is-detail-up {
  top: auto;
  bottom: calc(100% - 8px);
  transform-origin: bottom left;
}

.p2-brainstorm-cue-detail.is-detail-in {
  animation: p2BrainstormDetailIn 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.p2-brainstorm-cue-detail.is-detail-up.is-detail-in {
  animation-name: p2BrainstormDetailInUp;
}

@keyframes p2BrainstormDetailIn {
  from { opacity: 0; transform: translateY(-6px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes p2BrainstormDetailInUp {
  from { opacity: 0; transform: translateY(6px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* Filter changes move as one stable result set. The row grid is only swapped
   while fully faded, so no intermediate reflow is visible. */
.p2-brainstorm-list.is-filter-switching-out > .p2-brainstorm-row:not(.is-filtered-out) {
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 140ms ease-out, transform 140ms ease-out;
  pointer-events: none;
}

.p2-brainstorm-list.is-filter-switching-in > .p2-brainstorm-row:not(.is-filtered-out) {
  animation: p2BrainstormFilterIn 230ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes p2BrainstormFilterIn {
  from { opacity: 0; transform: translateY(-4px) scale(0.992); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .p2-brainstorm-cue-detail.is-detail-in,
  .p2-brainstorm-list.is-filter-switching-in > .p2-brainstorm-row:not(.is-filtered-out) {
    animation: none;
  }

  .p2-brainstorm-list.is-filter-switching-out > .p2-brainstorm-row:not(.is-filtered-out) {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

