.p2-bank-p3-active-question span {
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.p2-bank-p3-active-question strong {
  color: var(--ink);
  font-size: 15px;
  font-weight: 820;
  line-height: 1.38;
}

.p2-bank-p3-empty {
  margin: 0;
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 12px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 720;
}

.p2-bank-p3-loading {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.72);
}

.p2-bank-p3-loading span {
  display: block;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(90deg, rgba(148, 163, 184, 0.16), rgba(148, 163, 184, 0.28), rgba(148, 163, 184, 0.16));
  background-size: 180% 100%;
  animation: corpusPeekLoading 1.15s ease-in-out infinite;
}

.p2-bank-p3-loading span:nth-child(2) {
  width: 92%;
}

.p2-bank-p3-loading span:nth-child(3) {
  width: 78%;
}

.p2-corpus-p3-dialog-card .vditor {
  min-height: 280px;
}

.p2-corpus-p3-dialog-card .vditor-ir,
.p2-corpus-p3-dialog-card .vditor-wysiwyg,
.p2-corpus-p3-dialog-card .vditor-reset {
  font-size: 17px;
  line-height: 1.58;
}

@media (max-width: 1180px) {
  .p2-corpus-p3-dialog-card {
    width: calc(100vw - var(--sidebar-width) - 36px);
    max-height: calc(100vh - 48px);
  }

  .p2-bank-p3-workspace {
    grid-template-columns: minmax(0, 1fr);
  }

  .p2-bank-p3-question-list {
    grid-template-columns: minmax(0, 1fr);
    max-height: 190px;
  }
}

.p2-add-material-button strong {
  color: var(--corpus-accent-dark);
}

.p2-corpus-prep {
  display: block;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
  margin: 0 0 14px;
}

.p2-corpus-prep strong,
.p2-corpus-prep span {
  display: block;
}

.p2-corpus-prep span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 13px;
}

.p2-corpus-prep-picker {
  position: relative;
  width: 100%;
  z-index: 1400;
}

.p2-corpus-prep-trigger {
  width: 100%;
  min-height: 46px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--line));
  border-radius: 16px;
  background:
    linear-gradient(180deg, #fff 0%, #fbfcfd 100%);
  color: var(--ink);
  padding: 0 16px 0 18px;
  font-size: 17px;
  font-weight: 650;
  line-height: 1.2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  text-align: left;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 1px 0 rgba(15, 23, 42, 0.02);
}

.p2-corpus-prep-trigger span {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.p2-corpus-prep-trigger svg {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  color: var(--muted);
  transition: transform 0.16s ease, color 0.16s ease;
}

.p2-corpus-prep-trigger[aria-expanded="true"] svg {
  transform: rotate(180deg);
  color: var(--accent);
}

.p2-corpus-prep-trigger:disabled {
  cursor: not-allowed;
  opacity: 0.68;
}

.p2-corpus-prep-trigger:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
  border-color: color-mix(in srgb, var(--accent) 46%, var(--line));
}

.p2-corpus-prep-menu {
  position: fixed;
  z-index: 9999;
  left: var(--p2-corpus-menu-left, 0);
  top: var(--p2-corpus-menu-top, 0);
  width: var(--p2-corpus-menu-width, 320px);
  max-height: min(280px, 52vh);
  overflow-y: auto;
  padding: 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--line));
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 94%, #fff);
  box-shadow:
    0 22px 50px rgba(15, 23, 42, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.78);
}

.p2-corpus-prep-menu button {
  width: 100%;
  min-height: 44px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--ink);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  text-align: left;
  font-size: 16px;
  font-weight: 650;
  cursor: pointer;
}

.p2-corpus-prep-menu button + button {
  margin-top: 2px;
}

.p2-corpus-prep-menu button:hover,
.p2-corpus-prep-menu button:focus-visible,
.p2-corpus-prep-menu button[aria-selected="true"] {
  outline: 0;
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.p2-corpus-prep-menu button strong {
  color: var(--accent);
  font-size: 12px;
  white-space: nowrap;
}

.p1-corpus-dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  align-items: center;
  min-height: 14px;
  margin-top: -6px;
}

.p1-corpus-dialog-actions span {
  color: var(--muted);
  font-size: 13px;
}

#historyPanel {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  flex: 1;
  min-height: 0;
  overflow: hidden;
  gap: 10px;
  padding: 0;
  border: none;
  background: transparent;
}

#historyPanel.is-loading > .page-center-loading,
.writing-reports-panel.is-loading > .page-center-loading {
  position: absolute;
  inset: 0;
  z-index: 8;
  min-height: 0;
  background: rgba(248, 250, 252, 0.58);
  backdrop-filter: blur(2px);
}

.writing-panel {
  position: relative;
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  overflow: hidden;
}

.writing-panel.is-loading .writing-shell {
  opacity: 0.34;
  pointer-events: none;
}

.writing-panel > .page-center-loading {
  position: absolute;
  inset: 0;
  z-index: 8;
  min-height: 0;
  background: rgba(248, 250, 252, 0.58);
  backdrop-filter: blur(2px);
}

.writing-shell {
  display: grid;
  grid-template-columns: minmax(0, 2.35fr) minmax(240px, 280px);
  grid-template-areas:
    "editor result";
  gap: 20px;
  align-items: start;
  min-height: 0;
  height: auto;
}

.writing-calendar-card,
.writing-editor-card,
.writing-result-card {
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--panel);
  padding: 16px;
  box-shadow: var(--shadow-xs);
}

.writing-calendar-card,
.writing-result-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.writing-editor-card {
  grid-area: editor;
  display: grid;
  grid-template-rows: auto auto auto;
  gap: 16px;
  padding: 22px 24px 24px;
  height: auto;
  max-height: calc(100vh - 76px - var(--safe-top) - var(--safe-bottom));
  overflow-y: auto;
  scrollbar-gutter: stable;
  -webkit-overflow-scrolling: touch;
}

.writing-result-card {
  grid-area: result;
  position: sticky;
  top: calc(64px + var(--safe-top));
  align-self: stretch;
  height: 100%;
  max-height: calc(100vh - 76px - var(--safe-top) - var(--safe-bottom));
  overflow: hidden;
  padding: 12px;
  gap: 10px;
}

.writing-checkin-top,
.writing-checkin-bottom {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.writing-checkin-bottom {
  margin-top: auto;
}

.writing-card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 6px;
}

.writing-card-head h2,
.writing-history-head h3 {
  font-size: 18px;
  line-height: 1.25;
}

.writing-icon-button {
  width: 38px;
  min-width: 38px;
  height: 38px;
  min-height: 38px;
  padding: 0;
  display: grid;
  place-items: center;
}

.writing-icon-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#writingRefreshBtn {
  display: none;
}

.writing-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  margin-bottom: 8px;
}

.writing-stats-grid div {
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #fbfcfd;
  padding: 6px 8px;
}

.writing-stats-grid span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.writing-stats-grid strong {
  display: block;
  margin-top: 2px;
  color: var(--ink);
  font-size: 18px;
  line-height: 1;
}

.writing-calendar {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: #fbfcfd;
}

.writing-weekday {
  color: var(--muted);
  text-align: center;
  font-size: 10px;
  font-weight: 800;
}

.writing-day {
  height: 26px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: #fff;
  color: var(--muted);
  padding: 0;
  min-height: 0;
  font-size: 11px;
  font-weight: 800;
}

.writing-day.blank {
  border-color: transparent;
  background: transparent;
  pointer-events: none;
}

.writing-day.saved {
  border-color: rgba(14, 165, 233, 0.35);
  background: #e0f2fe;
  color: #075985;
}

.writing-day.scored {
  border-color: rgba(16, 163, 127, 0.36);
  background: #d1fae5;
  color: #065f46;
}

.writing-day.saved:hover,
.writing-day.scored:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(15, 23, 42, 0.08);
}

.writing-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
  color: var(--muted);
  font-size: 11px;
}

.writing-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.writing-legend i {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid var(--line);
  background: #fff;
}

.writing-legend i.saved { background: #e0f2fe; border-color: #7dd3fc; }
.writing-legend i.scored { background: #d1fae5; border-color: #6ee7b7; }

.writing-task-bar {
  display: grid;
  grid-template-columns: minmax(190px, auto) minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
}

.writing-task-switch {
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(92px, 1fr));
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: #fbfcfd;
  align-self: stretch;
  overflow: hidden;
}

.writing-task-switch::before {
  content: "";
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc((100% - 12px) / 2);
  border-radius: var(--radius-md);
  background: var(--ink);
  box-shadow: var(--shadow-sm);
  transform: translateX(0);
  transition: transform var(--motion-base);
  pointer-events: none;
}

.writing-task-switch[data-active-task="task2"]::before {
  transform: translateX(calc(100% + 4px));
}

.writing-task-option {
  position: relative;
  z-index: 1;
  min-height: 36px;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--muted);
  padding: 0 12px;
  font-weight: 800;
  transition: color var(--motion-fast);
}

.writing-task-option.active {
  color: #fff;
}

.writing-actions-row {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto;
  gap: 12px;
  align-items: stretch;
}

.writing-picker-button {
  min-width: 0;
  min-height: 64px;
  border: 1px solid #d8e7e2;
  border-radius: var(--radius-xl);
  background: linear-gradient(180deg, #ffffff 0%, #f7fbfa 100%);
  color: var(--ink);
  padding: 10px 14px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(19, 32, 38, 0.05);
  transition: transform var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast);
}

.writing-picker-button:hover {
  border-color: var(--accent);
  box-shadow: 0 10px 24px rgba(15, 118, 110, 0.12);
  transform: translateY(-1px);
}

.writing-picker-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.writing-picker-kicker {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.writing-picker-button strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 18px;
  line-height: 1.2;
  font-weight: 850;
}

.writing-picker-chip {
  display: inline-flex;
  align-items: center;
  justify-self: end;
  min-height: 28px;
  padding: 0 10px;
  border-radius: var(--radius-pill);
  background: #e6f4f1;
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.writing-picker-chevron {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
  color: var(--muted);
}

.writing-actions-row select {
  min-width: 0;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #fff;
  color: var(--ink);
  padding: 0 12px;
  font-weight: 650;
}

.writing-prompt-card {
  display: grid;
  gap: 12px;
  border: 1px solid #d8e7e2;
  border-left: 5px solid var(--accent);
  border-radius: var(--radius-lg);
  background: #f8faf9;
  padding: 18px 20px;
}

.writing-prompt-card h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.25;
  font-weight: 850;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.writing-prompt-card p {
  color: #27363d;
  line-height: 1.62;
  white-space: pre-wrap;
  max-width: 86ch;
}

.writing-prompt-text-structured {
  display: grid;
  gap: 0;
  white-space: normal;
}

/* Compact inline loading row shown in the prompt area while switching tasks. */
.writing-task-switch-loading {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 2px;
  color: var(--muted, #8aa0ad);
  font-size: 15px;
}

.writing-task-switch-loading .spinner {
  width: 16px;
  height: 16px;
  border-width: 2px;
}

.writing-prompt-segment {
  display: block;
}

.writing-prompt-context {
  white-space: pre-wrap;
}

.writing-prompt-fixed-question {
  width: fit-content;
  max-width: 100%;
  padding: 3px 8px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 10%, white);
  color: #0f3d35;
  font-weight: 900;
  line-height: 1.5;
  white-space: pre-wrap;
}

.writing-prompt-card mark.writing-highlight-mark {
  background: #ffe69a;
  color: inherit;
  font: inherit;
  line-height: inherit;
  border-radius: 3px;
  padding: 0;
  box-shadow: inset 0 -1px 0 rgba(111, 80, 0, 0.16);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  cursor: pointer;
}

.writing-prompt-card mark.writing-highlight-mark:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 62%, transparent);
  outline-offset: 2px;
}

.writing-highlight-menu {
  position: fixed;
  z-index: 60;
  padding: 6px;
  border: 1px solid #d8dde5;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.16);
}

.writing-highlight-menu button {
  min-width: 112px;
  min-height: 34px;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: #f4f7fb;
  color: #172033;
  font-weight: 700;
  cursor: pointer;
}

.writing-highlight-menu button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 62%, transparent);
  outline-offset: 2px;
}

.writing-highlight-menu.is-delete button {
  background: transparent;
  color: #9a3412;
  border-color: rgba(154, 52, 18, 0.28);
}

.writing-highlight-menu.is-delete button:hover {
  background: rgba(154, 52, 18, 0.08);
  border-color: rgba(154, 52, 18, 0.42);
  color: #7c2d12;
}

body.theme-dark .writing-highlight-menu {
  background: #111827;
  border-color: rgba(148, 163, 184, 0.22);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.36);
}

body.theme-dark .writing-highlight-menu button {
  background: rgba(148, 163, 184, 0.10);
  color: #e5edf6;
}

body.theme-dark .writing-highlight-menu.is-delete button {
  background: transparent;
  border-color: rgba(248, 113, 113, 0.24);
  color: #fca5a5;
}

body.theme-dark .writing-highlight-menu.is-delete button:hover {
  background: rgba(248, 113, 113, 0.10);
  border-color: rgba(248, 113, 113, 0.42);
  color: #fecaca;
}

.writing-highlight-menu button svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.writing-prompt-image {
  position: relative;
  margin: 18px auto 0;
  width: 100%;
  max-width: min(1120px, 100%);
  min-height: clamp(340px, 52vh, 680px);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(126, 139, 153, 0.18);
  border-radius: 14px;
  background: linear-gradient(180deg, #f8fafc, #ffffff);
  overflow: hidden;
}

.writing-prompt-image img {
  max-width: calc(100% - 24px);
  max-height: clamp(320px, 50vh, 660px);
  object-fit: contain;
  display: block;
  border-radius: 8px;
  border: 1px solid #e5e7eb;
  background: #fff;
  cursor: zoom-in;
  opacity: 0;
  transform: scale(0.992);
  transition: opacity 180ms ease, transform 180ms ease;
}

.writing-prompt-image.image-ready img,
.writing-report-prompt-card .writing-prompt-image img {
  opacity: 1;
  transform: none;
}

/* Thumbnail-first loading: the thumb sits in flow (instantly visible), the
   full-res original is absolutely overlaid and fades in when ready. */
.writing-prompt-image img.writing-prompt-image-thumb {
  opacity: 1;
  transform: none;
  cursor: default;
  filter: blur(1px);
}

.writing-prompt-image.has-thumb img[data-writing-image-preview] {
  position: absolute;
  inset: 0;
  margin: auto;
}

.writing-prompt-image.image-ready img.writing-prompt-image-thumb {
  visibility: hidden;
}

.writing-prompt-image.thumb-ready .writing-prompt-image-loading {
  opacity: 0;
  pointer-events: none;
}

.writing-prompt-image-loading {
  position: absolute;
  inset: 12px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  border-radius: 10px;
  background:
    linear-gradient(90deg, rgba(226, 232, 240, 0.68) 0%, rgba(248, 250, 252, 0.96) 42%, rgba(226, 232, 240, 0.68) 84%);
  background-size: 240% 100%;
  color: #607284;
  font-size: 14px;
  font-weight: 850;
  animation: writingImageSkeleton 1.35s ease-in-out infinite;
}

.writing-prompt-image-loading span {
  width: 42px;
  height: 42px;
  border: 3px solid rgba(47, 125, 104, 0.18);
  border-top-color: #2f7d68;
  border-radius: 50%;
  animation: writingImageSpin 0.85s linear infinite;
}

.writing-prompt-image.image-ready .writing-prompt-image-loading {
  opacity: 0;
  pointer-events: none;
}

.writing-prompt-image.image-error .writing-prompt-image-loading {
  animation: none;
  background: #fff7ed;
  color: #9a3412;
}

.writing-prompt-image.image-error .writing-prompt-image-loading span {
  display: none;
}

.writing-prompt-image.image-error .writing-prompt-image-loading strong {
  font-size: 0;
}

.writing-prompt-image.image-error .writing-prompt-image-loading strong::after {
  content: "图表加载失败";
  font-size: 14px;
}

@keyframes writingImageSkeleton {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}

@keyframes writingImageSpin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
