  box-shadow: 0 24px 80px rgba(15, 23, 42, 0.22);
}

.modal-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  padding: 20px 22px 14px;
  border-bottom: 1px solid var(--line);
}

.modal-head h2 {
  margin-top: 4px;
  font-size: 22px;
}

.agent-assistant-card {
  width: min(880px, calc(100vw - 36px));
  max-height: min(760px, calc(100vh - 72px - var(--safe-top)));
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
  border-radius: 12px;
}

.agent-assistant-modal .agent-assistant-card {
  background: rgba(255, 255, 255, 0.90);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-color: rgba(15, 23, 42, 0.10);
  box-shadow: 0 26px 90px rgba(15, 23, 42, 0.24);
}

body.theme-dark .agent-assistant-modal .agent-assistant-card {
  background: rgba(19, 26, 34, 0.92);
  border-color: rgba(148, 163, 184, 0.18);
  box-shadow: 0 26px 90px rgba(0, 0, 0, 0.46);
}

.agent-assistant-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.agent-assistant-search {
  display: grid;
  gap: 8px;
  padding: 18px 22px 0;
  background: rgba(255, 255, 255, 0.72);
}

.agent-assistant-search label {
  font-size: 12px;
  font-weight: 800;
  color: #475569;
}

.agent-assistant-input-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 88px;
  gap: 10px;
}

.agent-assistant-input-row input {
  min-width: 0;
  height: 50px;
  padding: 0 16px;
  border: 1px solid rgba(15, 23, 42, 0.12);
  border-radius: 12px;
  background: #ffffff;
  color: #111827;
  font-size: 15px;
  box-shadow: inset 0 1px 0 rgba(15, 23, 42, 0.03);
}

.agent-assistant-input-row input:focus {
  outline: 3px solid rgba(37, 99, 235, 0.14);
  border-color: #2563eb;
  background: #ffffff;
}

.agent-assistant-input-row button,
.agent-result-open {
  min-height: 44px;
  border: 0;
  border-radius: 12px;
  background: linear-gradient(180deg, #111827 0%, #020617 100%);
  color: #ffffff;
  font-weight: 800;
  padding: 0 16px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.agent-assistant-examples {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 22px 0;
  background: rgba(255, 255, 255, 0.72);
}

.agent-assistant-examples button {
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 999px;
  background: #f8fafc;
  color: #334155;
  min-height: 32px;
  padding: 0 11px;
  font-size: 12px;
  font-weight: 700;
}

.agent-assistant-status {
  min-height: 22px;
  color: #64748b;
  font-size: 13px;
  padding: 14px 22px 12px;
  background: rgba(255, 255, 255, 0.72);
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
}

.agent-assistant-results {
  display: grid;
  gap: 12px;
  overflow: auto;
  padding: 14px 22px 22px;
  min-height: 0;
  overscroll-behavior: contain;
  background: rgba(248, 250, 252, 0.72);
}

.agent-result-card {
  display: grid;
  gap: 11px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 12px;
  background: #ffffff;
  padding: 16px 18px;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.agent-result-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.agent-result-top > div {
  min-width: 0;
}

.agent-result-top strong {
  display: block;
  font-size: 16px;
  color: #111827;
  line-height: 1.25;
}

.agent-result-top span {
  color: #64748b;
  font-size: 12px;
  display: block;
  margin-top: 4px;
}

.agent-result-score {
  flex: 0 0 auto;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-size: 12px;
  font-weight: 800;
  padding: 5px 10px;
  white-space: nowrap;
}

.agent-result-reasons {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.agent-result-reasons span {
  border: 1px solid rgba(37, 99, 235, 0.14);
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.08);
  color: #1d4ed8;
  font-size: 11px;
  font-weight: 760;
  padding: 3px 7px;
}

.agent-result-prompt {
  margin: 0;
  color: #1f2937;
  font-size: 14px;
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.agent-result-actions {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.agent-result-actions.has-two-actions {
  grid-template-columns: auto auto minmax(0, 1fr);
  justify-content: start;
}

.agent-result-open {
  min-height: 38px;
  padding: 0 18px;
}

.agent-result-secondary {
  min-height: 38px;
  border: 1px solid rgba(15, 23, 42, 0.12);
  border-radius: 12px;
  background: #ffffff;
  color: #0f172a;
  font-size: 13px;
  font-weight: 800;
  padding: 0 14px;
}

.agent-result-secondary:hover {
  border-color: rgba(37, 99, 235, 0.28);
  background: #eff6ff;
  color: #1d4ed8;
}

.agent-result-link {
  min-width: 0;
  color: #2563eb;
  font-size: 12px;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-decoration: none;
}

.agent-result-empty {
  border: 1px dashed rgba(15, 23, 42, 0.18);
  border-radius: 12px;
  padding: 18px;
  color: #64748b;
  background: #f8fafc;
}

.agent-jump-highlight {
  position: relative;
  z-index: 2;
  animation: agent-jump-highlight 2.4s ease-out both;
}

@keyframes agent-jump-highlight {
  0% {
    outline: 0 solid rgba(245, 158, 11, 0);
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0);
    background-color: rgba(255, 247, 237, 0.96);
  }
  18% {
    outline: 4px solid rgba(245, 158, 11, 0.28);
    box-shadow: 0 18px 42px rgba(245, 158, 11, 0.22);
    background-color: rgba(255, 247, 237, 0.98);
  }
  100% {
    outline: 0 solid rgba(245, 158, 11, 0);
    box-shadow: none;
    background-color: transparent;
  }
}

.icon-button {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  display: inline-grid;
  place-items: center;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  line-height: 1;
  padding: 0;
  box-shadow: var(--shadow-sm);
  transition: transform var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast), background var(--motion-fast);
}

.icon-button svg {
  display: block;
  width: 20px;
  height: 20px;
  margin: 0;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.3;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-button:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--ink) 18%, var(--line));
  box-shadow: var(--shadow-md);
  background: #fbfcfd;
}

.writing-prompt-modal-card {
  width: min(1460px, calc(100vw - 56px));
  height: min(820px, calc(100vh - 56px));
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  overflow: hidden;
}

.writing-prompt-modal-toolbar {
  display: grid;
  grid-template-columns: minmax(150px, 180px) minmax(0, 1fr) minmax(390px, 430px);
  align-items: center;
  gap: 12px;
  min-height: 82px;
  padding: 8px 18px;
  border-bottom: 1px solid var(--line);
}

.writing-prompt-modal-toolbar .writing-task-switch {
  width: 100%;
  grid-template-columns: repeat(2, minmax(78px, 1fr));
  min-height: 58px;
  border-radius: 14px;
  align-self: center;
}

.writing-prompt-modal-toolbar .writing-task-option {
  min-height: 54px;
  padding: 0 10px;
  font-size: 15px;
}

.writing-prompt-filter-wrap {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  justify-items: end;
  justify-content: center;
  align-self: stretch;
}

.writing-prompt-pattern-panel {
  min-height: 66px;
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border: 1px solid #dbe7e2;
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(20, 184, 166, 0.08), transparent 42%),
    #fbfdfc;
}

.writing-prompt-pattern-panel-head {
  width: auto;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  min-height: 42px;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: default;
}

.writing-prompt-pattern-panel-head span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.writing-prompt-pattern-panel-head strong {
  min-width: max-content;
  color: #174238;
  font-size: 15px;
  font-weight: 950;
  text-align: left;
  line-height: 1.25;
  flex: 1 1 auto;
}

.writing-prompt-pattern-panel-head svg {
  display: none;
}

.writing-prompt-source-filters {
  max-width: none;
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  flex-wrap: nowrap;
}

.writing-source-filter {
  min-height: 30px;
  padding: 5px 10px;
  border-radius: var(--radius-pill);
  border: 1px solid #d8e2e8;
  background: #fff;
  color: #31424b;
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
  flex: 1 1 0;
  min-width: 0;
}

.writing-source-filter span {
  margin-left: 6px;
  color: var(--muted);
  font-weight: 800;
}

.writing-source-filter:hover,
.writing-source-filter.active {
  border-color: #111827;
  background: #111827;
  color: #fff;
}

.writing-source-filter:hover span,
.writing-source-filter.active span {
  color: rgba(255, 255, 255, 0.72);
}

.writing-prompt-pattern-filters {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 2px 4px;
  scrollbar-width: thin;
}

.writing-prompt-pattern-filters.hidden {
  display: none;
}

.writing-prompt-type-filters {
  max-width: 520px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.writing-type-filter,
.writing-pattern-filter {
  min-height: 32px;
  padding: 6px 10px;
  border-radius: var(--radius-pill);
  border: 1px solid #d8e2e8;
  background: #f8fafc;
  color: #31424b;
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
  flex: 0 0 auto;
}

.writing-type-filter span,
.writing-pattern-filter span {
  margin-left: 8px;
  color: var(--muted);
  font-weight: 700;
}

.writing-pattern-filter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  text-align: left;
}

.writing-pattern-filter strong {
  min-width: 0;
  color: inherit;
  font-weight: 860;
  line-height: 1.25;
}

.writing-type-filter:hover,
.writing-type-filter.active,
.writing-pattern-filter:hover,
.writing-pattern-filter.active {
  border-color: var(--accent);
  background: #e7f5f3;
  color: var(--accent-dark);
}

.writing-pattern-filter:hover,
.writing-pattern-filter.active {
  border-color: var(--accent);
  background: #e7f5f3;
  color: var(--accent-dark);
}

.writing-prompt-pattern-badge {
  width: fit-content;
  border: 1px solid rgba(234, 88, 12, 0.2);
  border-radius: 999px;
  background: #fff7ed;
  color: #9a3412;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 850;
}

.writing-prompt-modal-toolbar p {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
  margin: 0;
}

.writing-prompt-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  justify-content: stretch;
  align-content: start;
  gap: 16px;
  padding: 22px;
  overflow-y: auto;
  min-height: 0;
}

.writing-prompt-section {
  min-width: 0;
  display: grid;
  gap: 12px;
}

.writing-prompt-section + .writing-prompt-section {
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.writing-prompt-section-head {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 16px;
}

.writing-prompt-section-head h3 {
  margin: 0;
  color: var(--ink);
  font-size: 18px;
  line-height: 1.25;
  letter-spacing: 0;
}

.writing-prompt-section-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.writing-prompt-section-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 16px;
}

.cambridge-section .writing-prompt-section-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.writing-catalog-slot {
  min-width: 0;
  min-height: 74px;
  border: 1px dashed #cbd5dc;
  border-radius: var(--radius-lg);
  background: #f7f9fa;
  padding: 12px 14px;
  color: #536168;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  text-align: left;
}

.writing-catalog-slot-main {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.writing-catalog-slot-main strong {
  min-width: 0;
  color: #26343b;
  font-size: 14px;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.writing-catalog-slot-main small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.writing-catalog-slot-status {
  justify-self: end;
  border-radius: 999px;
  border: 1px solid #d8e2e8;
  background: #fff;
  color: #6b7c85;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.writing-prompt-grid.is-loading {
  display: grid;
  grid-template-columns: 1fr;
  align-content: center;
  justify-items: center;
}

.writing-prompt-grid.is-loading .page-center-loading {
  min-height: 360px;
  width: 100%;
}

.writing-prompt-empty,
.writing-prompt-load-error {
  grid-column: 1 / -1;
  align-self: center;
  justify-self: center;
  text-align: center;
}

.writing-prompt-load-error {
  display: grid;
  gap: 6px;
  max-width: 520px;
  border: 1px solid #fecaca;
  border-radius: var(--radius-lg);
  background: #fff7f7;
  color: #991b1b;
  padding: 16px 18px;
}

.writing-prompt-load-error span {
  color: #7f1d1d;
  line-height: 1.5;
}

.writing-prompt-choice {
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: #fbfcfd;
  padding: 0;
  overflow: hidden;
  text-align: left;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: transform var(--motion-fast), border-color var(--motion-fast), box-shadow var(--motion-fast), background var(--motion-fast);
}

.writing-prompt-choice.task1-choice {
  height: 392px;
}

.writing-prompt-choice.task2-choice {
  min-height: 148px;
}

.writing-prompt-choice:hover,
.writing-prompt-choice.active {
  border-color: var(--accent);
  box-shadow: 0 8px 24px rgba(15, 118, 110, 0.12);
  background: #fff;
  transform: translateY(-1px);
}

.writing-prompt-choice.missing {
  cursor: not-allowed;
  opacity: 0.68;
  background: #f5f7f8;
  border-style: dashed;
}

.writing-prompt-choice.missing:hover {
  border-color: var(--line);
  box-shadow: none;
  transform: none;
}

.writing-prompt-choice-image {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  place-items: center;
  background: #f7fafb;
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  padding: 8px;
  box-sizing: border-box;
}

.writing-prompt-choice-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  opacity: 0;
  transition: opacity 0.28s ease;
}

.writing-prompt-choice-image img.is-loaded {
  opacity: 1;
}

/* Shimmer while the thumbnail is still downloading. */
.writing-prompt-choice-image {
  position: relative;
}

.writing-prompt-choice-image::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 32%, rgba(255, 255, 255, 0.65) 50%, transparent 68%);
  background-size: 220% 100%;
  animation: writing-thumb-shimmer 1.15s linear infinite;
  pointer-events: none;
}

.writing-prompt-choice-image.placeholder::before,
.writing-prompt-choice-image:has(img.is-loaded)::before {
  content: none;
}

@keyframes writing-thumb-shimmer {
  from { background-position: 200% 0; }
  to { background-position: -20% 0; }
}

.writing-prompt-choice.task1-choice .writing-prompt-choice-body {
  flex: 0 0 auto;
}

.writing-prompt-choice-image.placeholder {
  background:
    linear-gradient(135deg, rgba(15, 118, 110, 0.08), rgba(14, 165, 233, 0.08)),
    #f7fafb;
  color: #6b7c85;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.writing-prompt-choice-body {
  display: grid;
  gap: 5px;
  padding: 12px 14px 13px;
  min-height: 0;
  background: #fff;
  flex: 0 0 auto;
  align-content: start;
}

.writing-prompt-choice-body strong {
  color: var(--accent-dark);
  font-size: 14px;
  font-weight: 900;
  line-height: 1.25;
}

.writing-prompt-choice-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.writing-prompt-choice-head strong {
  color: var(--ink);
  font-size: 15px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.writing-prompt-status {
  justify-self: end;
  border-radius: var(--radius-pill);
  padding: 4px 8px;
  font-size: 11px;
  font-style: normal;
  font-weight: 900;
  line-height: 1;
  border: 1px solid transparent;
}

.writing-prompt-status.status-unpracticed {
  color: #536168;
  background: #eef2f4;
  border-color: #dde5e8;
}

.writing-prompt-status.status-saved {
  color: #8a4d08;
  background: #fff6d8;
  border-color: #f3d77a;
}

.writing-prompt-status.status-scored {
  color: #0f766e;
  background: #dff4f0;
  border-color: #a7dcd3;
}

.writing-prompt-choice-body small {
  color: var(--accent-dark);
  font-weight: 800;
}

.writing-prompt-choice-body span {
  color: var(--muted);
  line-height: 1.38;
  font-size: 13px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.writing-prompt-choice.task2-choice .writing-prompt-choice-body {
  min-height: 148px;
  height: 100%;
  padding: 14px 16px;
}

.writing-prompt-choice.task2-choice .writing-prompt-choice-body span {
  display: block;
  overflow: visible;
  -webkit-line-clamp: unset;
  -webkit-box-orient: initial;
}

.writing-prompt-choice.task2-choice .writing-prompt-preview {
  color: var(--muted);
}

.writing-prompt-card-fixed-line {
  display: inline;
  color: #194d42;
  font-weight: 950;
}

.writing-pill {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  border-radius: var(--radius-pill);
  background: #e0f2fe;
  color: #075985;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 800;
  margin-bottom: 8px;
}

/* ── Label + frame-hint header row ─────────────────────────── */
.writing-answer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.writing-answer-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  margin: 0;
  white-space: nowrap;
}

.writing-answer {
  width: 100%;
  min-height: 500px;
  height: 500px;
  max-height: none;
  border: 1px solid var(--line);
