/* ── Writing Action Panel — collapsible ──────────────────────── */
.writing-action-panel {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.writing-action-panel-toggle {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 20px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  color: var(--muted);
}

/* Horizontal rule */
.writing-action-panel-toggle::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: var(--line);
}

/* Chevron pill floats above the rule */
.wap-chevron {
  position: relative;
  z-index: 1;
  width: 12px;
  height: 12px;
  padding: 4px 10px;
  box-sizing: content-box;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 20px;
  flex-shrink: 0;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              background 0.15s, border-color 0.15s;
}

.writing-action-panel-toggle:hover .wap-chevron {
  background: var(--panel);
  border-color: color-mix(in srgb, var(--line) 80%, var(--accent));
}

/* Collapsed: chevron flips to point down */
.writing-action-panel.is-collapsed .wap-chevron {
  transform: rotate(180deg);
}

/* Smooth body collapse via CSS grid trick */
.writing-action-panel-body {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.writing-action-panel.is-collapsed .writing-action-panel-body {
  grid-template-rows: 0fr;
}

.wap-inner {
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 8px;
}

.writing-submit-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
}

.writing-submit-row #writingScoreBtn,
.writing-submit-row #interviewCustomSubmit {
  grid-column: auto;
}

.writing-inline-edit-actions {
  display: inline-flex;
  align-items: center;
