  border: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 92%, #ffffff);
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.06);
}

.corpus-loading-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.corpus-loading-card span,
.corpus-loading-card em,
.corpus-loading-card strong,
.corpus-loading-card p {
  display: block;
  margin: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(148, 163, 184, 0.12), rgba(148, 163, 184, 0.27), rgba(148, 163, 184, 0.12));
  background-size: 220% 100%;
  animation: shimmer 1.15s linear infinite;
}

.corpus-loading-card span {
  width: 46%;
  height: 22px;
}

.corpus-loading-card em {
  width: 44px;
  height: 30px;
}

.corpus-loading-card strong {
  width: 86%;
  height: 10px;
}

.corpus-loading-card p {
  height: 12px;
}

.corpus-loading-card p:nth-of-type(1) { width: 92%; }
.corpus-loading-card p:nth-of-type(2) { width: 76%; }
.corpus-loading-card p:nth-of-type(3) { width: 84%; }

body.theme-dark .corpus-loading-card {
  background: rgba(15, 23, 42, 0.42);
  border-color: rgba(148, 163, 184, 0.16);
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.22);
}

@media (max-width: 1180px) {
  .corpus-loading-grid {
    grid-template-columns: repeat(2, minmax(220px, 1fr));
  }
}

@media (max-width: 760px) {
  .corpus-loading-state {
    min-height: 420px;
  }

  .corpus-loading-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.writing-feedback {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  overflow-y: auto;
  max-height: 42%;
}

.writing-history-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin: 14px 0 10px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.writing-history-head span {
  color: var(--muted);
  font-size: 12px;
}

.writing-history-list {
  display: grid;
  gap: 8px;
  overflow-y: auto;
  min-height: 0;
  padding-right: 2px;
}

.writing-history-item {
  min-height: 78px;
  display: grid;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfcfd;
  color: var(--ink);
  padding: 10px 12px;
  text-align: left;
}

.writing-history-item:hover,
.writing-history-item.active {
  border-color: var(--accent);
  background: #f0f9f7;
}

.writing-history-item span {
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 800;
}

.writing-history-item strong {
  font-size: 14px;
  line-height: 1.25;
}

.writing-history-item small {
  color: var(--muted);
  font-size: 12px;
}

.writing-reports-panel {
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
  border: 0;
  background: transparent;
  gap: 14px;
}

.writing-reports-panel:not(.hidden) {
  display: flex;
  height: 100%;
}

.writing-report-list {
  min-height: 122px;
  max-height: 122px;
}

.writing-report-tab {
  appearance: none;
}

.writing-report-item-wrap {
  display: inline-flex;
}

.writing-reports-panel .detail-panel {
  border-top: 0;
  padding-top: 0;
}

#detailPanel > .page-center-loading,
#writingReportDetail > .page-center-loading {
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  align-self: stretch;
}

.writing-report-prompt .coaching-content,
.writing-report-answer p {
  color: #263238;
  line-height: 1.68;
}

.muted-badge {
  background: #eef2f6;
  color: var(--muted);
}

.busy-bar {
  position: fixed;
  inset: 0 0 0 var(--sidebar-width);
  z-index: 260;
  box-sizing: border-box;
  border: 0;
  border-radius: 0;
  background: rgba(248, 250, 252, 0.58);
  color: var(--muted);
  padding: calc(58px + var(--safe-top)) clamp(18px, 3vw, 40px) calc(24px + var(--safe-bottom));
  display: grid;
  place-items: center;
  backdrop-filter: blur(2px);
  pointer-events: auto;
}

.busy-bar-card {
  min-width: min(260px, 70vw);
  max-width: 420px;
  min-height: 58px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  color: var(--ink);
  padding: 16px 18px;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  text-align: center;
  box-shadow: 0 14px 38px rgba(15, 23, 42, 0.08);
}

.busy-bar-card .spinner {
  flex: 0 0 auto;
}

.busy-bar-card #busyText {
  display: block;
  min-width: 0;
}

.spinner {
  width: 18px;
  height: 18px;
  border: 3px solid color-mix(in srgb, var(--accent) 18%, var(--line));
  border-top-color: var(--accent);
  border-radius: 50%;
  flex: 0 0 auto;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.exam-status {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  box-sizing: border-box;
  height: 64px;
  min-height: 64px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
  overflow: visible;
  position: relative;
  z-index: 120;
}

.exam-status .p2-corpus-prep {
  flex: 1 1 560px;
  min-width: 0;
  max-width: min(760px, 58vw);
  height: 48px;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  overflow: visible;
}

.exam-status .p2-corpus-prep .p2-corpus-prep-copy {
  display: none;
}

.exam-status .p2-corpus-prep strong,
.exam-status .p2-corpus-prep span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.exam-status .p2-corpus-prep-trigger {
  width: 100%;
  min-width: 0;
  height: 46px;
}

.exam-status .p2-corpus-prep {
  transition:
    opacity 220ms ease,
    transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    filter 220ms ease !important;
  will-change: opacity, transform, filter;
}

.exam-status .p2-corpus-prep.p2-prep-entering {
  animation: p2PrepEnter 360ms cubic-bezier(0.18, 1.12, 0.28, 1) both !important;
}

.exam-status .p2-corpus-prep.p2-prep-leaving {
  opacity: 0 !important;
  transform: translateY(-6px) scale(0.975) !important;
  filter: blur(1px) saturate(1.08) brightness(1.05) !important;
  pointer-events: none !important;
}

@keyframes p2PrepEnter {
  0% {
    opacity: 0;
    transform: translateY(7px) scale(0.965);
    filter: blur(2px) saturate(0.95) brightness(1.12);
  }
  54% {
    opacity: 1;
    transform: translateY(-2px) scale(1.012);
    filter: blur(0) saturate(1.12) brightness(1.08);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: none;
  }
}

.exam-status strong {
  display: block;
  font-size: 17px;
}

.exam-status span {
  display: block;
  margin-top: 4px;
  color: var(--muted);
}

.inline-timer {
  min-width: 96px;
  text-align: center;
  font-size: 30px;
  line-height: 1;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.exam-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  margin-left: auto;
  flex: 0 0 auto;
  min-width: max-content;
}

.exam-actions .p1-corpus-peek-button.is-empty-slot {
  visibility: hidden;
  pointer-events: none;
}

.exam-actions .p2-corpus-peek-button.is-empty-slot {
  opacity: 0.92;
  filter: none;
}

.exam-actions .p1-corpus-peek-button.is-loading-slot {
  opacity: 0.92;
  cursor: pointer;
  pointer-events: auto;
}

.exam-actions .p1-corpus-peek-button.is-loading-slot svg {
  opacity: 1;
}

.mobile-font-options {
  display: none;
}

.phase-meter {
  height: 7px;
  border-radius: 999px;
  background: #e7ecef;
  overflow: hidden;
  margin: 10px 0 12px;
}

.phase-meter span {
  display: block;
  width: 0;
  height: 100%;
  background: var(--accent);
  transition: width 180ms linear;
}

.cue-top,
.prompt-card.cue-prompt {
  border-left: 5px solid var(--accent);
  background: #f8faf9;
  padding: 20px 24px;
  line-height: 1.5;
  margin-bottom: 0;
}

.cue-detail {
  border-left: 5px solid var(--accent);
  line-height: 1.5;
}

.cue-detail + .turn-report-table {
  margin-top: -1px;
}

.cue-detail + .turn-report-table thead th {
  border-top: 0;
}

.cue-top h2,
.prompt-card.cue-prompt h2,
.cue-detail h2 {
  font-size: 24px;
  line-height: 1.25;
  margin-bottom: 16px;
}

.cue-label,
.cue-detail p:first-of-type {
  font-weight: 800;
  margin-bottom: 8px;
}

.cue-top ul,
.prompt-card.cue-prompt ul,
.cue-detail ul {
  margin: 0 0 16px 22px;
  padding: 0;
}

.cue-top li,
.prompt-card.cue-prompt li,
.cue-detail li {
  margin: 6px 0;
}

/* ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   P3 LAUNCH PANEL — canonical single definition
   All P3 base layout and style rules live here. No duplicates elsewhere.
   ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */

/* ── Outer panel card ────────────────────────────────────────────── */
.p3-topic-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  background: color-mix(in srgb, var(--panel) 97%, #f2fbf8);
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 18px;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.07);
}

/* ── Compact title header (shown outside view-p3) ────────────────── */
.p3-topic-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--line) 76%, transparent);
  border-radius: 14px;
  background: var(--panel);
}

.p3-topic-copy {
  max-width: none;
}

.p3-topic-panel label {
  display: block;
  margin-bottom: 2px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.p3-topic-panel h2 {
  margin: 0;
  color: var(--ink);
  font-size: clamp(20px, 1.6vw, 24px);
  line-height: 1.1;
  letter-spacing: 0;
}

.p3-topic-panel p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.48;
  max-width: 76ch;
}

/* ── Single-column launch body ───────────────────────────────────── */
.p3-topic-body {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

/* ── Section cards (mode-row & any launch-section) ───────────────── */
.p3-mode-row,
.p3-launch-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--line) 76%, transparent);
  border-radius: 16px;
  background: var(--panel);
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.04);
}

.p3-launch-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ── Intensity toggle switch ─────────────────────────────────────── */
.p3-mode-switch {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  position: relative;
}

.p3-mode-switch::before {
  content: none;
}

.p3-mode-switch.high-intensity::before {
  transform: none;
}

.p3-mode-option {
  min-height: 38px;
  min-width: 0;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  font-size: 14px;
  font-weight: 720;
  padding: 0 14px;
  white-space: nowrap;
  position: relative;
  z-index: 1;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
}

.p3-mode-option.active {
  background: var(--ink);
  color: #fff;
  box-shadow: 0 6px 16px rgba(21, 32, 39, 0.14);
}

body.theme-dark .p3-mode-option.active {
  background: var(--dark-surface-2, #243647);
  color: var(--dark-primary-text, #f8fbfd);
}

.p3-mode-help {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

/* ── Source selection grid ───────────────────────────────────────── */
.p3-source-grid,
.p3-focus-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.p3-source-option,
.p3-focus-option {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 68px;
  padding: 12px 14px 12px 18px;
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 14px;
  background: var(--panel);
  color: var(--ink);
  font-size: 14px;
  font-weight: 720;
  text-align: left;
  position: relative;
  cursor: pointer;
  transition: border-color 160ms, background 160ms, box-shadow 160ms;
}

.p3-source-option::before,
.p3-focus-option::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 13px;
  bottom: 13px;
  width: 3px;
  border-radius: 999px;
  background: transparent;
  transition: background 160ms;
}

.p3-source-option:hover,
.p3-focus-option:hover {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  background: color-mix(in srgb, var(--accent) 4%, var(--panel));
}

.p3-source-option.active,
.p3-focus-option.active {
  border-color: color-mix(in srgb, var(--accent) 52%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
  color: var(--accent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 18%, transparent),
    0 10px 22px color-mix(in srgb, var(--accent) 10%, transparent);
  transform: translateY(-1px);
}

.p3-source-option.active::before,
.p3-focus-option.active::before {
  background: var(--accent);
}

.p3-source-option strong,
.p3-focus-option strong {
  color: inherit;
  font-size: 15px;
  line-height: 1.25;
}

.p3-source-option small,
.p3-focus-option small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  max-width: 44ch;
}

.p3-source-option.active small,
.p3-focus-option.active small {
  color: color-mix(in srgb, var(--accent) 72%, var(--muted));
}

/* ── Custom theme input ──────────────────────────────────────────── */
.p3-custom-input {
  width: 100%;
  min-height: 46px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0 14px;
  color: var(--ink);
  background: var(--panel);
  font-size: 15px;
}

.p3-custom-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
}

/* ── Source context ──────────────────────────────────────────────── */
.p3-source-context {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}

.p3-context-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  align-items: stretch;
}

/* ── Plan preview ────────────────────────────────────────────────── */
.p3-plan-preview {
  position: relative;
  min-height: 280px;
  max-height: min(48vh, 560px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 18px;
  background: var(--panel);
  padding: 18px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
}

.p3-plan-preview.is-refreshing .p3-plan-head,
.p3-plan-preview.is-refreshing .p3-plan-list {
  opacity: 0.48;
}

.p3-plan-refresh-overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  pointer-events: none;
  background: color-mix(in srgb, var(--panel) 64%, transparent);
  backdrop-filter: blur(1.5px);
}

.p3-plan-refresh-overlay span {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 16px;
  border: 1px solid color-mix(in srgb, var(--accent) 24%, var(--line));
  border-radius: 999px;
  background: var(--panel);
  color: var(--accent);
  font-size: 13px;
  font-weight: 760;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
}

.p3-plan-empty {
  min-height: 230px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  text-align: center;
  color: var(--muted);
}

.p3-plan-empty strong {
  color: var(--ink);
  font-size: 16px;
}

.p3-plan-empty span {
  max-width: 560px;
  line-height: 1.55;
}

.p3-plan-error {
  color: #9f3a2f;
}

.p3-plan-error strong {
  color: #8f2f25;
}

.p3-plan-error small {
  max-width: 560px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
}

/* ── Bank picker entry (shown in plan-preview when no card selected) ── */
.p3-bank-entry {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  height: 100%;
  min-height: 320px;
  text-align: center;
  padding: 32px 24px;
}

.p3-source-context .p3-bank-entry {
  min-height: 190px;
}

.p3-bank-entry-select {
  width: 100%;
  border: 1px dashed color-mix(in srgb, var(--accent) 42%, var(--line));
  border-radius: 16px;
  background: color-mix(in srgb, var(--accent) 4%, var(--panel));
  color: inherit;
  cursor: pointer;
  transition: border-color 160ms, background 160ms, box-shadow 160ms, transform 120ms;
}

.p3-bank-entry-select:hover,
.p3-bank-entry-select:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--accent) 68%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
  box-shadow: 0 14px 30px color-mix(in srgb, var(--accent) 12%, transparent);
  transform: translateY(-1px);
}

.p3-bank-entry-icon {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--line));
  display: grid;
  place-items: center;
  color: var(--accent);
}

.p3-bank-entry-icon svg {
  width: 28px;
  height: 28px;
}

.p3-bank-entry strong {
  color: var(--ink);
  font-size: 17px;
  font-weight: 760;
  line-height: 1.25;
}

.p3-bank-entry span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 640;
  line-height: 1.55;
  max-width: 36ch;
}

.p3-bank-entry-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 4px;
  padding: 0 22px;
  height: 44px;
  border: 0;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 14px;
  font-weight: 760;
  cursor: pointer;
  transition: background 150ms, transform 100ms, box-shadow 150ms;
  box-shadow: 0 8px 20px color-mix(in srgb, var(--accent) 22%, transparent);
}

.p3-bank-entry-btn svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.p3-bank-entry-btn:hover {
  background: var(--accent-dark, #0f766e);
  transform: translateY(-1px);
  box-shadow: 0 12px 24px color-mix(in srgb, var(--accent) 28%, transparent);
}

.p3-bank-entry.is-loading .p3-bank-entry-icon {
  animation: p3-bank-pulse 1.4s ease-in-out infinite;
}

.p3-bank-entry.is-loading strong,
.p3-bank-entry.is-empty strong {
  color: var(--muted);
  font-weight: 700;
}

@keyframes p3-bank-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.45; }
}

/* dark mode */
body.theme-dark .p3-bank-entry-icon {
  background: color-mix(in srgb, var(--ds-l2-bg) 88%, #34d399);
  border-color: rgba(52, 211, 153, 0.24);
  color: #34d399;
}

body.theme-dark.font-academic .p3-bank-entry-icon {
  background: color-mix(in srgb, var(--ds-l2-bg) 88%, #c6a071);
  border-color: rgba(198, 160, 113, 0.24);
  color: #c6a071;
}

body.theme-dark.font-popular .p3-bank-entry-icon {
  background: color-mix(in srgb, var(--ds-l2-bg) 88%, #7bb7ff);
  border-color: rgba(123, 183, 255, 0.24);
  color: #7bb7ff;
}

.p3-plan-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.p3-plan-card {
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 14px;
  background: var(--surface, #fff);
  padding: 15px 16px;
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr);
  align-items: start;
  gap: 10px 18px;
  box-shadow: 0 4px 12px rgba(20, 40, 48, 0.04);
}

.p3-plan-card-top {
  display: flex;
  justify-content: flex-start;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}

.p3-plan-card-top span,
.p3-plan-card-top em {
  border-radius: 999px;
  font-size: 11px;
  font-style: normal;
  font-weight: 780;
  padding: 4px 8px;
}

.p3-plan-card-top span {
  background: #eef2f7;
  color: #475569;
}

.p3-plan-card-top em {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface, #fff));
  color: var(--accent);
}

.p3-plan-card p {
  grid-column: 2;
  grid-row: 1;
  align-self: start;
  margin: 0;
  color: var(--ink);
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  text-align: left;
}

.p3-plan-coachline {
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--line));
  border-radius: 14px;
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
  padding: 11px 13px;
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 14px;
}

.p3-plan-coachline strong {
  color: var(--accent);
  font-size: 12px;
  white-space: nowrap;
}

.p3-plan-coachline span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.45;
}

.p3-target-moves {
  grid-column: 2;
  grid-row: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.p3-target-moves span {
  border-radius: 999px;
  background: #f5f7f8;
  color: var(--muted);
  font-size: 11px;
  font-weight: 720;
  padding: 4px 8px;
}

/* ── Start row & action buttons ──────────────────────────────────── */
.p3-start-row {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 0 2px;
}

.p3-plan-status {
  margin-right: auto;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.p3-generate-button,
.p3-start-button {
  min-height: 46px;
  min-width: 160px;
  border: 0;
  border-radius: 12px;
  font-weight: 780;
  font-size: 15px;
  padding: 0 24px;
  cursor: pointer;
  transition: background 160ms, box-shadow 160ms, transform 100ms;
}

.p3-generate-button {
  background: var(--ink);
  color: #fff;
  box-shadow: 0 8px 20px rgba(21, 32, 39, 0.16);
}

.p3-start-button {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 12px 24px color-mix(in srgb, var(--accent) 22%, transparent);
}

.p3-generate-button:hover {
  background: color-mix(in srgb, var(--ink) 80%, white);
}

.p3-start-button:hover {
  background: var(--accent-dark, #0f766e);
}

.p3-generate-button:disabled,
.p3-start-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

/* ── Bank picker modal ───────────────────────────────────────────── */
.p3-bank-picker-modal-card {
  width: min(940px, calc(100vw - 48px));
  height: min(720px, calc(100vh - 56px));
  max-height: min(760px, calc(100vh - 56px));
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}

.p3-bank-picker-list {
  padding: 18px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  align-content: start;
  gap: 16px;
  min-height: 0;
  overflow: auto;
}

.p3-bank-picker-loading {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 100%;
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 16px;
  background:
    radial-gradient(circle at 42% 34%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 32%),
    color-mix(in srgb, var(--panel) 94%, transparent);
  color: var(--muted, #64748b);
  font-size: 14px;
  font-weight: 650;
  text-align: center;
}

.p3-bank-picker-loading .spinner {
  margin-bottom: 2px;
}

.p3-bank-picker-loading strong {
  color: var(--ink);
  font-size: 16px;
  font-weight: 850;
}

.p3-bank-picker-loading small {
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
}

.p3-bank-picker-loading-lines {
  width: min(360px, 70%);
  display: grid;
  gap: 9px;
  margin-top: 8px;
}

.p3-bank-picker-loading-lines span {
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(148, 163, 184, 0.12), rgba(148, 163, 184, 0.32), rgba(148, 163, 184, 0.12));
  background-size: 180% 100%;
  animation: corpusPeekLoading 1.15s ease-in-out infinite;
}

.p3-bank-picker-loading-lines span:nth-child(2) {
  width: 78%;
  justify-self: center;
}

.p3-bank-picker-loading-lines span:nth-child(3) {
  width: 58%;
  justify-self: center;
}

.p3-bank-picker-card {
  --p3-bank-progress-fill: 0%;
  --p3-bank-progress-color: color-mix(in srgb, var(--accent) 14%, #ffffff);
  width: 100%;
  appearance: none;
  cursor: pointer;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: linear-gradient(
    90deg,
    var(--p3-bank-progress-color) 0 var(--p3-bank-progress-fill),
    var(--panel) var(--p3-bank-progress-fill) 100%
  );
  padding: 18px;
  display: grid;
  gap: 12px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 320ms cubic-bezier(0.22, 1, 0.36, 1);
}

body.theme-dark .p3-bank-picker-card {
  --p3-bank-progress-color: color-mix(in srgb, var(--accent) 16%, var(--panel));
}

.p3-bank-picker-card--none {
  --p3-bank-progress-fill: 0%;
}

.p3-bank-picker-card--partial {
  --p3-bank-progress-fill: 50%;
}

.p3-bank-picker-card--complete {
  --p3-bank-progress-fill: 100%;
}

.p3-bank-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0;
}

.p3-bank-card-top em {
  font-style: normal;
  color: var(--muted);
}

.p3-bank-picker-card strong {
  color: var(--ink);
  font-size: clamp(18px, 1.6vw, 24px);
  line-height: 1.18;
}

.p3-bank-picker-card ul {
  margin: 0;
  padding-left: 20px;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.45;
}

.p3-bank-picker-cycle-status {
  width: max-content;
  min-height: 28px;
  margin-top: 10px;
  padding: 5px 10px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 7px;
  background: color-mix(in srgb, var(--accent) 9%, var(--panel));
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  font-size: 12px;
  font-weight: 850;
}

.p3-bank-round-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 28px;
}

.p3-bank-round-chip {
  min-height: 26px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  box-sizing: border-box;
  font-size: 12px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0;
  transition: color 180ms ease, border-color 180ms ease, background-color 180ms ease, opacity 180ms ease;
}

.p3-bank-round-chip.is-next {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--line));
  background: color-mix(in srgb, var(--accent) 14%, var(--panel));
  color: var(--accent);
}

.p3-bank-round-chip.is-dim {
  border-color: color-mix(in srgb, var(--line) 82%, transparent);
  background: color-mix(in srgb, var(--panel) 88%, var(--muted));
  color: color-mix(in srgb, var(--muted) 74%, var(--panel));
  opacity: 0.74;
}

.p3-bank-replay-dialog {
  width: min(480px, calc(100vw - 40px));
  display: grid;
  gap: 12px;
}

.p3-bank-replay-dialog h3 {
  margin: 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.25;
}

.p3-bank-replay-dialog p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.p3-bank-replay-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.p3-bank-replay-option {
  min-height: 38px;
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: 7px;
  background: color-mix(in srgb, var(--accent) 9%, var(--panel));
  color: var(--ink);
  font-weight: 800;
  cursor: pointer;
}

.p3-bank-replay-option:hover,
.p3-bank-replay-option:focus-visible {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 18%, var(--panel));
  color: var(--accent);
  outline: none;
}

.p3-cycle-notice-dialog {
  max-width: 420px;
  display: grid;
  gap: 12px;
}

.p3-cycle-notice-kicker {
  width: max-content;
  border-radius: 999px;
  padding: 4px 9px;
  background: color-mix(in srgb, var(--accent) 12%, var(--panel));
  color: var(--accent);
  font-size: 12px;
  font-weight: 850;
}

.p3-cycle-notice-dialog h3 {
  margin: 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.25;
}

.p3-cycle-notice-dialog p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.p3-cycle-notice-dialog-complete {
  max-width: min(620px, calc(100vw - 40px));
  padding: 28px 30px 24px;
  gap: 16px;
  border-color: color-mix(in srgb, var(--accent) 36%, var(--line));
  box-shadow:
    0 26px 70px rgba(0, 0, 0, 0.24),
    0 0 0 1px color-mix(in srgb, var(--accent) 12%, transparent) inset;
}

.p3-cycle-notice-dialog-complete .p3-cycle-notice-kicker {
  padding: 5px 12px;
}

.p3-cycle-notice-dialog-complete h3 {
  font-size: clamp(26px, 3vw, 34px);
  letter-spacing: 0;
}

.p3-cycle-notice-dialog-complete p {
  max-width: 54ch;
  font-size: 15px;
}

.p3-cycle-start {
  background: var(--accent);
  color: #fff;
}

.p2-brainstorm-detail-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.p2-brainstorm-practice-btn {
  flex: 0 0 30px;
  inline-size: 30px;
  block-size: 30px;
  min-inline-size: 30px;
  min-block-size: 30px;
  margin: 0;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
  color: var(--accent);
  cursor: pointer;
}

.p2-brainstorm-practice-btn svg {
  display: block;
  inline-size: 14px;
  block-size: 14px;
  margin: 0;
}

.p2-brainstorm-practice-btn:hover,
.p2-brainstorm-practice-btn:focus-visible {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 18%, var(--panel));
  outline: none;
}

.p3-bank-picker-card--partial .p3-bank-card-top em,
.p3-bank-picker-card--complete .p3-bank-card-top em {
  color: var(--accent);
}

.p3-bank-picker-card:hover,
.p3-bank-picker-card:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--accent) 58%, var(--line));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 15%, transparent),
    0 12px 28px color-mix(in srgb, var(--accent) 12%, transparent);
}

.p3-bank-picker-card.active {
  outline: none;
  border-color: color-mix(in srgb, var(--accent) 58%, var(--line));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 15%, transparent),
    0 12px 28px color-mix(in srgb, var(--accent) 12%, transparent);
}

.p3-bank-context-card {
  min-height: 0;
}

/* ── Exam brief tile ─────────────────────────────────────────────── */
.p3-exam-brief {
  min-width: 224px;
  padding: 11px 13px;
  border: 1px solid color-mix(in srgb, var(--accent) 16%, var(--line));
  border-radius: 14px;
  background: color-mix(in srgb, var(--accent) 6%, var(--panel));
  display: grid;
  align-content: center;
  gap: 8px;
  box-shadow: none;
}

.p3-exam-brief span {
  width: max-content;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, var(--panel));
  color: var(--accent);
  font-size: 12px;
  font-weight: 850;
  padding: 5px 10px;
}

.p3-exam-brief strong {
  color: var(--ink);
  line-height: 1.35;
}

.p3-exam-brief small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 720;
}

/* ── Flow steps ──────────────────────────────────────────────────── */
.p3-flow-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.p3-flow-steps span {
  min-height: 38px;
  border: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
  color: var(--muted);
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 820;
}

.p3-flow-steps span.active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

/* ── Context / corpus cards ──────────────────────────────────────── */
.p3-context-note,
.p3-source-corpus-card {
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 12px;
  background: var(--surface, #f8fbfc);
  padding: 12px 14px;
  display: grid;
  align-content: center;
  gap: 5px;
}

.p3-context-note strong,
.p3-source-corpus-card strong {
  color: var(--ink);
  font-size: 14px;
  line-height: 1.35;
}

.p3-context-note span,
.p3-source-corpus-card span,
.p3-source-corpus-card p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.p3-source-corpus-card p {
  margin: 0;
  font-weight: 600;
  max-width: 78ch;
}

.p3-context-warning {
  border-color: rgba(245, 158, 11, 0.38);
  background: #fffbeb;
}

.p3-corpus-context {
  display: grid;
  grid-template-columns: minmax(220px, 0.42fr) 1fr;
  gap: 12px;
  align-items: stretch;
}

/* ── Selected bank card in context ──────────────────────────────── */
.p3-selected-bank-card {
  width: 100%;
  margin-inline: 0;
  min-height: 0;
  cursor: pointer;
}

.p3-empty-bank-card {
  border-style: dashed;
  background: color-mix(in srgb, var(--accent) 3%, var(--panel));
}

.p3-bank-empty-card-body {
  border-top: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  padding-top: 12px;
  display: grid;
  gap: 5px;
  justify-items: center;
  text-align: center;
}

.p3-bank-empty-card-body strong {
  color: var(--accent);
  font-size: 15px;
  line-height: 1.35;
}

.p3-bank-empty-card-body p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.5;
}

/* ── Report card within P3 context ──────────────────────────────── */
.p3-source-report-card {
  position: relative;
  width: 100%;
  min-width: 0;
  min-height: 116px;
  border: 1px solid color-mix(in srgb, #2563eb 28%, var(--line));
  border-radius: 12px;
  background: var(--panel);
  padding: 12px 14px;
  display: grid;
  align-content: start;
  gap: 9px;
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.08);
}

.p3-source-card-menu {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 22px;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  border-radius: 4px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  padding: 0;
}

.p3-source-card-menu span {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: -5px 0 0 currentColor, 5px 0 0 currentColor;
}

/* Reserve room on the right so the Band pill never slides under the ⋯ menu. */
.p3-source-report-card .history-item-top {
  padding-right: 32px;
}

.p3-source-card-menu:hover,
.p3-source-card-menu:focus-visible {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--ink);
}

.p3-source-report-menu {
  top: 38px;
  right: 10px;
  min-width: 104px;
}

.p3-linked-corpus-line {
  min-width: 0;
  margin-top: 2px;
  padding-top: 8px;
  border-top: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  display: grid;
  gap: 3px;
}

.p3-linked-corpus-line span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.p3-linked-corpus-line strong {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink);
  font-size: 13px;
  font-weight: 820;
}

/* ── Bank empty state ────────────────────────────────────────────── */
.p3-bank-empty {
  border: 1px dashed color-mix(in srgb, var(--line) 64%, transparent);
  border-radius: 12px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 720;
  padding: 18px;
  background: color-mix(in srgb, var(--panel) 92%, transparent);
}

/* ── Topic chips ─────────────────────────────────────────────────── */
.topic-chips {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
  margin-top: 0;
}

.topic-chip {
  min-height: 68px;
  white-space: normal;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 15px;
  color: var(--ink);
  font-size: 15px;
  font-weight: 650;
  text-align: left;
  cursor: pointer;
  transition: all 160ms ease;
}

.topic-chip:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
  transform: translateY(-1px);
}

.topic-chip.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
  box-shadow: 0 8px 20px color-mix(in srgb, var(--accent) 18%, transparent);
}

/* ── .hidden utility (sections toggled by JS) ────────────────────── */
.p3-launch-section.hidden,
.p3-plan-preview.hidden {
  display: none !important;
}

/* ── view-p3: hide the title header (compact workbench mode) ─────── */
body.view-p3 .p3-topic-head {
  display: none;
}

/* ── Responsive: tablet ≤ 1100px ─────────────────────────────────── */
@media (max-width: 1100px) {
  .p3-plan-preview {
    min-height: 320px;
  }
}

/* ── Responsive: ≤ 980px (two-col source grid) ───────────────────── */
@media (max-width: 980px) {
  .p3-source-grid,
  .p3-focus-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .p3-context-grid,
  .p3-corpus-context {
    grid-template-columns: 1fr;
  }

  .p3-flow-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ── Responsive: mobile ≤ 640px ──────────────────────────────────── */
@media (max-width: 640px) {
  .p3-topic-panel {
    padding: 12px;
  }

  .p3-source-grid,
  .p3-focus-grid {
    display: flex;
    flex-direction: column;
  }

  .p3-flow-steps {
    grid-template-columns: 1fr;
  }

  .p3-plan-coachline {
    align-items: flex-start;
    flex-direction: column;
  }

  .p3-plan-card {
    grid-template-columns: 1fr;
  }

  .p3-plan-card p,
  .p3-target-moves {
    grid-column: 1;
    grid-row: auto;
  }

  .p3-start-row {
    align-items: stretch;
    flex-direction: column;
  }

  .p3-plan-status {
    margin-right: 0;
  }

  .topic-chips {
    grid-template-columns: 1fr;
  }

  .p3-generate-button,
  .p3-start-button {
    width: 100%;
  }
}

.home-panel {
  display: grid;
  gap: 20px;
  min-height: calc(100vh - 128px);
  align-content: start;
}

.home-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  min-height: 190px;
  padding: 30px 32px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}

.home-copy {
  max-width: 820px;
}

.home-copy h2 {
  margin: 0 0 14px;
  color: var(--ink);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.05;
  letter-spacing: 0;
}

.home-copy p {
  margin: 0;
  max-width: 720px;
  color: var(--muted);
  font-size: 17px;
  line-height: 1.72;
}

.home-practice-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  padding: 0 32px 32px;
}

.home-practice-card {
  min-height: 210px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  display: grid;
  grid-template-rows: auto auto 1fr;
  align-content: start;
  gap: 12px;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.05);
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

.home-practice-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
  box-shadow: 0 18px 36px rgba(15, 23, 42, 0.09);
}

.home-practice-card:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 28%, transparent);
  outline-offset: 3px;
}

.home-card-kicker {
  width: fit-content;
  min-height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  color: var(--accent-dark);
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  font-size: 13px;
  font-weight: 820;
}

.home-practice-card strong {
  margin: 2px 0 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.18;
  letter-spacing: 0;
}

.home-practice-card small {
  margin: 0;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.58;
}

.home-practice-card.tone-p1 .home-card-kicker {
  color: var(--tone-p1-border);
  background: var(--tone-p1-surface);
}

.home-practice-card.tone-p2 .home-card-kicker {
  color: var(--tone-p2-border);
  background: var(--tone-p2-surface);
}

.home-practice-card.tone-p3 .home-card-kicker {
  color: var(--tone-p3-border);
  background: var(--tone-p3-surface);
}

.home-practice-card.tone-mock .home-card-kicker {
  color: var(--tone-mock-border);
  background: var(--tone-mock-surface);
}

.practice-grid {
  display: grid;
  grid-template-columns: minmax(360px, 1.06fr) minmax(320px, 0.94fr);
  gap: 18px;
  align-items: stretch;
  height: 100%;
  min-height: 0;
}

.practice-grid.p2-mode {
  grid-template-columns: minmax(360px, 1.06fr) minmax(320px, 0.94fr);
}

.practice-grid.practice-enter {
  animation: practiceEnter 260ms ease-out;
}

@keyframes practiceEnter {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.prompt-pane {
  background: #fafbfc;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.section-label {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0;
  margin-bottom: 10px;
}

.prompt-card {
  position: relative;
  flex: 1;
  border-left: 5px solid var(--accent);
  background: #f8faf9;
  padding: 22px;
  line-height: 1.38;
  display: grid;
  place-items: center;
}

.prompt-card.short-prompt {
  min-height: 220px;
  display: grid;
  place-items: center;
  text-align: center;
  font-size: clamp(24px, 1.9vw, 32px);
  font-weight: 760;
}

.prompt-card.medium-prompt {
  font-size: 24px;
  font-weight: 720;
}

.prompt-card.long-prompt {
  font-size: 18px;
  line-height: 1.55;
}

.prompt-card.cue-prompt {
  min-height: 300px;
  font-size: 18px;
  place-items: start;
  text-align: left;
}

.follow-up {
  margin-top: 14px;
  color: var(--warn);
  line-height: 1.45;
}

.follow-up:empty {
  display: none;
}

.prompt-followup-tag {
  position: absolute;
  top: 22px;
  left: 24px;
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 10px;
  border: 1px solid rgba(180, 83, 9, 0.26);
  border-radius: 999px;
  background: #fef3c7;
  color: #92400e;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.01em;
}

.prompt-card:has(.prompt-followup-tag) {
  padding-top: 62px;
}

.tts-player {
  width: 100%;
  margin-top: 14px;
}

.recorder-pane {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: #fafbfc;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px;
  min-height: 0;
  position: relative;
}

.recorder-pane .inline-timer {
  position: absolute;
  top: 16px;
  right: 16px;
  font-size: 32px;
  font-weight: 700;
  color: var(--ink);
}

.inline-timer.timer-analyzing {
  animation: timerPulse 1.2s ease-in-out infinite;
}

@keyframes timerPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.record-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  position: relative;
  min-height: 0;
}

.record-control {
  width: min(300px, 42vw);
  aspect-ratio: 1 / 1;
  border: 0;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 8px;
  padding: 26px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.16);
  position: relative;
}

.icon-exit-button {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 56px;
  height: 56px;
  min-width: 56px;
  padding: 0;
  border-radius: 50%;
  border: 0;
  background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
  color: #fff;
  display: inline-grid;
  place-items: center;
  box-shadow: 0 10px 22px rgba(220, 38, 38, 0.24);
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
  animation: exitBreath 1.8s ease-in-out infinite;
}

.icon-exit-button svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.8;
  stroke-linecap: round;
}

.icon-exit-button:hover {
  background: linear-gradient(180deg, #f87171 0%, #ef4444 100%);
  box-shadow: 0 12px 26px rgba(220, 38, 38, 0.32);
}

.icon-exit-button:active {
  transform: translateY(-50%) scale(0.94);
}

@keyframes exitBreath {
  0%, 100% { box-shadow: 0 6px 14px rgba(224, 73, 73, 0.08); }
  50% { box-shadow: 0 6px 18px rgba(224, 73, 73, 0.18); }
}

.record-control:hover { background: var(--accent-dark); }
.record-control:disabled {
  opacity: 0.72;
}
.record-control.loading,
.record-control.examiner_loading,
.record-control.preparing { background: var(--blue) !important; cursor: wait; }
.record-control.examiner_playing,
.record-control.turn_saved { background: #45535b !important; cursor: wait; }
.record-control.recording { background: var(--danger) !important; }
.record-control.processing,
.record-control.scoring {
  background: #d97706 !important;
  cursor: wait;
  animation: btnPulse 1.2s ease-in-out infinite;
}

body.font-popular .record-control.loading,
body.font-popular .record-control.preparing {
  background: linear-gradient(135deg, #8fd3ff 0%, #1a73e8 52%, #174ea6 100%) !important;
  box-shadow: inset 0 -12px 22px rgba(24, 58, 184, 0.2), 0 12px 24px rgba(26, 115, 232, 0.32);
}

body.font-popular .record-control.examiner_playing,
body.font-popular .record-control.turn_saved {
  background: linear-gradient(135deg, #8b99a6 0%, #45535b 52%, #263238 100%) !important;
  box-shadow: inset 0 -12px 22px rgba(0, 0, 0, 0.16), 0 12px 24px rgba(38, 50, 56, 0.26);
}

body.font-popular .record-control.recording {
  background: linear-gradient(135deg, #ff9a8a 0%, #ea4335 52%, #b3261e 100%) !important;
  box-shadow: inset 0 -12px 22px rgba(154, 52, 18, 0.22), 0 12px 24px rgba(234, 67, 53, 0.34);
}

body.font-popular .record-control.processing,
body.font-popular .record-control.scoring {
  background: linear-gradient(135deg, #ffe082 0%, #f9ab00 52%, #d97706 100%) !important;
  box-shadow: inset 0 -12px 22px rgba(146, 64, 14, 0.2), 0 12px 24px rgba(217, 119, 6, 0.32);
}

@keyframes btnPulse {
  0%, 100% { box-shadow: 0 10px 30px rgba(217, 119, 6, 0.3); }
  50% { box-shadow: 0 10px 30px rgba(217, 119, 6, 0.6); }
}

#recordIcon {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.9;
}

.record-control strong {
  font-size: 32px;
  line-height: 1;
}

.record-control small {
  max-width: 180px;
  color: rgba(255,255,255,0.86);
  line-height: 1.35;
  font-size: 14px;
}

.analyzing-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 14px;
}

.analyzing-dots span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  animation: dotBounce 1.2s ease-in-out infinite;
}

.analyzing-dots span:nth-child(1) { animation-delay: 0s; }
.analyzing-dots span:nth-child(2) { animation-delay: 0.2s; }
.analyzing-dots span:nth-child(3) { animation-delay: 0.4s; }

@keyframes dotBounce {
  0%, 80%, 100% { transform: translateY(0); opacity: 0.5; }
  40% { transform: translateY(-10px); opacity: 1; }
}

.scoring-indicator {
  justify-self: center;
  margin-top: 16px;
  padding: 10px 14px;
  border: 1px solid #fed7aa;
  border-radius: 999px;
  background: #fff7ed;
  color: #9a3412;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  animation: scoringPulse 1s ease-in-out infinite;
}

.scoring-indicator span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #f97316;
  box-shadow: 0 0 0 0 rgba(249, 115, 22, 0.45);
  animation: scoringDot 1s ease-in-out infinite;
}

@keyframes scoringPulse {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-1px); }
}

@keyframes scoringDot {
  0%, 100% { box-shadow: 0 0 0 2px rgba(249, 115, 22, 0.16); }
  50% { box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.08); }
}

.record-status {
  text-align: center;
  color: var(--muted);
  min-height: 44px;
  line-height: 1.45;
  margin-top: 14px;
}

.dictation-status {
  justify-self: center;
  max-width: 520px;
  margin: 10px auto 0;
  padding: 8px 12px;
  border: 1px solid #c7d2fe;
  border-radius: 999px;
  background: #eef2ff;
  color: #3730a3;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.35;
  text-align: center;
}

.dictation-status.captured {
  border-color: #99f6e4;
  background: #ecfdf5;
  color: #0f766e;
}

.dictation-status.reconnecting,
.dictation-status.saving {
  border-color: #fed7aa;
  background: #fff7ed;
  color: #9a3412;
}

.dictation-status.unavailable {
  border-color: #fecaca;
  background: #fef2f2;
  color: #b91c1c;
}

.realtime-pcm-status {
  justify-self: center;
  max-width: 620px;
  margin: 8px auto 0;
  padding: 7px 11px;
  border: 1px solid #d1d5db;
  border-radius: 999px;
  background: #f8fafc;
  color: #475569;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
  text-align: center;
}

.realtime-pcm-status.live {
  border-color: #a7f3d0;
  background: #ecfdf5;
  color: #047857;
}

.realtime-pcm-status.fallback {
  border-color: #fed7aa;
  background: #fff7ed;
  color: #9a3412;
}

audio {
  width: 100%;
  margin-top: 12px;
}

.summary-panel {
  position: fixed;
  bottom: 0;
  left: var(--sidebar-width);
  right: 0;
  max-height: 70vh;
  overflow-y: auto;
  background: var(--panel);
  border-top: 1px solid var(--line);
  border-radius: 16px 16px 0 0;
  padding: 24px;
  box-shadow: 0 -8px 32px rgba(0, 0, 0, 0.12);
  z-index: 200;
  transform: translateY(100%);
  transition: transform 300ms ease-out;
}

.summary-panel.visible {
  transform: translateY(0);
}

.summary-panel-overlay {
  position: fixed;
  top: 0;
  left: var(--sidebar-width);
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.3);
  z-index: 199;
  opacity: 0;
  pointer-events: none;
  transition: opacity 200ms ease;
}

.summary-panel-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.summary-panel.summary-highlight {
  animation: summaryPulse 1.45s ease-out;
}

@keyframes summaryPulse {
  0% { background: #fff7ed; box-shadow: 0 0 0 0 rgba(249, 115, 22, 0.18); }
  100% { background: transparent; box-shadow: 0 0 0 6px rgba(249, 115, 22, 0); }
}

.score-row {
  display: grid;
  grid-template-columns: repeat(5, minmax(92px, 1fr));
  gap: 12px;
}

.score-row.compact {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0;
}

.score-row.compact.writing-criteria-score-row {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.score-row.mini {
  grid-template-columns: repeat(4, minmax(58px, 1fr));
  gap: 8px;
}

.score-cell {
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 10px;
  background: #fbfcfd;
}

.score-cell span {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.score-cell strong {
  display: block;
  margin-top: 2px;
  font-size: 20px;
}

.score-row.mini .score-cell {
  padding: 6px;
}

.score-row.mini .score-cell strong {
  font-size: 15px;
}

.feedback {
  margin-top: 12px;
  line-height: 1.5;
  font-size: 13px;
}

.summary-actions {
  margin-top: 16px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

button {
  min-height: 42px;
  border: 0;
  border-radius: 8px;
  padding: 0 16px;
  background: var(--accent);
  color: white;
}

button.secondary { background: var(--blue); }
button.ghost {
  background: #e8edf0;
  color: var(--ink);
}

.history-rail-shell {
  position: fixed;
  top: calc(8px + var(--safe-top));
  left: calc(176px + 14px);
  right: 64px;
  z-index: 90;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 8px 10px 8px 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-xl);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 252, 0.9));
  box-shadow: var(--shadow-sm);
  backdrop-filter: blur(10px);
}

.history-rail-head {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto auto;
  align-items: center;
  gap: 7px;
  min-width: 0;
  width: 68px;
  max-width: 68px;
  justify-self: center;
}

.history-rail-head > div:first-child {
  width: 68px;
  justify-self: center;
  text-align: center;
}

.history-rail-head strong {
  display: block;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.1;
}

.history-rail-head span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
  white-space: nowrap;
}

.history-rail-actions {
  width: 68px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 4px;
  border: 1px solid color-mix(in srgb, var(--border-soft) 82%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, #ffffff 66%, transparent);
  box-shadow: none;
}

.report-filter {
  position: relative;
  width: 100%;
}

.report-filter-compact {
  width: 68px;
  max-width: 68px;
  justify-self: center;
}

.report-filter-button {
  width: 100%;
  box-sizing: border-box;
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 7px;
  border: 1px solid color-mix(in srgb, var(--border-soft) 82%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, #ffffff 66%, transparent);
  color: var(--ink);
  font-size: 12px;
  font-weight: 820;
  cursor: pointer;
}

.report-filter-button svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.report-filter-menu {
  position: absolute;
  left: 0;
  top: calc(100% + 6px);
  z-index: 20;
  min-width: 96px;
  padding: 5px;
  border: 1px solid color-mix(in srgb, var(--border-soft) 86%, transparent);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.14);
}

.report-filter-menu button {
  width: 100%;
  min-height: 30px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ink);
  font-size: 12px;
  font-weight: 760;
  text-align: left;
  padding: 0 9px;
  cursor: pointer;
}

.report-filter-menu button:hover,
.report-filter-menu button.active {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent-dark);
}

.history-rail-nav {
  width: 28px;
  height: 24px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: color-mix(in srgb, var(--ink) 76%, var(--muted));
  display: grid;
  place-items: center;
  line-height: 1;
  cursor: pointer;
  box-shadow: none;
  padding: 0;
}

.history-rail-nav svg {
  margin: auto;
}

.history-rail-nav:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent-dark);
  box-shadow: none;
  transform: none;
}

.history-rail-nav svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  display: block;
}

.history-rail-nav:disabled {
  opacity: 0.34;
  cursor: default;
  box-shadow: none;
}

.history-rail-window {
  position: relative;
  min-width: 0;
  overflow: hidden;
}

.history-rail-window::before,
.history-rail-window::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  width: 34px;
  pointer-events: none;
  opacity: 1;
  transition: opacity 160ms ease;
}

.history-rail-window::before {
  left: 0;
  background: linear-gradient(90deg, rgba(250, 252, 252, 0.98), rgba(250, 252, 252, 0));
}

.history-rail-window::after {
  right: 0;
  background: linear-gradient(270deg, rgba(250, 252, 252, 0.98), rgba(250, 252, 252, 0));
}

.history-rail-shell.at-start .history-rail-window::before,
.history-rail-shell.at-end .history-rail-window::after {
  opacity: 0;
}

.history-list {
  display: flex;
  flex-direction: row;
  gap: 8px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 2px 4px;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
  flex-shrink: 0;
  min-height: 122px;
  max-height: 122px;
