  border: 0;
  border-radius: 0;
}

.history-list::-webkit-scrollbar {
  display: none;
}

.history-empty-state {
  min-width: 220px;
  height: 116px;
  border: 1px dashed rgba(15, 23, 42, 0.14);
  border-radius: var(--radius-xl);
  display: grid;
  place-items: center;
  color: var(--muted);
  font-size: 13px;
  font-weight: 760;
  background: rgba(255, 255, 255, 0.54);
}

.report-empty-rail-card {
  min-width: 250px;
  max-width: 250px;
  padding: 16px 18px;
  display: grid;
  place-items: start;
  align-content: center;
  gap: 7px;
  border-style: solid;
  border-color: color-mix(in srgb, var(--accent) 18%, var(--border-soft));
  background:
    radial-gradient(circle at 88% 18%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 30%),
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 92%, #ffffff), color-mix(in srgb, var(--panel) 82%, #f8fafc));
