  background:
    radial-gradient(circle at 50% 22%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 34%),
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 94%, #ffffff), color-mix(in srgb, var(--panel) 86%, #f8fafc));
