}

.report-empty-secondary {
  color: var(--ink);
  background: color-mix(in srgb, #ffffff 72%, transparent);
  border-color: color-mix(in srgb, var(--border-soft) 86%, transparent);
}

body.theme-dark .report-empty-rail-card,
body.theme-dark.font-academic .report-empty-rail-card,
body.theme-dark.font-popular .report-empty-rail-card {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--dark-border));
  background:
