  background: color-mix(in srgb, var(--accent) 18%, transparent);
}

body.theme-dark .report-empty-detail-card,
body.theme-dark.font-academic .report-empty-detail-card,
body.theme-dark.font-popular .report-empty-detail-card {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--dark-border));
  background:
    radial-gradient(circle at 50% 22%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 34%),
    linear-gradient(180deg, color-mix(in srgb, var(--dark-surface) 86%, transparent), color-mix(in srgb, var(--dark-panel) 92%, transparent));
}

body.theme-dark .report-empty-orbit,
body.theme-dark.font-academic .report-empty-orbit,
body.theme-dark.font-popular .report-empty-orbit {
  color: color-mix(in srgb, var(--accent) 82%, #ffffff);
