}

.history-loading-state {
  min-width: 142px;
  height: 40px;
  align-self: center;
  border-color: rgba(15, 23, 42, 0.1);
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  box-shadow: none;
}

@keyframes recordPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(16, 163, 127, 0.45), 0 10px 22px rgba(15, 23, 42, 0.2);
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 0 14px rgba(16, 163, 127, 0), 0 16px 30px rgba(15, 23, 42, 0.28);
    transform: scale(1.03);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(16, 163, 127, 0), 0 10px 22px rgba(15, 23, 42, 0.2);
    transform: scale(1);
  }
}

@keyframes geminiSphereShift {
  0% {
    background-position:
      0% 0%,
      24% 18%,
      16% 54%,
      34% 82%,
      72% 72%,
      82% 42%,
      62% 14%,
      50% 50%;
  }
  50% {
    background-position:
      0% 0%,
      30% 24%,
      20% 58%,
      40% 78%,
      68% 76%,
      78% 46%,
      58% 18%,
      50% 50%;
  }
  100% {
    background-position:
      0% 0%,
      24% 18%,
      16% 54%,
      34% 82%,
      72% 72%,
      82% 42%,
      62% 14%,
      50% 50%;
  }
}

.record-control {
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.record-control:hover {
  transform: translateY(-1px) scale(1.01);
}

.record-control.recording {
  animation: recordPulse 1.8s ease-in-out infinite;
}

body.font-popular .record-control.recording {
