.history-item-wrap {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
}

.report-band-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  min-width: 0;
}

.report-export-btn {
  min-height: 34px;
  height: 34px;
  width: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 9%, var(--panel));
  color: color-mix(in srgb, var(--accent) 78%, var(--ink));
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
  box-sizing: border-box;
  cursor: pointer;
}

.report-export-btn svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.1;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.report-export-btn:hover {
  background: color-mix(in srgb, var(--accent) 15%, var(--panel));
}

.history-item-wrap .history-item {
  position: relative;
}

.history-item-menu-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 22px;
  height: 22px;
  min-width: 22px;
  max-width: 22px;
  min-height: 22px;
  max-height: 22px;
  flex: 0 0 22px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #7b8494;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  box-shadow: none;
  padding: 0;
  overflow: hidden;
  z-index: 6;
  transition: background 160ms ease, color 160ms ease;
}

.history-item-wrap .history-item-top {
  padding-right: 18px;
}

.history-item-wrap .history-item-title,
.history-item-wrap .history-item-time {
  padding-right: 2px;
}

.history-item-menu-btn span {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: -5px 0 0 currentColor, 5px 0 0 currentColor;
  flex-shrink: 0;
}

.history-item-menu-btn:hover {
  background: rgba(16, 163, 127, 0.08);
  color: var(--ink);
}

/* Per-card three-dot menu MUST be a floating overlay pinned to each card's OWN
   top-right corner: anchored to the (relative) wrap, lifted out of flow so it never
   squeezes the title, and never collapsing onto the whole rail's corner. Hardened
   with !important + child specificity so no stray rule can knock it back into flow. */
.history-item-wrap,
.writing-report-item-wrap {
  position: relative !important;
}

.history-item-wrap > .history-item-menu-btn,
.writing-report-item-wrap > .history-item-menu-btn {
  position: absolute !important;
  top: 4px !important;
  right: 4px !important;
  left: auto !important;
  bottom: auto !important;
  z-index: 8 !important;
  margin: 0 !important;
  flex: 0 0 auto !important;
  /* A faint floating chip so the dots read as hovering above the card, always
     visible (not only on hover). */
  background: color-mix(in srgb, var(--panel) 72%, transparent) !important;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.14) !important;
  backdrop-filter: blur(2px);
}

.history-item-wrap > .history-item-menu-btn:hover,
.writing-report-item-wrap > .history-item-menu-btn:hover {
  background: color-mix(in srgb, var(--accent) 16%, var(--panel)) !important;
  color: var(--ink) !important;
}

/* The band/title rows only need to clear the floating chip — no extra reserved
   gutter that would push the title left and leave dead space on the right. */
.history-item-wrap .history-item-top {
  padding-right: 26px !important;
}

.history-item-wrap .history-item-title,
.history-item-wrap .history-item-time {
  padding-right: 0 !important;
}

.history-item-menu {
  position: absolute;
  top: 32px;
  right: 4px;
  z-index: 100;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  padding: 4px;
  min-width: 80px;
}

.history-menu-delete {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--danger);
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
}

.history-menu-action {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--ink);
  font-size: 13px;
  font-weight: 650;
  text-align: left;
  cursor: pointer;
}

.history-menu-action:hover {
  background: rgba(16, 163, 127, 0.08);
}

.history-menu-delete:hover {
  background: rgba(239, 68, 68, 0.08);
}

.confirm-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
}

.confirm-dialog {
  background: var(--panel);
  border-radius: 12px;
  padding: 24px;
  max-width: 320px;
  width: 90%;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.2);
}

.confirm-dialog p {
  margin: 0 0 20px;
  font-size: 15px;
  color: var(--ink);
}

.confirm-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.confirm-cancel {
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink);
  font-size: 14px;
  cursor: pointer;
}

.confirm-cancel:hover {
  background: var(--bg);
}

.confirm-delete {
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  background: var(--danger);
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}

.confirm-delete:hover {
  background: #dc2626;
}

.confirm-delete.p3-cycle-start {
  background: var(--accent);
  color: #fff;
}

.confirm-delete.p3-cycle-start:hover {
  background: color-mix(in srgb, var(--accent) 84%, #000);
}

/* Guest "not signed in" prompt — reuses the confirm overlay, but reads as an
   invitation (title + three actions) rather than a destructive confirm. */
.guest-login-dialog {
  max-width: 360px;
}
.guest-login-title {
  margin: 0 0 8px;
  font-size: 17px;
  font-weight: 800;
  color: var(--ink);
}
.guest-login-actions {
  flex-wrap: wrap;
}
.guest-login-register {
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink);
  font-size: 14px;
  cursor: pointer;
}
.guest-login-register:hover {
  background: var(--bg);
}
.guest-login-go {
  padding: 8px 16px;
  border: none;
