/* 编辑语料库 button: an icon + label pill so it reads by SHAPE, not just colour.
   One coherent accent-tinted treatment across P1/P2/P3 (the old per-context
   solid green/blue is gone) with a real dark-mode surface. */
.corpus-edit-button,
button.ghost.corpus-edit-button,
.p2-report-actions button.ghost.corpus-edit-button {
  --corpus-accent: var(--accent, #2563eb);
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  border: 1px solid color-mix(in srgb, var(--corpus-accent) 38%, transparent);
  border-radius: 999px;
  padding: 6px 14px 6px 11px;
  color: var(--corpus-accent) !important;
  background: color-mix(in srgb, var(--corpus-accent) 9%, var(--panel)) !important;
  font-weight: 720;
  white-space: nowrap;
  box-shadow: none;
  text-shadow: none;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.corpus-edit-button .corpus-edit-icon {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.corpus-edit-button .corpus-edit-icon path:last-child { fill: color-mix(in srgb, currentColor 18%, transparent); }

.corpus-edit-button:hover,
button.ghost.corpus-edit-button:hover,
.p2-report-actions button.ghost.corpus-edit-button:hover {
  background: color-mix(in srgb, var(--corpus-accent) 16%, var(--panel)) !important;
  border-color: color-mix(in srgb, var(--corpus-accent) 55%, transparent) !important;
}
.corpus-edit-button:active { transform: translateY(1px); }

body.theme-dark .corpus-edit-button,
body.theme-dark button.ghost.corpus-edit-button,
body.theme-dark .p2-report-actions button.ghost.corpus-edit-button {
  --corpus-accent: #7aa2ff;
  color: #cdddff !important;
  background: color-mix(in srgb, #7aa2ff 16%, var(--panel)) !important;
  border-color: color-mix(in srgb, #7aa2ff 38%, transparent) !important;
}
body.theme-dark .corpus-edit-button:hover,
body.theme-dark button.ghost.corpus-edit-button:hover,
body.theme-dark .p2-report-actions button.ghost.corpus-edit-button:hover {
  background: color-mix(in srgb, #7aa2ff 26%, var(--panel)) !important;
  border-color: color-mix(in srgb, #7aa2ff 60%, transparent) !important;
}

/* Saved state: a filled green pill with a check, so 已保存 reads at a glance and
   isn't confused with the (outline) 待补充 state. */
.corpus-edit-button.is-corpus-saved,
button.ghost.corpus-edit-button.is-corpus-saved,
.p2-report-actions button.ghost.corpus-edit-button.is-corpus-saved {
  color: #fff !important;
  background: linear-gradient(180deg, #22a565, #15834e) !important;
  border-color: #15803d !important;
}
.corpus-edit-button.is-corpus-saved:hover,
button.ghost.corpus-edit-button.is-corpus-saved:hover,
.p2-report-actions button.ghost.corpus-edit-button.is-corpus-saved:hover {
  background: linear-gradient(180deg, #1f9a5e, #136e42) !important;
  border-color: #166534 !important;
}
.corpus-edit-button.is-corpus-saved .corpus-edit-icon path:last-child { fill: none; }
body.theme-dark .corpus-edit-button.is-corpus-saved,
body.theme-dark button.ghost.corpus-edit-button.is-corpus-saved,
body.theme-dark .p2-report-actions button.ghost.corpus-edit-button.is-corpus-saved {
  color: #eafff3 !important;
  background: linear-gradient(180deg, #1f8f57, #115e38) !important;
  border-color: #1b7a49 !important;
}

