  font-size: 13px;
  font-weight: 700;
  line-height: 1.45;
}

.missing-transcript-notice {
  display: grid;
  gap: 8px;
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid #f59e0b;
  border-radius: 10px;
  background: #fff7ed;
  color: #92400e;
  line-height: 1.45;
}

.missing-transcript-notice strong {
  color: #78350f;
}

.missing-transcript-notice span {
  font-size: 13px;
}

.regenerate-transcript-button {
  justify-self: start;
  min-height: 34px;
  padding: 7px 12px;
  border-color: #f59e0b;
  color: #92400e;
}

.regenerate-transcript-button:hover {
  border-color: #d97706;
  background: #fffbeb;
}

.settings-name-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(150px, 1fr));
