  min-width: min(420px, 46vw);
}

.account-name-fields {
  min-width: 0;
  margin-bottom: 12px;
}

.settings-page-head {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  margin-bottom: 14px;
  min-height: 40px;
}

.settings-page-head:has(.settings-back-button.hidden) {
  display: none;
}

.settings-back-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 4px 12px rgba(15, 32, 38, 0.06);
}

.settings-back-button span {
  font-size: 18px;
  line-height: 1;
}

.settings-back-button:hover {
  border-color: var(--accent);
  color: var(--accent-dark);
}

.topbar-name-fields {
  grid-column: 2 / 4;
  justify-self: end;
  align-self: end;
}

.settings-name-fields label {
  display: grid;
  gap: 5px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.settings-name-fields input {
  min-height: 38px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  padding: 0 11px;
  font-size: 15px;
  font-weight: 700;
}

.settings-status-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(240px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
  height: calc(100vh - 250px);
}

.account-page-layout {
  display: grid;
  grid-template-columns: minmax(320px, 560px);
  align-items: start;
}

.account-dashboard {
  width: 100%;
  margin: 0;
  padding-top: calc(8px + var(--safe-top));
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
  align-items: start;
}

.shell.account-shell .workspace {
  overflow-y: auto;
}

.shell.account-shell .topbar {
  display: none;
}

.account-page-header {
  width: min(1160px, 100%);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 2px 2px 0;
}

.account-page-copy {
  display: grid;
  gap: 8px;
}

.account-page-kicker {
  margin: 0;
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.account-page-copy h1 {
  margin: 0;
  font-size: clamp(28px, 3vw, 38px);
  line-height: 1.05;
}

.account-page-copy .muted {
  max-width: 56ch;
  margin: 0;
  color: #5f6f79;
  line-height: 1.45;
}

.account-page-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.account-action-button {
  min-height: 42px;
  padding: 0 18px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background 160ms ease;
}

.account-action-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 28px rgba(15, 23, 42, 0.11);
}

.account-action-button-primary {
  background: linear-gradient(180deg, #1f8a6f 0%, #176a57 100%);
  color: #fff;
  border-color: rgba(23, 106, 87, 0.36);
}

.account-action-button-primary:hover {
  background: linear-gradient(180deg, #229679 0%, #176a57 100%);
}

.account-action-button-secondary {
  background: linear-gradient(180deg, #ffffff 0%, #edf3f7 100%);
  color: #1f2937;
  border-color: rgba(15, 23, 42, 0.12);
}

.account-action-button-secondary:hover {
  background: linear-gradient(180deg, #ffffff 0%, #e6edf3 100%);
}

.account-action-button-ghost {
  background: #f3f6f8;
  color: #334155;
  border-color: rgba(15, 23, 42, 0.08);
}

.account-action-button-accent {
  background: linear-gradient(180deg, #176b8a 0%, #14556d 100%);
  color: #fff;
  border-color: rgba(20, 85, 109, 0.28);
}

.account-dashboard-grid {
  width: min(1160px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  align-items: start;
}

.account-profile-card,
.account-wallet-card {
  min-height: 100%;
}

.account-profile-card {
  width: 100%;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.98), rgba(252, 253, 254, 0.98));
  padding: 22px;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.07);
  border-color: rgba(15, 23, 42, 0.07);
  position: relative;
  overflow: hidden;
}

.account-profile-card::before,
.account-wallet-card::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, rgba(16, 163, 127, 0.85), rgba(37, 99, 235, 0.62));
  opacity: 0.55;
  pointer-events: none;
}

.account-profile-card .settings-metric {
  margin-bottom: 10px;
}

.account-wallet-card {
  min-height: 100%;
  border-color: rgba(37, 99, 235, 0.10);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.97), rgba(250,252,255,0.98));
  box-shadow: 0 16px 40px rgba(37, 99, 235, 0.05);
  position: relative;
  overflow: hidden;
}

body.theme-dark .account-profile-card,
body.theme-dark .account-wallet-card {
  background: linear-gradient(180deg, rgba(19, 26, 34, 0.98), rgba(13, 19, 27, 0.98));
  border-color: rgba(148, 163, 184, 0.18);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.26);
}

body.theme-dark .account-page-copy .muted,
body.theme-dark .account-wallet-head .muted,
body.theme-dark .account-wallet-card .settings-list-row span,
body.theme-dark .account-wallet-card .settings-list-row small {
  color: var(--muted);
}

body.theme-dark .settings-name-fields input,
body.theme-dark .account-action-button-secondary,
body.theme-dark .account-action-button-ghost {
  background: #0f1720;
  color: var(--ink);
  border-color: rgba(148, 163, 184, 0.22);
}

body.theme-dark .account-bank-selector {
  border-color: var(--dark-border);
  background: rgba(15, 23, 32, 0.50);
}

body.theme-dark .account-bank-season,
body.theme-dark .account-bank-options button {
  background: rgba(15, 23, 32, 0.72);
  border-color: rgba(148, 163, 184, 0.20);
  color: var(--ink);
}

body.theme-dark .account-bank-options button small {
  color: var(--muted);
}

body.theme-dark .account-bank-options button.is-active {
  background: var(--dark-primary);
  border-color: var(--dark-primary-border);
  color: #ecfdf5;
}

.account-wallet-card .settings-list {
  max-height: 250px;
}

.account-wallet-head {
  margin-bottom: 12px;
}

.account-wallet-head .muted {
  margin: 4px 0 0;
  color: #64748b;
}

.account-wallet-card .wallet-header {
  margin-bottom: 10px;
}

.account-profile-card .settings-name-fields {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
  align-items: end;
  min-width: 0;
  gap: 12px;
}

.account-profile-card .settings-name-fields .account-action-button {
  min-width: 118px;
  min-height: 58px;
  border-radius: 16px;
}

.account-bank-selector {
  margin-top: 16px;
  padding: 13px;
  border: 1px solid rgba(126, 139, 153, 0.18);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(248, 251, 250, 0.92), rgba(255, 255, 255, 0.78));
}

.account-bank-selector-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.account-bank-selector h3 {
  margin: 4px 0 0;
  font-size: 17px;
  line-height: 1.15;
}

.account-bank-season {
  flex: 0 0 auto;
  border-radius: 999px;
  background: #fff;
  border: 1px solid rgba(13, 138, 106, 0.14);
  color: #0f766e;
  padding: 6px 10px;
  font-size: 12px;
  font-weight: 850;
}

.account-bank-selector .account-card-subtitle {
  margin-top: 8px;
  font-size: 13px;
  line-height: 1.35;
}

.account-bank-options {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin-top: 11px;
}

.account-bank-options button {
  min-height: 44px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.86);
  color: var(--ink);
  padding: 8px 9px;
  text-align: left;
  font-size: 13px;
  font-weight: 850;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.account-bank-options button:hover {
  border-color: rgba(13, 138, 106, 0.26);
  background: #fff;
  transform: translateY(-1px);
}

.account-bank-options button:focus-visible {
  outline: 3px solid rgba(13, 138, 106, 0.22);
  outline-offset: 2px;
}

.account-bank-option-label {
  display: block;
  overflow: hidden;
  width: 100%;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-bank-options button small {
  color: #64748b;
  font-size: 9.5px;
  font-weight: 750;
  line-height: 1.15;
  white-space: nowrap;
}

.account-bank-options button.is-active {
  border-color: rgba(13, 138, 106, 0.42);
  background: #0f8f72;
  color: #fff;
  box-shadow: 0 10px 22px rgba(13, 138, 106, 0.14);
}

.account-bank-options button.is-active small {
  color: rgba(255, 255, 255, 0.78);
}

body.theme-dark .account-bank-options button:hover {
  background: rgba(22, 34, 44, 0.92);
  border-color: rgba(52, 211, 153, 0.28);
}

body.theme-dark .account-bank-options button.is-active:hover {
  background: var(--dark-primary);
}

body.theme-dark .account-bank-selector .account-card-subtitle {
  color: #9fb1bf;
}

body.theme-dark .account-profile-card .settings-name-fields input {
  background: rgba(15, 23, 32, 0.86);
  color: var(--ink);
  border-color: rgba(148, 163, 184, 0.24);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

@media (max-width: 1120px) {
  .account-bank-options {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.account-theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  margin-top: 16px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  user-select: none;
}

.account-theme-toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.account-theme-toggle i {
  position: relative;
  width: 48px;
  height: 28px;
  border-radius: 999px;
  background: #dbe4ea;
  border: 1px solid rgba(15, 23, 42, 0.10);
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.10);
  transition: background 160ms ease, border-color 160ms ease;
}

.account-theme-toggle i::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.20);
  transition: transform 160ms ease, background 160ms ease;
}

.account-theme-toggle input:checked + i {
  background: #172033;
  border-color: rgba(148, 163, 184, 0.28);
}

.account-theme-toggle input:checked + i::after {
  transform: translateX(20px);
  background: #34d399;
}

.account-profile-card .settings-card-head {
  display: none;
}

.account-security-card {
  width: min(760px, 100%);
  margin: 0 auto;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.08);
}

.account-security-card-head {
  align-items: center;
}

.account-security-card-head .icon-button {
  width: 42px;
  height: 42px;
}

.auth-panel {
  position: relative;
  min-height: 100vh;
  min-height: 100dvh;
  padding: clamp(18px, 3vw, 36px);
  border: 0;
  border-radius: 0;
  background: transparent;
}

.auth-panel:not(.hidden) {
  display: block;
}

#loginPanel {
  position: relative;
}

#loginPanel.is-loading .auth-stage {
  filter: blur(1px);
  opacity: 0.35;
  pointer-events: none;
  user-select: none;
}

#loginPanel .page-center-loading {
  position: absolute;
  inset: 0;
  z-index: 3;
  min-height: 0;
  background: rgba(247, 247, 248, 0.5);
  backdrop-filter: blur(3px);
}

#accountSecurityPanel.auth-panel {
  position: fixed;
  inset: 0;
  z-index: 220;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.38);
  backdrop-filter: blur(4px);
}

#accountSecurityPanel.auth-panel.hidden {
  display: none;
}

#accountSecurityPanel.auth-panel > .account-security-card {
  max-height: min(86vh, 820px);
  overflow: auto;
}

.auth-back-button {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: 18px;
  z-index: 2;
  min-height: 36px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.86);
  color: #334155;
  padding: 0 14px;
  font-size: 14px;
  font-weight: 800;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

.auth-back-button:hover {
  border-color: rgba(15, 23, 42, 0.18);
  background: #fff;
}

.auth-stage {
  width: min(1040px, 100%);
  min-height: calc(100vh - 96px);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(280px, 0.9fr) minmax(340px, 460px);
  gap: clamp(24px, 5vw, 72px);
  align-items: center;
}

.auth-copy {
  display: grid;
  gap: 18px;
  color: var(--ink);
}

.auth-kicker {
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.auth-copy h1 {
  max-width: 10ch;
  font-size: clamp(38px, 6vw, 68px);
  line-height: 0.98;
}

.auth-copy p {
  max-width: 48ch;
  color: #475569;
  font-size: 17px;
  line-height: 1.6;
}

.auth-benefits {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.auth-benefits span {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(13, 138, 106, 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  color: #1f3d35;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 800;
}

.auth-card {
  width: 100%;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.94);
  padding: clamp(22px, 4vw, 34px);
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
}

.auth-card-head {
  margin-bottom: 22px;
}

.auth-card-head h2 {
  margin: 0;
  font-size: 26px;
}

.auth-card-head p,
.auth-card > p.muted {
  margin-top: 8px;
  color: #5f6f79;
  line-height: 1.45;
}

.auth-card label {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 14px;
}

.auth-card input {
  width: 100%;
  box-sizing: border-box;
  min-height: 46px;
  border: 1px solid #dbe3e8;
  border-radius: 9px;
  background: #fff;
  padding: 0 13px;
  color: var(--ink);
  font-size: 15px;
}

.auth-card input:focus {
  outline: 2px solid rgba(16, 163, 127, 0.18);
  border-color: var(--accent);
}

.auth-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.auth-row-between {
  justify-content: flex-end;
}

.auth-two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.text-link {
  min-height: 30px;
  border: 0;
  background: transparent;
  color: var(--accent-dark);
  padding: 0;
  font-weight: 800;
}

.auth-action-stack {
  display: grid;
  gap: 10px;
}

.auth-action-stack button {
  min-height: 44px;
}

.auth-card .settings-metric {
  margin: 10px 0;
  min-height: 20px;
}

.auth-card .settings-metric.error {
  color: #ef4444;
}

.auth-notice-emphasis {
  border: 1px solid rgba(245, 158, 11, 0.28);
  border-radius: 9px;
  background: #fffbeb;
  color: #92400e !important;
  padding: 10px 12px;
}

@media (max-width: 820px) {
  .account-profile-body .account-action-button {
    width: 100%;
    min-width: 0;
  }
  .auth-copy h1 {
    max-width: none;
