.settings-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fbfcfd;
  padding: 18px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.settings-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.settings-card h2 {
  margin-bottom: 10px;
  font-size: 18px;
}

.settings-card .settings-card-head h2 {
  margin-bottom: 4px;
}

.account-settings-card {
  gap: 12px;
}

.account-login-form {
  display: grid;
  gap: 10px;
}

.account-login-form label {
  display: grid;
  gap: 5px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.account-login-form input {
  width: 100%;
  box-sizing: border-box;
}

.account-action-row,
.account-profile-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.account-action-row button,
.account-profile-actions button,
.settings-card-head button {
  min-height: 38px;
}

.account-security-card .account-action-row {
  justify-content: flex-end;
  margin-top: 6px;
}

.account-security-card .account-action-button {
  min-width: 132px;
}

.account-lower-grid .settings-card h2 {
  color: #111827;
  font-size: 18px;
}

/* ── AI quota exhausted dialog ─────────────────────────────── */
@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.ai-quota-dialog-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(4px);
