}

/* Recharge Dialog */
.recharge-dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.38);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 300;
  padding: 20px;
  backdrop-filter: blur(4px);
}

.recharge-dialog-overlay.hidden {
  display: none;
}

.insufficient-balance-dialog-overlay {
  position: fixed;
  inset: 0;
  z-index: 320;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(5px);
}

.insufficient-balance-dialog {
  width: min(460px, 100%);
  padding: 26px;
  border: 1px solid rgba(190, 91, 65, 0.18);
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(255, 250, 247, 0.99));
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.24);
  text-align: center;
}

.insufficient-balance-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 14px;
  border-radius: 18px;
  background: rgba(190, 91, 65, 0.12);
  color: #be5b41;
  font-size: 28px;
  font-weight: 900;
}

.insufficient-balance-copy span {
  display: inline-flex;
  min-height: 22px;
  align-items: center;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(190, 91, 65, 0.10);
  color: #9a4b32;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.insufficient-balance-copy h3 {
  margin: 9px 0 8px;
  color: #1f2933;
  font-size: 28px;
  line-height: 1.1;
}

.insufficient-balance-copy p {
  margin: 0;
  color: #667784;
  font-size: 15px;
  line-height: 1.55;
}

.insufficient-balance-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 22px;
}

.insufficient-balance-actions button {
  min-height: 50px;
  border-radius: 14px;
  font-size: 16px;
  font-weight: 850;
  cursor: pointer;
}

.recharge-dialog {
  width: min(560px, 100%);
  border: 1px solid rgba(126, 139, 153, 0.20);
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(249, 251, 252, 0.98));
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.24);
  padding: 28px;
}

.recharge-dialog-head {
  text-align: center;
  margin-bottom: 20px;
}

.recharge-dialog-head span {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(47, 125, 104, 0.10);
  color: #2f7d68;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.recharge-dialog h3 {
  margin: 8px 0 6px;
  color: #1f2933;
  font-size: 28px;
  line-height: 1.1;
}

.recharge-dialog-head p {
  margin: 0;
  color: #667784;
  font-size: 14px;
}

.recharge-dialog .recharge-buttons {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.recharge-dialog .recharge-btn {
  min-height: 56px;
  padding: 0 10px;
  border: 1px solid rgba(126, 139, 153, 0.22);
  border-radius: 14px;
  background: #fff;
  color: #1f2933;
  font-size: 20px;
  font-weight: 850;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease;
}

.recharge-dialog .recharge-btn:hover,
.recharge-dialog .recharge-btn.selected {
  background: #2f7d68;
  border-color: #2f7d68;
  color: #fff;
  box-shadow: 0 12px 24px rgba(47, 125, 104, 0.20);
}

.recharge-dialog .recharge-custom {
  margin-bottom: 14px;
}

.recharge-dialog .recharge-custom input {
  width: 100%;
  min-height: 52px;
  padding: 0 16px;
  border: 1px solid rgba(126, 139, 153, 0.22);
  border-radius: 14px;
  font-size: 18px;
  font-weight: 750;
  background: #fff;
  color: #1f2933;
  box-sizing: border-box;
}

.recharge-dialog .recharge-custom input:focus {
  outline: none;
  border-color: #2f7d68;
  box-shadow: 0 0 0 3px rgba(47, 125, 104, 0.13);
}

.recharge-dialog .recharge-preview {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 64px;
  padding: 0 16px;
  margin-bottom: 18px;
  border: 1px solid rgba(126, 139, 153, 0.16);
  border-radius: 16px;
  background: #f8fbfa;
  font-size: 15px;
  font-weight: 850;
  color: #465667;
}

.recharge-dialog .recharge-preview strong {
  font-size: 30px;
  color: #1f2933;
  line-height: 1;
}

body.theme-dark .recharge-dialog .recharge-preview strong {
  color: #ffffff;
}

.recharge-dialog-buttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.recharge-dialog-buttons button {
  min-height: 52px;
  padding: 0 14px;
  border-radius: 14px;
  font-size: 16px;
  font-weight: 850;
  cursor: pointer;
}

.recharge-dialog-cancel {
  border: 1px solid rgba(126, 139, 153, 0.22);
  background: #fff;
  color: #1f2933;
}

.recharge-dialog-confirm {
  border: none;
  background: #2f7d68;
  color: #fff;
  box-shadow: 0 14px 30px rgba(47, 125, 104, 0.20);
}

.recharge-dialog-confirm:disabled {
  background: #b8bec4;
  opacity: 1;
  box-shadow: none;
  cursor: not-allowed;
}

.transcript-status {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(220px, 1fr));
  gap: 16px;
}

.settings-grid label {
  display: grid;
  gap: 7px;
  color: var(--muted);
}

.settings-font-options {
  display: flex;
  gap: 8px;
}

