}

.settings-font-options .font-option:hover,
.settings-font-options .font-option.active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

input, select {
  min-height: 40px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 10px;
  background: white;
}

