.speaking-report-rail-shell,
.writing-report-rail-shell {
  grid-template-columns: 68px minmax(0, 1fr);
  gap: 8px;
  padding: 8px 10px 8px 12px;
}

.speaking-report-rail-shell .history-rail-head,
.writing-report-rail-shell .history-rail-head {
  width: 68px;
  max-width: 68px;
  padding: 4px 0 4px 0;
  border-right: 0;
}

.speaking-report-rail-shell .history-rail-head strong,
.writing-report-rail-shell .history-rail-head strong {
  font-size: 13px;
  letter-spacing: 0;
}

.speaking-report-rail-shell .history-rail-head span,
.writing-report-rail-shell .history-rail-head span {
  font-size: 10px;
  color: color-mix(in srgb, var(--muted) 88%, var(--ink));
}

.speaking-report-rail-shell .history-rail-actions,
.writing-report-rail-shell .history-rail-actions {
  width: 68px;
  height: 38px;
  padding: 4px;
  border-radius: 13px;
  background: color-mix(in srgb, #ffffff 62%, transparent);
}

.speaking-report-rail-shell .history-rail-nav,
.writing-report-rail-shell .history-rail-nav {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  flex: 0 0 28px;
  display: grid;
  place-items: center;
}

/* Speaking report rail intentionally inherits the base .history-list/.history-item
   styles so its cards match the writing report rail exactly (writing is the
   reference). No size/gap overrides here. */

