/* Ultra-narrow portrait mode (< 380px) */
@media (max-width: 380px) {
  .nav {
    padding: 5px;
    gap: 0;
  }
  .nav-button {
    min-height: 28px;
    font-size: 10px;
    padding: 0 5px;
    border-radius: 6px;
  }
  .user-avatar {
    width: 28px;
    height: 28px;
    font-size: 11px;
  }
  .workspace {
    padding: 10px;
    gap: 10px;
  }
  h1 {
    font-size: 22px;
  }
  .topbar p {
    font-size: 13px;
  }
  .panel {
    padding: 12px;
    border-radius: 8px;
  }
  .writing-panel {
    padding: 0;
  }
  .writing-task-switch {
    grid-template-columns: 1fr 1fr;
  }
  .writing-day {
    font-size: 10px;
    border-radius: 5px;
  }
  .prompt-pane,
  .recorder-pane {
    min-height: 240px;
    padding: 12px;
  }
  .record-control {
    width: min(170px, 52vw);
    padding: 16px;
  }
  .record-control strong {
    font-size: 22px;
  }
  #recordIcon {
    width: 28px;
    height: 28px;
  }
  .icon-exit-button {
    width: 42px;
    height: 42px;
    min-width: 42px;
  }
  .history-item {
    width: 190px;
    min-width: 190px;
    height: 112px;
    padding: 10px 30px 10px 12px;
  }
  .history-item-tag {
    font-size: 10px;
    min-width: 0;
    min-height: 0;
    padding: 2px 6px;
  }
  .history-item-band {
    font-size: 11px;
    padding: 2px 6px;
  }
  .history-item-title {
    font-size: 12px;
  }
  .writing-saved-report-head,
  .writing-saved-report-body {
    grid-template-columns: 1fr;
  }
  .writing-saved-report-head {
    display: grid;
  }
  .writing-saved-report-head > strong,
  .writing-saved-report-actions .writing-report-edit-btn {
    width: 100%;
  }
  .p3-start-button {
    min-height: 44px;
    font-size: 14px;
  }
}

/* Landscape phone orientation adjustments */
@media (max-height: 500px) and (orientation: landscape) {
  .nav {
    padding: 8px 12px;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
  }
  .nav-top {
    flex-direction: row;
    gap: 12px;
  }
  .nav-primary {
    flex-direction: row;
    gap: 6px;
  }
  .nav-bottom {
    flex-direction: row;
    border-top: none;
    padding-top: 0;
  }
  .workspace {
    padding: 10px 16px;
  }
  .prompt-pane,
  .recorder-pane {
    min-height: 200px;
  }
  .record-control {
    width: min(140px, 30vh);
    padding: 12px;
  }
  .record-control strong {
    font-size: 20px;
  }
}

/* Dark prompt bank hierarchy: keep the picker readable across all typefaces. */
body.theme-dark .writing-prompt-modal-card {
  --prompt-modal-shell: linear-gradient(180deg, #172433 0%, #0c1621 100%);
  --prompt-modal-toolbar: linear-gradient(180deg, rgba(26, 40, 54, 0.98), rgba(17, 29, 41, 0.98));
  --prompt-grid-tray: linear-gradient(180deg, rgba(7, 16, 25, 0.92), rgba(10, 20, 31, 0.96));
  --prompt-card-bg: #152233;
  --prompt-card-body: #111c2a;
  --prompt-card-hover: #1a2b40;
  --prompt-card-border: rgba(148, 163, 184, 0.30);
  --prompt-card-border-strong: rgba(52, 211, 153, 0.58);
  --prompt-chip-bg: #111d2b;
  --prompt-chip-hover: #1c3043;
  --prompt-active-bg: rgba(52, 211, 153, 0.18);
  --prompt-active-text: #d8fff0;
  --prompt-active-shadow: rgba(52, 211, 153, 0.20);
  background: var(--prompt-modal-shell) !important;
  border: 1px solid rgba(148, 163, 184, 0.30);
  box-shadow: 0 34px 90px rgba(0, 0, 0, 0.58);
}

body.theme-dark .writing-prompt-modal-card .modal-head {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0));
  border-bottom-color: rgba(148, 163, 184, 0.28);
}

body.theme-dark .writing-prompt-modal-toolbar {
  background: var(--prompt-modal-toolbar);
  border-bottom-color: rgba(148, 163, 184, 0.30);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045), 0 10px 30px rgba(0, 0, 0, 0.18);
}

body.theme-dark .writing-prompt-filter-wrap {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

body.theme-dark .writing-prompt-pattern-panel {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--dark-primary) 14%, transparent), transparent 44%),
    rgba(15, 23, 42, 0.48);
  border-color: rgba(148, 163, 184, 0.22);
}

body.theme-dark .writing-prompt-pattern-panel-head span {
  color: rgba(216, 225, 234, 0.68);
}

body.theme-dark .writing-prompt-pattern-panel-head strong {
  color: #ecfff8;
}

body.theme-dark .writing-prompt-pattern-panel-head svg {
  stroke: #8ff4d2;
}

body.theme-dark .writing-prompt-pattern-filters {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

body.theme-dark .writing-prompt-modal-toolbar .writing-task-switch {
  background: rgba(6, 14, 23, 0.72);
  border-color: rgba(148, 163, 184, 0.24);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

body.theme-dark .writing-prompt-modal-toolbar .writing-task-option {
  color: #aebdca;
}

body.theme-dark .writing-prompt-modal-toolbar .writing-task-option.active {
  color: #06121a;
  background: linear-gradient(180deg, var(--dark-primary), var(--dark-primary-strong));
  box-shadow: 0 10px 24px var(--prompt-active-shadow);
}

body.theme-dark .writing-source-filter,
body.theme-dark .writing-type-filter,
body.theme-dark .writing-pattern-filter {
  background: var(--prompt-chip-bg);
  border-color: rgba(148, 163, 184, 0.26);
  color: #d8e1ea;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

body.theme-dark .writing-source-filter:hover,
body.theme-dark .writing-type-filter:hover,
body.theme-dark .writing-pattern-filter:hover {
  background: var(--prompt-chip-hover);
  border-color: var(--prompt-card-border-strong);
  color: var(--prompt-active-text);
}

body.theme-dark .writing-source-filter.active,
body.theme-dark .writing-type-filter.active,
body.theme-dark .writing-pattern-filter.active {
  background: var(--prompt-active-bg);
  border-color: var(--prompt-card-border-strong);
  color: var(--prompt-active-text);
  box-shadow: 0 8px 20px var(--prompt-active-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

body.theme-dark .writing-source-filter span,
body.theme-dark .writing-type-filter span,
body.theme-dark .writing-pattern-filter span {
  color: rgba(216, 225, 234, 0.66);
}

body.theme-dark .writing-source-filter.active span,
body.theme-dark .writing-type-filter.active span,
body.theme-dark .writing-pattern-filter.active span {
  color: rgba(216, 255, 240, 0.78);
}

body.theme-dark .writing-prompt-pattern-badge {
  background: color-mix(in srgb, #f97316 16%, var(--dark-surface));
  border-color: color-mix(in srgb, #f97316 32%, var(--dark-border));
  color: #fed7aa;
}

body.theme-dark .writing-prompt-grid {
  background: var(--prompt-grid-tray);
  border-top: 1px solid rgba(255, 255, 255, 0.035);
  box-shadow: inset 0 18px 36px rgba(0, 0, 0, 0.18);
}

body.theme-dark .writing-prompt-section + .writing-prompt-section {
  border-top-color: rgba(148, 163, 184, 0.20);
}

body.theme-dark .writing-prompt-section-head h3 {
  color: #f0f7fb;
}

body.theme-dark .writing-prompt-section-head p,
body.theme-dark .writing-prompt-modal-toolbar p {
  color: rgba(216, 225, 234, 0.70);
}

body.theme-dark .writing-prompt-choice {
  position: relative;
  background: var(--prompt-card-bg) !important;
  border-color: var(--prompt-card-border);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.24);
}

body.theme-dark .writing-prompt-choice::before {
  content: "";
