  inset: 0 auto 0 0;
  width: 3px;
  background: transparent;
  transition: background var(--motion-fast), opacity var(--motion-fast);
  z-index: 2;
}

body.theme-dark .writing-prompt-choice:hover,
body.theme-dark .writing-prompt-choice.active {
  background: var(--prompt-card-hover) !important;
  border-color: var(--prompt-card-border-strong);
