  --chrome-surface-strong: linear-gradient(180deg, rgba(32, 49, 65, 0.98), rgba(18, 31, 44, 0.98));
  --chrome-border: rgba(148, 163, 184, 0.28);
  --chrome-border-strong: rgba(52, 211, 153, 0.50);
  --chrome-text: #eef7f4;
  --chrome-muted: rgba(222, 238, 233, 0.66);
  --chrome-active: linear-gradient(180deg, #34d399, #10b981);
  --chrome-active-text: #07140f;
  --chrome-glow: rgba(52, 211, 153, 0.20);
}

