  --chrome-border-strong: rgba(199, 184, 168, 0.52);
  --chrome-text: #f1ebe2;
  --chrome-muted: rgba(232, 221, 209, 0.66);
  --chrome-active: linear-gradient(180deg, #c8b9a8, #948574);
  --chrome-active-text: #1f1712;
  --chrome-glow: rgba(199, 184, 168, 0.16);
}

body.theme-dark.font-popular {
  --chrome-shell: rgba(8, 15, 28, 0.86);
  --chrome-surface: linear-gradient(180deg, rgba(23, 37, 61, 0.94), rgba(13, 24, 42, 0.94));
  --chrome-surface-strong: linear-gradient(180deg, rgba(31, 51, 84, 0.98), rgba(17, 31, 55, 0.98));
  --chrome-border: rgba(138, 180, 248, 0.28);
  --chrome-border-strong: rgba(138, 180, 248, 0.58);
  --chrome-text: #edf4ff;
  --chrome-muted: rgba(218, 229, 255, 0.66);
  --chrome-active: linear-gradient(180deg, #a8c7fa, #669df6);
