}

body.theme-dark .font-options {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.018)),
    color-mix(in srgb, var(--chrome-shell) 78%, #000);
  border: 1px solid color-mix(in srgb, var(--chrome-border) 90%, transparent);
  gap: 6px;
  padding: 6px;
  min-height: 52px;
  border-radius: 14px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 12px 26px rgba(0, 0, 0, 0.26);
}

body.theme-dark .font-options::before {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--chrome-border-strong) 28%, rgba(255, 255, 255, 0.08)), rgba(255, 255, 255, 0.035)),
    var(--chrome-surface-strong);
  border-color: var(--chrome-border-strong);
  top: 6px;
  left: 6px;
  width: calc((100% - 24px) / 3);
  height: calc(100% - 12px);
  border-radius: 12px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.10),
    0 8px 18px var(--chrome-glow),
    0 0 0 1px color-mix(in srgb, var(--chrome-border-strong) 28%, transparent);
}

body.theme-dark .font-options.academic::before {
  transform: translateX(calc(100% + 6px));
}

body.theme-dark .font-options.popular::before {
  transform: translateX(calc((100% + 6px) * 2));
}

body.theme-dark .font-option {
  min-height: 40px;
  height: 40px;
  border-radius: 12px;
  color: color-mix(in srgb, var(--chrome-text) 68%, var(--chrome-muted));
