/* ─── Writing frame hint + custom-frame modal ─────────────────────── */
.writing-frame-hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  margin: 0;
  font-size: 12px;
  color: var(--muted);
  line-height: 1.4;
  justify-content: flex-end;
}
.writing-frame-hint-lead {
  font-weight: 600;
  color: var(--ink);
  margin-right: 2px;
}
.writing-frame-hint-dot { color: var(--muted); opacity: 0.6; }
.writing-frame-cmd {
  appearance: none;
  background: transparent;
  border: 0;
  padding: 2px 0;
  color: var(--accent, #0f766e);
  font-size: 13px;
  cursor: pointer;
  text-decoration: none;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: unset;
}
.writing-frame-cmd code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  padding: 1px 6px;
  background: color-mix(in srgb, var(--accent, #0f766e) 10%, transparent);
  border-radius: 4px;
  color: inherit;
}
.writing-frame-cmd:hover { color: var(--accent-dark, #0d6460); text-decoration: underline; text-underline-offset: 3px; }
.writing-frame-cmd:hover code { background: color-mix(in srgb, var(--accent, #0f766e) 18%, transparent); }

/* Modal */
.writing-frame-modal-card {
  width: min(96vw, 1120px);
  height: min(92vh, 900px);
  max-height: calc(100vh - 32px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}
.writing-frame-modal-sub {
  margin: 6px 0 0;
  font-size: 14px;
  color: var(--muted);
}
.writing-frame-modal-body {
  min-height: 0;
  padding: 10px 34px 34px;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 12px;
  overflow: hidden;
}
.writing-frame-modal-help {
  margin: 0;
  font-size: 15px;
  color: var(--muted);
  line-height: 1.65;
}
.writing-frame-modal-help code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  padding: 2px 6px;
  background: color-mix(in srgb, var(--accent, #0f766e) 10%, transparent);
  border-radius: 4px;
  color: var(--accent, #0f766e);
}
.writing-frame-editor {
  width: 100%;
  height: 100%;
  min-height: 560px;
  padding: 20px 22px;
  font-family: "Source Han Serif SC", "Newsreader", Georgia, "Songti SC", serif;
  font-size: 18px;
  line-height: 1.75;
  border: 1px solid var(--line);
  border-radius: 12px;
  resize: none;
  overflow: auto;
  background: var(--panel);
  color: var(--ink);
  outline: none;
}
.writing-frame-editor:focus { border-color: var(--accent, #0f766e); }
.writing-frame-modal-card.is-saving .writing-frame-editor {
  opacity: 0.72;
  pointer-events: none;
}
.writing-frame-modal-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.writing-frame-modal-actions button {
  padding: 8px 18px;
  border-radius: 8px;
  border: 1px solid var(--accent, #0f766e);
  background: var(--accent, #0f766e);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  min-height: 36px;
}
.writing-frame-modal-actions button.ghost {
  background: transparent;
  color: var(--accent, #0f766e);
}
.writing-frame-modal-actions button:hover { background: var(--accent-dark, #0d6460); border-color: var(--accent-dark, #0d6460); color: #fff; }
.writing-frame-modal-actions button.ghost:hover { color: #fff; }
.writing-frame-modal-status {
  font-size: 12px;
  color: var(--muted);
  min-height: 18px;
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 7px;
}
.writing-frame-modal-card.is-saving .writing-frame-modal-status::before {
  content: "";
  width: 0.85em;
  height: 0.85em;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 999px;
  animation: busy-spin 720ms linear infinite;
}
.writing-frame-modal-status.error { color: #b91c1c; }

@media (max-height: 760px) {
  .writing-frame-modal-card {
    height: calc(100vh - 20px);
  }

  .writing-frame-editor {
    min-height: 420px;
  }
}

/* Corpus topic cards: quiet dashboard treatment, no decorative header icons/stripes. */
.p1-topic-card,
.p2-category-entry-card {
  border-top: 0 !important;
