/* ══════════════════════════════════════════════════════════════════════════
   P1 Library — paper checklist / pencil aesthetic  (light theme only)
   Visual-only restyle: no layout/flow changes. Scoped to .p1-topic-card under
   body:not(.theme-dark) so it overrides the quiet-dashboard block above without
   leaking into dark mode (which keeps its own treatment). Accent-driven, plus
   the same study-paper texture used by the Takeaway book.
   ══════════════════════════════════════════════════════════════════════════ */

/* ── Card → a sheet of ruled study paper ── */
body:not(.theme-dark) .p1-topic-card {
  /* --nr-hand is otherwise scoped to the spelling drill; redeclare so the card
     and its descendants can use the Caveat handwriting stack (loaded globally). */
  --nr-hand: "Caveat", "Newsreader", "Songti SC", "Source Han Serif SC", cursive;
  border: 1px solid rgba(79, 102, 94, 0.30);
  border-radius: 11px;
  background:
    linear-gradient(180deg, rgba(255, 253, 248, 0.84), rgba(249, 246, 239, 0.80)),
    url("/assets/takeaway/pencil-card-paper-light.webp") center / cover no-repeat,
    rgba(255, 251, 243, 0.97);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.8) inset,
    0 10px 24px rgba(83, 66, 55, 0.08);
}
body:not(.theme-dark) .p1-topic-card:hover {
  transform: translateY(-3px) rotate(-0.3deg);
  border-color: color-mix(in srgb, var(--p1-corpus-accent) 50%, rgba(79, 102, 94, 0.4));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.85) inset,
    0 16px 34px rgba(83, 66, 55, 0.14);
}

/* Faded red margin rule down the left, like a real notebook page */
body:not(.theme-dark) .p1-topic-card::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 34px;
  width: 1.5px;
  background: repeating-linear-gradient(180deg,
    color-mix(in srgb, #c2554e 50%, transparent) 0 7px,
    transparent 7px 11px);
  opacity: 0.5;
  pointer-events: none;
  z-index: 1;
}

/* ── Header → handwritten heading, dashed pencil rule under it ── */
body:not(.theme-dark) .p1-topic-card header {
  background: transparent !important;
  border-bottom: 1.5px dashed rgba(79, 102, 94, 0.32);
}
/* Topic title → Caveat handwriting in graphite ink */
body:not(.theme-dark) .p1-topic-card h3 {
  font-family: var(--nr-hand);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: #2f2924 !important;
}
/* Count → a hand-circled fraction, not a solid pill */
body:not(.theme-dark) .p1-topic-card .p1-topic-count {
  background: transparent !important;
  border: 1.6px solid color-mix(in srgb, var(--p1-corpus-accent) 45%, #8a9890);
  border-radius: 16px 14px 17px 13px / 14px 17px 13px 16px;
  color: color-mix(in srgb, var(--p1-corpus-accent) 72%, #2f2924) !important;
  font-family: var(--nr-hand);
  font-size: 18px;
  font-weight: 700;
  box-shadow: none !important;
}

/* ── Progress → an empty pencil-drawn capsule that fills with cross-hatch ── */
body:not(.theme-dark) .p1-topic-progress {
  background: color-mix(in srgb, var(--p1-corpus-accent) 5%, transparent);
  border: 1.5px solid color-mix(in srgb, var(--p1-corpus-accent) 28%, #9aa8a0);
  border-radius: 999px;
  height: 9px;
  overflow: hidden;
}
body:not(.theme-dark) .p1-topic-progress span {
  background: repeating-linear-gradient(45deg,
    var(--p1-corpus-accent) 0 4px,
    color-mix(in srgb, var(--p1-corpus-accent) 65%, #fff) 4px 8px);
  box-shadow: none;
}

/* ── Question rows → checklist items on dotted pencil rules ── */
body:not(.theme-dark) .p1-topic-question-list button {
  background: transparent;
  border-bottom: 1.5px dotted rgba(79, 102, 94, 0.28);
}
body:not(.theme-dark) .p1-topic-question-list button:hover {
  background: color-mix(in srgb, var(--p1-corpus-accent) 7%, transparent);
}
body:not(.theme-dark) .p1-topic-question-list button > span {
  color: #44403a;
}
/* Q badge → a wobbly hand-drawn checkbox with a pencilled label */
body:not(.theme-dark) .p1-topic-question-list strong {
  border-radius: 7px 6px 8px 5px / 6px 8px 5px 7px;
  border: 2px solid color-mix(in srgb, var(--p1-corpus-accent) 40%, #8a9890);
  background: transparent;
  color: color-mix(in srgb, var(--p1-corpus-accent) 55%, #6b7c74);
  font-family: var(--nr-hand);
  font-size: 13px;
  font-weight: 700;
}

/* ── Saved row → the box gets ticked, "已备" noted in the margin ── */
body:not(.theme-dark) .p1-topic-question-list button.has-corpus {
  background: color-mix(in srgb, var(--p1-corpus-accent) 8%, transparent);
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--p1-corpus-accent) 55%, transparent);
}
body:not(.theme-dark) .p1-topic-question-list button.has-corpus:hover {
  background: color-mix(in srgb, var(--p1-corpus-accent) 12%, transparent);
}
body:not(.theme-dark) .p1-topic-question-list button.has-corpus > span {
  color: #2f2924;
  font-weight: 600;
}
body:not(.theme-dark) .p1-topic-question-list button.has-corpus strong {
  background: color-mix(in srgb, var(--p1-corpus-accent) 15%, transparent);
  border-color: var(--p1-corpus-accent);
  color: transparent;
  font-size: 0;
  box-shadow: none;
}
body:not(.theme-dark) .p1-topic-question-list button.has-corpus strong::after {
  content: "✓";
  font-family: var(--nr-hand);
  font-size: 18px;
  font-weight: 700;
  color: var(--p1-corpus-accent);
}
body:not(.theme-dark) .p1-topic-question-list button.has-corpus::after {
  content: "已备";
  background: transparent;
  border: none;
  padding: 0;
  font-family: var(--nr-hand);
  font-size: 15px;
  font-weight: 600;
  color: color-mix(in srgb, var(--p1-corpus-accent) 70%, #2f2924);
}

