  background-color: var(--dark-surface) !important;
}

/* Final P3 launch workbench overrides. Kept at the end so older responsive rules cannot undo it. */
body.view-p3 .practice-panel.p3-launch-mode {
  display: grid;
  gap: 14px;
}

body.view-p3 .practice-panel.p3-launch-mode .phase-meter,
body.view-p3 .practice-panel.p3-launch-mode .cue-top {
  display: none;
}
/* Corpus workspace redesign: compact, task-oriented entry cards. */
.corpus-home-shell {
  max-width: 1280px;
  margin: 0 auto;
  padding: 26px 28px 32px;
  gap: 18px;
}

.corpus-home-head {
  min-height: 118px;
  align-items: center;
  padding: 22px 26px;
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.9)),
    var(--panel);
}

.corpus-home-head h2 {
  font-size: clamp(34px, 3.5vw, 52px);
  letter-spacing: 0;
}

.corpus-home-head p {
  max-width: 720px;
  font-size: 16px;
}

.corpus-home-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  grid-auto-flow: dense;
  gap: 16px;
}

.corpus-home-card {
  min-height: 142px;
  grid-template-rows: auto auto auto 1fr auto;
  grid-column: span 2;
  gap: 8px;
  padding: 20px 22px;
  border-radius: 18px;
  border-color: rgba(148, 163, 184, 0.22);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9)),
    var(--panel);
}

.corpus-home-card::before {
  width: 5px;
  opacity: 0.85;
}

.corpus-card-p1,
.corpus-card-p2 {
  grid-column: span 3;
  min-height: 168px;
}

.corpus-card-mark {
  min-height: 28px;
  padding: 0 11px;
  font-size: 12px;
}

.corpus-card-type {
  color: color-mix(in srgb, var(--muted) 88%, var(--ink));
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.corpus-home-card strong {
  color: #0f172a;
  font-size: 24px;
  line-height: 1.12;
  letter-spacing: 0;
}

.corpus-card-p1 strong,
.corpus-card-p2 strong {
  font-size: 28px;
}

.corpus-home-card small {
  max-width: 92%;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.55;
}

.corpus-card-cta {
  width: fit-content;
  margin-top: 4px;
  padding: 7px 12px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 999px;
  color: color-mix(in srgb, var(--ink) 80%, var(--accent));
  background: rgba(255, 255, 255, 0.72);
  font-size: 13px;
  font-weight: 850;
  line-height: 1;
}

.corpus-home-card:hover .corpus-card-cta {
  border-color: color-mix(in srgb, var(--accent) 34%, rgba(148, 163, 184, 0.24));
  color: var(--accent);
}

body.theme-dark .corpus-home-head,
body.theme-dark .corpus-home-card {
  background: linear-gradient(180deg, var(--dark-panel-top), var(--dark-panel-bottom));
  border-color: var(--dark-border);
}

body.theme-dark .corpus-home-card strong,
body.theme-dark .corpus-home-head h2 {
  color: var(--ink);
}

body.theme-dark .corpus-card-type,
body.theme-dark .corpus-home-card small,
body.theme-dark .corpus-home-head p {
  color: var(--muted);
}

body.theme-dark .corpus-card-cta {
  background: var(--dark-surface);
  border-color: var(--dark-border);
  color: color-mix(in srgb, var(--ink) 82%, var(--dark-primary));
}

@media (max-width: 1120px) {
  .corpus-home-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .corpus-home-card,
  .corpus-card-p1,
  .corpus-card-p2 {
    grid-column: span 1;
  }
}

@media (max-width: 720px) {
  .corpus-home-shell {
    padding: 18px 14px 24px;
  }

  .corpus-home-head {
    min-height: 0;
    padding: 18px;
  }

  .corpus-home-head h2 {
    font-size: 34px;
  }

  .corpus-home-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .corpus-home-card,
  .corpus-card-p1,
  .corpus-card-p2 {
    min-height: 132px;
    padding: 18px;
  }
}

/* ═══════════════════════════════════════════════════════════════
   DARK MODE ELEVATION REDESIGN
   Problem: all surfaces identical (#111b25) → "一坨黑"
   Solution: 3-level surface hierarchy + criterion-coloured cells
   ═══════════════════════════════════════════════════════════════ */

/* ── Level variables — DEFAULT theme (green-teal) ───────────── */
body.theme-dark {
  --ds-l1-bg: linear-gradient(160deg, #141f30 0%, #101929 100%);
  --ds-l1-border: rgba(52, 211, 153, 0.16);
  --ds-l2-bg: #182c3f;
  --ds-l2-border: rgba(52, 211, 153, 0.20);
  --ds-criterion-tr:  #10b981;
  --ds-criterion-cc:  #60a5fa;
  --ds-criterion-lr:  #f59e0b;
  --ds-criterion-gra: #a78bfa;
  --ds-criterion-fc:  #2dd4bf;
}

/* ── Academic — Claude-like warm charcoal (zero blue) ────────── */
body.theme-dark.font-academic {
  --ds-l1-bg: linear-gradient(160deg, #252017 0%, #1d1b15 100%);
  --ds-l1-border: rgba(198, 160, 113, 0.18);
  --ds-l2-bg: #2f2920;
  --ds-l2-border: rgba(198, 160, 113, 0.26);
  --ds-criterion-tr:  #c6a071;   /* warm gold */
  --ds-criterion-cc:  #8fa7a1;   /* muted sage */
  --ds-criterion-lr:  #d4a85f;   /* amber */
  --ds-criterion-gra: #c0836a;   /* terracotta */
  --ds-criterion-fc:  #a89f87;   /* warm stone */
}

/* ── Popular — Material / Google deep navy ───────────────────── */
body.theme-dark.font-popular {
  --ds-l1-bg: linear-gradient(160deg, #152135 0%, #0f1a2c 100%);
  --ds-l1-border: rgba(123, 183, 255, 0.18);
  --ds-l2-bg: #1c2f48;
  --ds-l2-border: rgba(123, 183, 255, 0.26);
  --ds-criterion-tr:  #7bb7ff;   /* sky blue */
  --ds-criterion-cc:  #a78bfa;   /* lavender */
  --ds-criterion-lr:  #fbbf24;   /* amber */
  --ds-criterion-gra: #4ade80;   /* green */
  --ds-criterion-fc:  #2dd4bf;   /* teal */
}

/* ── L1 cards: primary report / account / overall review cards ── */
body.theme-dark .writing-score-summary-card,
body.theme-dark .speaking-score-summary-card,
body.theme-dark .writing-saved-report-card,
body.theme-dark .writing-saved-answer-card,
body.theme-dark .writing-overall-content,
body.theme-dark .overall-review-card,
body.theme-dark .account-profile-card,
body.theme-dark .account-wallet-card,
body.theme-dark .settings-card,
body.theme-dark .auth-card {
  background: var(--ds-l1-bg) !important;
  border-color: var(--ds-l1-border) !important;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.04) inset,
    0 20px 50px rgba(0,0,0,0.30) !important;
}

/* ── L2 score cells ──────────────────────────────────────────── */
body.theme-dark .score-cell,
body.theme-dark .writing-score-summary-grid .score-cell,
body.theme-dark .speaking-score-summary-grid .score-cell {
  background: var(--ds-l2-bg) !important;
  border-color: var(--ds-l2-border) !important;
  box-shadow: none !important;
  position: relative;
  overflow: hidden;
}

/* Left-border accent strip by criterion */
body.theme-dark .score-cell::before,
body.theme-dark .writing-score-summary-grid .score-cell::before,
body.theme-dark .speaking-score-summary-grid .score-cell::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  border-radius: 3px 0 0 3px;
  background: var(--ds-criterion-tr); /* default */
}

body.theme-dark .score-cell[data-criterion="TR"]::before  { background: var(--ds-criterion-tr);  }
body.theme-dark .score-cell[data-criterion="CC"]::before  { background: var(--ds-criterion-cc);  }
body.theme-dark .score-cell[data-criterion="LR"]::before  { background: var(--ds-criterion-lr);  }
body.theme-dark .score-cell[data-criterion="GRA"]::before { background: var(--ds-criterion-gra); }
body.theme-dark .score-cell[data-criterion="FC"]::before  { background: var(--ds-criterion-fc);  }
