/* ── Home workspace redesign ------------------------------------------------ */
.home-v2-panel {
  display: grid;
  gap: 16px;
  min-height: auto;
  align-content: start;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.home-v2-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 360px);
  gap: 16px;
  align-items: stretch;
  min-height: 0;
  padding: 24px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 20px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 251, 255, 0.96) 58%, rgba(245, 250, 247, 0.98)),
    #fff;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.home-v2-hero::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 5px;
  background: linear-gradient(90deg, #3a8d72, #6f9eff, #c47d60);
}

.home-v2-copy {
  position: relative;
  z-index: 1;
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 12px;
  max-width: 760px;
}

.home-v2-eyebrow,
.home-v2-module-head span,
.home-v2-spotlight span,
.home-v2-link > span {
  width: fit-content;
  min-height: 26px;
  display: inline-grid;
  place-items: center;
  padding: 0 11px;
  border-radius: 999px;
  color: #2f806d;
  background: rgba(48, 128, 109, 0.10);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.home-v2-copy h2 {
  margin: 0;
  max-width: 760px;
  color: #182034;
  font-size: clamp(34px, 4vw, 56px);
  line-height: 1.06;
  letter-spacing: 0;
}

.home-v2-copy p {
  margin: 0;
  max-width: 680px;
  color: #5d6879;
  font-size: 16px;
  line-height: 1.6;
}

.home-v2-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 4px;
}

.home-v2-primary,
.home-v2-secondary {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 20px;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 900;
  text-decoration: none;
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
}

.home-v2-primary {
  color: #fff;
  background: #2f806d;
  box-shadow: 0 16px 30px rgba(47, 128, 109, 0.22);
}

.home-v2-secondary {
  color: #203047;
  background: rgba(255, 255, 255, 0.86);
  border: 1px solid rgba(15, 23, 42, 0.11);
}

.home-v2-primary:hover,
.home-v2-secondary:hover,
.home-v2-link:hover {
  transform: translateY(-2px);
}

.home-v2-primary:focus-visible,
.home-v2-secondary:focus-visible,
.home-v2-link:focus-visible {
  outline: 3px solid rgba(111, 158, 255, 0.32);
  outline-offset: 3px;
}

.home-v2-spotlight {
  position: relative;
  z-index: 1;
  display: grid;
  align-content: end;
  gap: 10px;
  min-height: 100%;
  padding: 18px;
  border: 1px solid rgba(47, 128, 109, 0.16);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(239, 248, 245, 0.88)),
    rgba(255, 255, 255, 0.74);
}

.home-v2-spotlight strong {
  color: #182034;
  font-size: 21px;
  line-height: 1.2;
}

.home-v2-spotlight p {
  margin: 0;
  color: #647084;
  font-size: 14px;
  line-height: 1.65;
}

.home-v2-modules {
  display: grid;
  gap: 16px;
}

.home-v2-module {
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.06);
}

.home-v2-module-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.home-v2-module-head strong {
  color: #1c2435;
  font-size: 22px;
  line-height: 1.15;
}

.home-v2-link-grid {
  display: grid;
  gap: 14px;
}

.home-v2-link-grid.four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.home-v2-link-grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.home-v2-link-grid.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.home-v2-link {
  position: relative;
  min-height: 118px;
  display: grid;
  grid-template-rows: auto auto 1fr;
  align-content: start;
  gap: 10px;
  padding: 16px;
  border: 1px solid rgba(15, 23, 42, 0.10);
  border-radius: 16px;
  background: #fff;
  color: #172033;
  text-decoration: none;
  overflow: hidden;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.04);
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background 160ms ease;
}

.home-v2-link::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: var(--home-link-accent, #2f806d);
}

.home-v2-link:hover {
  border-color: color-mix(in srgb, var(--home-link-accent, #2f806d) 38%, rgba(15, 23, 42, 0.10));
  box-shadow: 0 18px 34px rgba(15, 23, 42, 0.10);
}

.home-v2-link strong {
  position: relative;
  z-index: 1;
  color: #172033;
  font-size: 19px;
  line-height: 1.18;
}

.home-v2-link small {
  position: relative;
  z-index: 1;
  color: #667386;
  font-size: 14px;
  line-height: 1.5;
}

.home-v2-link.tone-p1 { --home-link-accent: #3dbb75; }
.home-v2-link.tone-p2 { --home-link-accent: #4f7df3; }
.home-v2-link.tone-p3 { --home-link-accent: #8b5cf6; }
.home-v2-link.tone-mock { --home-link-accent: #d95d4f; }
.home-v2-link.tone-writing { --home-link-accent: #c47d60; }
.home-v2-link.tone-report { --home-link-accent: #2f806d; }
.home-v2-link.tone-corpus { --home-link-accent: #4f7df3; }
.home-v2-link.tone-takeaway { --home-link-accent: #0f9f8e; }
.home-v2-link.tone-spelling { --home-link-accent: #c47d60; }

.home-v2-link.tone-p1 > span { color: #16834b; background: rgba(61, 187, 117, 0.12); }
.home-v2-link.tone-p2 > span,
.home-v2-link.tone-corpus > span { color: #315edb; background: rgba(79, 125, 243, 0.12); }
.home-v2-link.tone-p3 > span { color: #6d38d6; background: rgba(139, 92, 246, 0.12); }
.home-v2-link.tone-mock > span { color: #b33d32; background: rgba(217, 93, 79, 0.12); }
.home-v2-link.tone-writing > span,
.home-v2-link.tone-spelling > span { color: #9d543c; background: rgba(196, 125, 96, 0.12); }
.home-v2-link.tone-report > span,
.home-v2-link.tone-takeaway > span { color: #237464; background: rgba(47, 128, 109, 0.12); }

