}

body.view-home .home-v2-module-corpus {
  grid-column: span 6;
}

body.view-home .home-v2-link {
  min-height: 112px;
}

body.view-home .home-v2-link strong {
  font-size: 18px;
}

body.theme-dark.view-home .workspace {
  background:
    radial-gradient(circle at 12% 8%, rgba(79, 125, 243, 0.16), transparent 32%),
