    linear-gradient(180deg, #0f151c, #111923);
}

@media (max-width: 1280px) {
  .home-v2-hero {
    grid-template-columns: minmax(0, 1fr);
    padding: 22px;
  }

  .home-v2-copy h2 {
    font-size: clamp(32px, 4.2vw, 48px);
  }

  .home-v2-link-grid.four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  body.view-home .home-v2-modules {
    grid-template-columns: 1fr;
  }

  body.view-home .home-v2-module-speaking,
  body.view-home .home-v2-module-writing,
  body.view-home .home-v2-module-corpus {
    grid-column: 1 / -1;
  }

  .home-v2-hero {
    grid-template-columns: 1fr;
  }

  .home-v2-link-grid.two,
  .home-v2-link-grid.three,
  .home-v2-link-grid.four {
    grid-template-columns: 1fr;
  }

  .home-v2-module-head {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 640px) {
  .home-v2-panel {
    gap: 14px;
  }

  .home-v2-hero,
  .home-v2-module {
    border-radius: 14px;
    padding: 18px;
  }

  .home-v2-copy h2 {
    font-size: 34px;
  }

  .home-v2-actions {
    width: 100%;
  }

  .home-v2-primary,
  .home-v2-secondary {
    width: 100%;
  }
}

/* Home canonical workspace layout.
   Home keeps the standard sidebar shell; only the inner dashboard composition is
   custom. Keep this block late so older home media-query rules do not re-hide
   the navigation. */
body.view-home {
  overflow-x: hidden;
  overflow-y: auto;
  background:
    radial-gradient(circle at 14% 8%, rgba(79, 125, 243, 0.10), transparent 32%),
    radial-gradient(circle at 88% 4%, rgba(47, 128, 109, 0.12), transparent 30%),
    linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(243, 246, 250, 0.98));
}

body.view-home .nav {
  display: flex !important;
}

body.view-home .global-topbar {
  display: flex !important;
  align-items: center;
  left: var(--sidebar-width);
  right: 0;
  height: 48px;
  padding: 0 16px;
}

body.view-home .global-topbar .topbar-back-button,
body.view-home .global-topbar .writing-topbar-actions,
body.view-home .global-topbar .global-topbar-spacer {
  display: none !important;
}

body.view-home .global-topbar-actions {
  margin-left: auto;
}

body.view-home .workspace,
body.view-home .workspace:has(#homePanel:not(.hidden)) {
  margin-left: var(--sidebar-width) !important;
  width: calc(100% - var(--sidebar-width));
  max-width: none;
  min-height: 100vh;
  min-height: 100dvh;
  height: auto;
  display: block;
  overflow: visible;
  padding: calc(76px + var(--safe-top)) clamp(18px, 2.4vw, 30px) calc(40px + var(--safe-bottom));
  background: transparent;
}

body.view-home .topbar,
body.view-home #viewTitleBlock,
body.view-home .busy-bar.hidden {
  display: none !important;
}

body.view-home .home-v2-panel {
  width: min(100%, 1480px);
  margin: 0 auto;
  display: grid;
  gap: 24px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

body.view-home .home-v3-panel {
  width: min(100%, 1320px);
  margin: 0 auto;
  display: grid;
  gap: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

body.view-home .home-v3-hero {
