  padding: 28px;
  border: 1px solid rgba(47, 128, 109, 0.14);
  border-radius: 22px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(240, 249, 246, 0.88)),
    #f7fbf9;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

body.view-home .home-v3-today > span,
body.view-home .home-v3-lane-head span {
  width: max-content;
