  position: relative;
  z-index: 1;
}
body.view-home .home-loop-title {
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: 21px;
  font-weight: 800;
}
body.view-home .home-loop-sub {
  font-size: 13px;
  font-weight: 720;
}
body.view-home .home-loop-num {
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: 17px;
  font-weight: 800;
}

body.view-home .home-v3-today ol {
  display: grid;
