.topbar-review-panel {
  position: relative;
  width: min(500px, 45vw);
  height: 56px;
  min-height: 56px;
  padding: 6px 12px 6px 18px;
  align-self: center;
  border: 1.5px solid rgba(63, 126, 108, 0.30);
  border-radius: 18px 22px 17px 20px;
  background:
    linear-gradient(90deg, rgba(63, 126, 108, 0.06), rgba(255, 253, 247, 0.9)),
    rgba(250, 255, 248, 0.94);
  box-shadow: 3px 4px 0 rgba(63, 126, 108, 0.07), 0 12px 26px rgba(63, 126, 108, 0.10);
  overflow: visible;
}

.topbar-review-panel.is-active {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
}

.topbar-review-panel .takeaway-review-exit.icon-exit-button {
  position: absolute;
  left: -74px;
  right: auto;
  top: 50%;
  width: 56px;
  height: 56px;
  min-width: 56px;
  transform: translateY(-50%);
  background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
  box-shadow: 0 10px 22px rgba(220, 38, 38, 0.24);
  animation: exitBreath 1.8s ease-in-out infinite;
}

.topbar-review-panel .takeaway-review-exit.icon-exit-button:hover {
  background: linear-gradient(180deg, #f87171 0%, #ef4444 100%);
  box-shadow: 0 12px 26px rgba(220, 38, 38, 0.32);
  transform: translateY(-50%);
}

.topbar-review-panel .takeaway-review-exit.icon-exit-button:active {
  transform: translateY(-50%) scale(0.94);
}

