  z-index: 1;
  display: grid;
  align-content: center;
  max-width: 520px;
}

body.view-home .home-v3-eyebrow {
  width: max-content;
  margin-bottom: 16px;
  padding: 6px 12px;
  border: 1.5px solid rgba(47, 128, 109, 0.35);
  border-radius: 999px 14px 999px 18px;
  background: rgba(47, 128, 109, 0.07);
  color: #2f806d;
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transform: rotate(-1.2deg);
}

body.view-home .home-v3-copy h2 {
  max-width: 520px;
  margin: 0;
  color: #172033;
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: clamp(30px, 3.5vw, 48px);
  font-weight: 840;
  letter-spacing: 0;
  line-height: 1.18;
  text-shadow: 0.5px 0 rgba(23, 32, 51, 0.22);
}

body.view-home .home-v3-route-title {
  display: grid;
  justify-items: start;
  gap: 8px;
}

body.view-home .home-v3-route-title span {
  white-space: nowrap;
}

body.view-home .home-v3-route-title span:last-child {
  font-size: clamp(28px, 3vw, 42px);
}

body.view-home .home-v3-route-title svg {
  width: 42px;
  height: 38px;
  margin-left: clamp(54px, 7vw, 92px);
  fill: none;
  stroke: #517d73;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(1px 1px 0 rgba(81, 125, 115, 0.12));
  transform: rotate(-1.5deg);
}

body.view-home .home-v3-copy p {
  display: none;
}

body.view-home .home-v3-actions {
  margin-top: 24px;
}

body.view-home .home-v3-primary,
body.view-home .home-v3-secondary {
  min-height: 44px;
  border-radius: 12px 16px 13px 15px;
  border: 1.5px solid rgba(23, 32, 51, 0.24);
  background: rgba(255, 255, 255, 0.66);
  color: #172033;
  box-shadow: 3px 4px 0 rgba(23, 32, 51, 0.09);
}

body.view-home .home-v3-primary {
  background: rgba(47, 128, 109, 0.12);
  color: #276f60;
}

body.view-home .sketch-flow-board {
  position: relative;
  /* Lock the board to the connector SVG's aspect ratio (620 x 430). With a
     matching aspect ratio, `preserveAspectRatio="none"` scales the viewBox
     uniformly, so the arrows no longer skew. align-self: start stops the grid
     from stretching the board taller (which would re-introduce the skew). */
  aspect-ratio: 620 / 430;
  align-self: start;
  min-height: 0;
  padding: 0;
  overflow: hidden;
  border: 1.5px solid rgba(45, 55, 72, 0.16);
  border-radius: 18px 22px 16px 20px;
  background: #fffaf0;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.74), 6px 7px 0 rgba(45, 55, 72, 0.04);
}

body.view-home .sketch-flow-board img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.72;
  filter: saturate(0.55) contrast(0.94);
}

body.view-home .sketch-flow-overlay {
  /* Fill the board via inset:0 rather than height:100%. The board's height comes
     from aspect-ratio, which isn't a "definite" height for a percentage-height
     child — height:100% would collapse and squash the step percentages. */
  position: absolute;
  inset: 0;
  z-index: 1;
  padding: 28px;
}

body.view-home .sketch-flow-overlay > span {
  width: max-content;
  display: inline-flex;
  margin: 0;
  padding: 7px 18px;
  border: 1.5px solid color-mix(in srgb, var(--accent) 36%, transparent);
  border-radius: 999px 18px 999px 16px;
  background: color-mix(in srgb, var(--accent) 14%, var(--panel));
  color: var(--accent-dark);
  font-size: 13px;
  font-weight: 950;
  letter-spacing: 0.10em;
  text-transform: uppercase;
}

body.view-home .sketch-flow-step {
  position: absolute;
  z-index: 3;
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  column-gap: 12px;
  row-gap: 4px;
  width: min(330px, 42%);
  padding: 12px 14px;
  border: 1.5px solid rgba(45, 55, 72, 0.18);
  border-radius: 18px 14px 18px 16px;
  background: rgba(255, 253, 246, 0.82);
  box-shadow: 3px 4px 0 rgba(45, 55, 72, 0.055);
}

body.view-home .sketch-flow-step::after {
  content: none;
}

body.view-home .sketch-flow-connectors {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

body.view-home .sketch-flow-connector {
  fill: none;
  stroke: color-mix(in srgb, var(--accent) 88%, transparent);
  stroke-width: 3.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  marker-end: url("#sketchFlowConnectorHead");
  filter:
    drop-shadow(0 0 2px color-mix(in srgb, var(--panel) 88%, transparent))
    drop-shadow(0 1px 2px color-mix(in srgb, var(--accent-dark) 28%, transparent));
}

body.view-home .sketch-flow-connectors marker path {
  fill: color-mix(in srgb, var(--accent) 92%, transparent);
}

body.view-home .sketch-flow-step b {
  grid-row: 1 / 3;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1.5px solid color-mix(in srgb, var(--accent-dark) 50%, transparent);
  border-radius: 50%;
  background: linear-gradient(165deg, var(--accent), var(--accent-dark));
  color: #fff;
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: 24px;
  font-weight: 800;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.28);
  box-shadow: 0 5px 14px -5px color-mix(in srgb, var(--accent-dark) 55%, transparent);
}

body.view-home .sketch-flow-step strong {
  color: var(--ink);
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-size: clamp(22px, 2vw, 30px);
  font-weight: 900;
  line-height: 1.05;
}

body.view-home .sketch-flow-step small {
  color: var(--muted);
  font-size: 15px;
  font-weight: 820;
  line-height: 1.3;
}

/* The three cards sit at the corners of a clockwise triangle (1 top-left,
   2 mid-right, 3 bottom-left). Positions are percentages so they track the
   board as it scales, keeping them locked to the connector arrows. */
body.view-home .sketch-flow-step.step-1 {
  top: 11%;
  left: 4%;
  transform: rotate(-1deg);
}

body.view-home .sketch-flow-step.step-1::after {
  content: none;
}

body.view-home .sketch-flow-step.step-2 {
  top: 40%;
  right: 4%;
  transform: rotate(1.1deg);
}

body.view-home .sketch-flow-step.step-2::after {
  content: none;
}

body.view-home .sketch-flow-step.step-3 {
  left: 9%;
  bottom: 9%;
  transform: rotate(-0.7deg);
}

body.view-home .home-v3-workbench {
  border: 1.5px solid rgba(45, 55, 72, 0.15);
  border-radius: 18px 22px 16px 20px;
  background: rgba(255, 253, 246, 0.82);
  box-shadow: 5px 6px 0 rgba(45, 55, 72, 0.04);
}

body.view-home .home-v3-lane {
  padding: 18px 22px;
}

body.view-home .home-v3-lane-head span {
  border: 1px solid rgba(47, 128, 109, 0.20);
  background: rgba(47, 128, 109, 0.07);
}

body.view-home .home-v3-links {
  border: 1.5px solid rgba(45, 55, 72, 0.14);
  border-radius: 14px 16px 12px 15px;
  background: rgba(255, 255, 255, 0.55);
}

body.view-home .home-v3-links a {
  min-height: 76px;
  background: transparent;
}

body.theme-dark.view-home .home-v3-hero,
body.theme-dark.view-home .home-v3-workbench,
body.theme-dark.view-home .sketch-flow-board {
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255, 255, 255, 0.035) 1px, transparent 1px),
    #141923;
  background-size: 28px 28px;
  border-color: rgba(255, 255, 255, 0.13);
}

body.theme-dark.view-home .sketch-flow-board img {
  opacity: 0.38;
  filter: saturate(0.3) invert(0.08) contrast(0.84);
}

body.theme-dark.view-home .home-v3-copy h2,
body.theme-dark.view-home .sketch-flow-step strong {
  color: #f7f1e8;
}

body.theme-dark.view-home .sketch-flow-step,
body.theme-dark.view-home .home-v3-links,
body.theme-dark.view-home .home-v3-primary,
body.theme-dark.view-home .home-v3-secondary {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.13);
}

body.theme-dark.view-home .sketch-flow-step small {
  color: rgba(226, 232, 240, 0.72);
}

body.theme-dark.view-home .sketch-flow-step b {
  border-color: color-mix(in srgb, var(--accent) 55%, transparent);
  background: linear-gradient(165deg, var(--accent), var(--accent-dark));
  color: #fff;
  box-shadow: 0 5px 14px -5px rgba(0, 0, 0, 0.5);
}

/* =====================================================================
   Dark + Academic ("第二个主题"): the home page hardcodes a teal/green
   accent (#2f806d, plus the sketch-flow teal gradient/connectors) which
   reads as a cool colour and clashes with this theme's warm terracotta
   --accent. Remap the home accents onto the theme accent so the home page
   matches the surrounding warm UI. Scoped to dark+academic only — the
   default and font-popular themes keep their original teal.
   ===================================================================== */
body.theme-dark.font-academic.view-home .home-v3-eyebrow,
body.theme-dark.font-academic.view-home .home-v3-today > span,
body.theme-dark.font-academic.view-home .home-v3-lane-head span,
body.theme-dark.font-academic.view-home .home-v3-today li::before,
body.theme-dark.font-academic.view-home .sketch-flow-overlay > span {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  border-color: color-mix(in srgb, var(--accent) 40%, transparent);
  color: var(--accent-dark);
}

body.theme-dark.font-academic.view-home .home-v3-links b {
  color: var(--accent-dark);
}

body.theme-dark.font-academic.view-home .home-v3-links a:hover {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

body.theme-dark.font-academic.view-home .home-v3-route-title svg {
  stroke: var(--accent-dark);
  filter: drop-shadow(1px 1px 0 color-mix(in srgb, var(--accent) 14%, transparent));
}

body.theme-dark.font-academic.view-home .home-v3-primary {
  background: var(--accent);
  color: #1b1410;
  border-color: transparent;
  box-shadow:
    0 16px 32px rgba(0, 0, 0, 0.34),
    0 0 0 1px color-mix(in srgb, var(--accent) 42%, transparent);
}

body.theme-dark.font-academic.view-home .sketch-flow-step b {
  border-color: color-mix(in srgb, var(--accent-dark) 60%, transparent);
  background: linear-gradient(165deg, var(--accent), var(--accent-dark));
  color: #fff;
  box-shadow: 0 5px 14px -5px rgba(0, 0, 0, 0.5);
}

body.theme-dark.font-academic.view-home .sketch-flow-connector {
  stroke: color-mix(in srgb, var(--accent) 82%, transparent);
  filter:
    drop-shadow(0 1px 0 rgba(0, 0, 0, 0.26))
    drop-shadow(0 0 11px color-mix(in srgb, var(--accent) 22%, transparent));
}

body.theme-dark.font-academic.view-home .sketch-flow-connectors marker path {
  fill: color-mix(in srgb, var(--accent) 90%, transparent);
}

@media (max-width: 1180px) {
  body.view-home .home-v3-hero {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  body.view-home .home-v3-copy {
    max-width: none;
  }

  body.view-home .home-v3-copy h2 {
    max-width: 760px;
  }
}

@media (max-width: 760px) {
  body.view-home .home-v3-hero {
    padding: 20px;
  }

  body.view-home .sketch-flow-board,
  body.view-home .sketch-flow-overlay {
    min-height: 0;
  }

  /* Mobile stacks the cards in normal flow: drop the desktop aspect-ratio and
     the absolute overlay so the board grows with its content. */
  body.view-home .sketch-flow-board {
    aspect-ratio: auto;
  }

  body.view-home .sketch-flow-board img {
    opacity: 0.34;
  }

  body.view-home .sketch-flow-overlay {
    position: relative;
    display: grid;
    gap: 12px;
    height: auto;
    padding: 18px;
  }

  body.view-home .sketch-flow-connectors {
    display: none;
  }

  body.view-home .sketch-flow-step,
  body.view-home .sketch-flow-step.step-1,
  body.view-home .sketch-flow-step.step-2,
  body.view-home .sketch-flow-step.step-3 {
    position: relative;
    inset: auto;
    width: 100%;
    transform: none;
  }

  body.view-home .sketch-flow-step::after {
    display: none;
  }
}

@media (max-width: 900px) {
  .language-book-shell {
    padding: 18px;
  }

  .language-book-head,
  .takeaway-review-panel {
    grid-template-columns: minmax(0, 1fr);
    align-items: stretch;
  }

  .topbar-review-panel {
    width: min(340px, 54vw);
    height: 56px;
    min-height: 56px;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
  }

  .takeaway-review-panel-actions {
    grid-template-columns: auto repeat(2, minmax(0, 1fr));
  }

  .language-book-head {
    flex-direction: column;
  }

  .language-book-actions {
    justify-content: flex-start;
  }

  .language-takeaway-list {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .language-takeaway-card-wrap.is-review-due .language-takeaway-card {
    animation: none;
  }
}

/* Corpus home fixed workspace: title, P1/P2 row, then compact review lane. */
.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) {
  box-sizing: border-box;
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  overflow: hidden;
  padding: calc(56px + var(--safe-top)) clamp(16px, 2vw, 26px) calc(18px + var(--safe-bottom));
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-panel {
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-shell {
  width: 100%;
  height: 100%;
  min-height: 0;
  max-width: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-rows: auto auto auto;
  gap: clamp(12px, 1.4vw, 18px);
  overflow: hidden;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-kicker-bar {
  display: grid;
  gap: 4px;
  padding: 0 2px;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-title {
  display: block;
  margin: 0;
  color: #172033;
  font-size: 26px;
  font-weight: 860;
  line-height: 1.12;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-sub {
  max-width: none;
  margin: 0;
  color: color-mix(in srgb, var(--muted) 86%, #111827);
  font-size: 14px;
  line-height: 1.45;
  white-space: nowrap;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-top-cards {
  min-height: 0;
  display: flex;
  flex-direction: row;
  gap: clamp(14px, 1.6vw, 22px);
  align-items: stretch;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-card-p1,
.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-card-p2 {
  flex: 1 1 0;
  width: 50%;
  min-height: 270px;
  height: clamp(270px, 36vh, 360px);
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-review-lane {
  min-height: 92px;
  display: grid;
  grid-template-columns: minmax(118px, 0.18fr) minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  padding: 14px 16px;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-review-link {
  min-height: 64px;
  padding: 10px 14px;
}

body.theme-dark .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-title {
  color: #f3f4f6;
}

body.theme-dark .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-sub {
  color: rgba(226, 232, 240, 0.78);
}

/* Final dark home background guard: later sketchbook light rules use !important. */
html:has(body.theme-dark.view-home) {
  min-height: 100%;
  background: #0c1219 !important;
}

body.theme-dark.view-home,
body.theme-dark.view-home .shell {
  min-height: 100vh;
  min-height: 100dvh;
  background:
    radial-gradient(circle at 14% 8%, rgba(72, 112, 164, 0.12), transparent 30%),
    radial-gradient(circle at 84% 10%, rgba(47, 128, 109, 0.10), transparent 28%),
    linear-gradient(180deg, #0f151c 0%, #0c1219 100%) !important;
}

body.theme-dark.view-home .workspace,
body.theme-dark.view-home .workspace:has(#homePanel:not(.hidden)) {
  min-height: 100vh;
  min-height: 100dvh;
  background:
    radial-gradient(circle at 12% 8%, rgba(47, 128, 109, 0.08), transparent 34%),
    linear-gradient(180deg, #111923 0%, #0c1219 100%) !important;
}

body.theme-dark.view-home .global-topbar {
  background:
    linear-gradient(180deg, rgba(12, 18, 25, 0.94), rgba(12, 18, 25, 0.76)) !important;
}

body.theme-dark.view-home .home-panel,
body.theme-dark.view-home .home-v3-panel {
  background: transparent !important;
}

/* =====================================================================
   Dark + Academic ("第二个主题"): warm the 首页 / 语料库 底色. The home and
   corpus pages fill their backgrounds with a cool navy + blue/teal glows
   (#0c1219 / #111923 / #141923) that fight this theme's warm accent. The
   theme's --bg is already a warm charcoal, so remap these hardcoded page
   backgrounds + glows onto warm tones too. Scoped to dark+academic; the
   default and font-popular themes keep their cool navy base.
   ===================================================================== */
body.theme-dark.font-academic {
  background:
    radial-gradient(circle at 20% 0%, color-mix(in srgb, var(--accent) 9%, transparent), transparent 28%),
    var(--bg) !important;
}

html:has(body.theme-dark.font-academic.view-home) {
  background: #0d0a08 !important;
}

body.theme-dark.font-academic.view-home,
body.theme-dark.font-academic.view-home .shell {
  background:
    radial-gradient(circle at 14% 8%, color-mix(in srgb, var(--accent) 13%, transparent), transparent 30%),
    radial-gradient(circle at 84% 10%, color-mix(in srgb, var(--warn) 10%, transparent), transparent 28%),
    linear-gradient(180deg, #15100c 0%, #0d0a08 100%) !important;
}

body.theme-dark.font-academic.view-home .workspace,
body.theme-dark.font-academic.view-home .workspace:has(#homePanel:not(.hidden)) {
  background:
    radial-gradient(circle at 12% 8%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 34%),
    linear-gradient(180deg, #191310 0%, #0d0a08 100%) !important;
}

body.theme-dark.font-academic.view-home .global-topbar {
  background:
    linear-gradient(180deg, rgba(21, 16, 12, 0.94), rgba(21, 16, 12, 0.76)) !important;
}

body.theme-dark.font-academic.view-home .home-v3-hero,
body.theme-dark.font-academic.view-home .home-v3-workbench,
body.theme-dark.font-academic.view-home .sketch-flow-board {
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255, 255, 255, 0.035) 1px, transparent 1px),
    #1c150f !important;
  background-size: 28px 28px !important;
}

/* Corpus library landing (语料库) — same warm remap of the cool navy base. */
body.theme-dark.font-academic .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) {
  background:
    radial-gradient(circle at 18% 10%, color-mix(in srgb, var(--accent) 15%, transparent), transparent 32%),
    radial-gradient(circle at 82% 16%, color-mix(in srgb, var(--warn) 10%, transparent), transparent 34%),
    linear-gradient(180deg, #15100c 0%, #0c0907 100%) !important;
}

body.theme-dark.font-academic .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-home-card,
body.theme-dark.font-academic .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) .corpus-review-lane {
  background:
    linear-gradient(90deg, rgba(214, 224, 224, 0.045) 1px, transparent 1px),
    linear-gradient(180deg, rgba(214, 224, 224, 0.036) 1px, transparent 1px),
    linear-gradient(180deg, rgba(38, 30, 25, 0.96), rgba(28, 22, 18, 0.96)) !important;
  background-size: 30px 30px, 30px 30px, auto !important;
}

/* Writing topbar final absolute-last guard: expand the middle prompt selector
   into the empty area without scaling text or button internals. */
body.view-writing .global-topbar > .writing-topbar-actions:not(.hidden) {
  left: calc(var(--sidebar-width) + clamp(26px, 2.4vw, 44px)) !important;
  right: calc(280px + 20px + clamp(26px, 2.4vw, 44px)) !important;
  grid-template-columns: 256px minmax(0, 1fr) auto !important;
  justify-content: stretch !important;
  gap: 12px !important;
}

.writing-topbar-actions .writing-task-switch {
  width: 256px !important;
}

.writing-topbar-actions .writing-picker-button {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
}

.writing-topbar-actions .topbar-random-button {
  min-width: 118px !important;
  padding-inline: 11px !important;
  gap: 6px !important;
}

/* FINAL OVERRIDE — clean red recording gradients.
   Recording/Stop must stay in the warm red family; avoid blue/green/purple overlays
   that blend into dirty grey on the large circular control. */
.record-control.recording,
