/* Final P3 intensity switch: clearer segmented affordance and centered help copy. */
.p3-mode-row .p3-mode-help {
  text-align: center !important;
  max-width: none !important;
  margin: 2px auto 0 !important;
}

.p3-mode-row .p3-mode-switch {
  --p3-switch-pad: 6px;
  --p3-switch-gap: 6px;
  isolation: isolate;
  position: relative !important;
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: var(--p3-switch-gap) !important;
  padding: var(--p3-switch-pad) !important;
  overflow: hidden !important;
  border-radius: 16px !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(248, 250, 252, 0.94)) !important;
  border: 1px solid rgba(148, 163, 184, 0.34) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    inset 0 -1px 0 rgba(15, 23, 42, 0.04) !important;
}

.p3-mode-row .p3-mode-switch::before {
  content: "" !important;
  position: absolute !important;
  z-index: 0 !important;
  top: var(--p3-switch-pad) !important;
  bottom: var(--p3-switch-pad) !important;
  left: var(--p3-switch-pad) !important;
  width: calc((100% - (var(--p3-switch-pad) * 2) - var(--p3-switch-gap)) / 2) !important;
  border-radius: 12px !important;
  background:
    linear-gradient(135deg, #0ea5e9 0%, #14b8a6 100%) !important;
  border: 1px solid rgba(255, 255, 255, 0.36) !important;
  box-shadow:
    0 10px 22px rgba(14, 165, 233, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
  transform: translateX(0) !important;
  transition:
    transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1),
    background 220ms ease,
    box-shadow 220ms ease !important;
}

.p3-mode-row .p3-mode-switch.high-intensity::before {
  background:
    linear-gradient(135deg, #f97316 0%, #ef4444 100%) !important;
  box-shadow:
    0 10px 22px rgba(239, 68, 68, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
  transform: translateX(calc(100% + var(--p3-switch-gap))) !important;
}

.p3-mode-row .p3-mode-option {
  min-height: 46px !important;
  border-radius: 12px !important;
  background: transparent !important;
  color: #64748b !important;
  font-size: 15px !important;
  font-weight: 820 !important;
  letter-spacing: 0 !important;
  transition:
    color 180ms ease,
    transform 180ms ease,
    background 180ms ease !important;
}

.p3-mode-row .p3-mode-option:hover,
.p3-mode-row .p3-mode-option:focus-visible {
  background: rgba(255, 255, 255, 0.48) !important;
  color: #0f172a !important;
  outline: none !important;
}

.p3-mode-row .p3-mode-option.active {
  background: transparent !important;
  color: #ffffff !important;
  box-shadow: none !important;
  transform: translateY(-1px) !important;
}

body.theme-dark .p3-mode-row .p3-mode-switch {
  background:
    linear-gradient(180deg, rgba(11, 20, 31, 0.94), rgba(7, 13, 22, 0.98)) !important;
  border-color: rgba(125, 211, 252, 0.2) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 0 0 1px rgba(15, 23, 42, 0.22) !important;
}

body.theme-dark .p3-mode-row .p3-mode-switch::before {
