/* =====================================================================
   BATCH 2 — record circle stability + calmer recording motion
   ===================================================================== */

/* Record circle stays centred in the pane; the runtime status lines live in a
   fixed-height zone pinned BELOW it (out of flow), so toggling them never
   shoves the circle around. */
.practice-panel .recorder-pane {
  grid-template-rows: auto minmax(0, 1fr) !important;
  padding-bottom: calc(16px + clamp(108px, 15vh, 150px) + 8px) !important;
}
.recorder-pane .record-row {
  align-self: center !important;
}
.recorder-status-zone {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  height: clamp(108px, 15vh, 150px);
  padding-bottom: 4px;
  overflow-y: auto;
  scrollbar-width: thin;
}
/* The zone owns spacing via gap; drop the children's own large margins /
   min-heights so the live status line never gets clipped at the bottom. */
.recorder-status-zone > .record-status,
.recorder-status-zone > .dictation-status,
.recorder-status-zone > .realtime-pcm-status {
  margin: 0 !important;
  min-height: 0 !important;
}
.recorder-status-zone > .hidden {
  display: none;
}
.recorder-status-zone #candidateAudio {
  width: 100%;
}

/* Replace the cheap, harsh expanding "炫光" halo on the big record circle with
   a calm breathing motion and a soft, steady shadow. Later @keyframes of the
   same name override the earlier ones. */
@keyframes recordPulse {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 14px 30px rgba(15, 23, 42, 0.22);
  }
  50% {
    transform: scale(1.018);
    box-shadow: 0 18px 38px rgba(15, 23, 42, 0.28);
  }
}
@keyframes btnPulse {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 14px 30px rgba(217, 119, 6, 0.24);
  }
  50% {
    transform: scale(1.012);
    box-shadow: 0 16px 34px rgba(217, 119, 6, 0.32);
  }
}
@media (prefers-reduced-motion: reduce) {
  .record-control.recording,
  .record-control.processing,
  .record-control.scoring {
    animation: none !important;
  }
}

/* =====================================================================
   Voice answer: keep the main record circle optically centred.
   The exit control floats independently, and the status copy below stays
   compact so the card does not feel bottom-heavy.
   ===================================================================== */
.practice-panel .recorder-pane {
  --voice-status-height: clamp(76px, 10vh, 104px);
  padding-bottom: calc(14px + var(--voice-status-height)) !important;
}
.practice-panel .recorder-pane .record-row {
  width: 100% !important;
  display: grid !important;
  place-items: center !important;
  align-self: center !important;
  justify-self: stretch !important;
  gap: 0 !important;
}
.practice-panel .recorder-pane .record-control {
  justify-self: center !important;
  margin-inline: auto !important;
}
.practice-panel .recorder-pane .icon-exit-button {
  right: 12px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  z-index: 2 !important;
}
.practice-panel .recorder-pane .icon-exit-button:active {
  transform: translateY(-50%) scale(0.94) !important;
}
.practice-panel .recorder-status-zone {
  height: var(--voice-status-height) !important;
  bottom: 12px !important;
  gap: 4px !important;
  justify-content: flex-start !important;
  padding-bottom: 0 !important;
}
.practice-panel .recorder-status-zone > .record-status,
.practice-panel .recorder-status-zone > .dictation-status,
.practice-panel .recorder-status-zone > .realtime-pcm-status {
  max-width: min(520px, 100%) !important;
  line-height: 1.32 !important;
  text-align: center !important;
}
@media (max-width: 720px) {
  .practice-panel .recorder-pane {
    --voice-status-height: 82px;
  }
  .practice-panel .recorder-pane .icon-exit-button {
    right: 6px !important;
  }
}

