/* =====================================================================
   Exam-practice cluster — Mock heads the group, P1/P2/P3 are its parts.
   A bordered card with the full-mock lead on top and a color-coded
   segmented trio beneath, connected by a divider to read as a hierarchy.
   ===================================================================== */
.nav-exam-group {
  display: grid;
  gap: 5px;
  padding: 6px;
  border: 1px solid rgba(127, 140, 141, 0.22);
  border-radius: 14px;
  background: rgba(127, 140, 141, 0.06);
  min-width: 0;
}
.nav-exam-group .nav-button {
  border: 1px solid transparent;
}
.nav-exam-group .nav-button:hover {
  background: rgba(127, 140, 141, 0.12);
}

/* Lead — the full mock */
.nav-exam-group .nav-exam-lead {
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 1px;
  min-height: 42px;
  padding: 5px 12px;
  border-radius: 10px;
}
.nav-exam-lead-title {
  font-size: 15px;
  font-weight: 820;
  letter-spacing: 0.03em;
  line-height: 1.1;
}
.nav-exam-lead-sub {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  opacity: 0.62;
  line-height: 1;
}
/* Inactive labels inherit the theme's nav text colour (.nav-button sets ink on
   light navs, light on the dark nav), so they stay legible in every theme —
   no hardcoded colour here. */
.nav-exam-group .nav-exam-lead.active {
  background: var(--tone-mock-bg);
  border-color: var(--tone-mock-border);
}
