  border-color: color-mix(in srgb, var(--tone-mock-border) 40%, transparent);
}

/* Parts — P1 / P2 / P3 segmented row, divided from the lead */
.nav-exam-group .nav-pgroup {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  min-width: 0;
  margin-top: 1px;
  padding-top: 7px;
