/* ════════════════════════════════════════════════════════════════════
   Spelling drill — style-only refinement (2026-06-23).
   Appearance ONLY: resting surface fills + accent gradients. No motion,
   no transitions, no transforms, no hover-lift, no shadow tricks, no
   layout — strictly how the surfaces look at rest. The card geometry
   above stays hard-locked and untouched.
   ════════════════════════════════════════════════════════════════════ */

/* Answer input — a faintly accent-tinted resting fill so it reads as the
   focal field (border weight and size unchanged). */
.spelling-drill-panel .nr-input {
  background: color-mix(in srgb, var(--sd-card) 94%, var(--sd-accent)) !important;
  border-color: color-mix(in srgb, var(--sd-accent) 30%, var(--sd-line)) !important;
}

/* Progress fill — a soft left-to-right sheen across the accent. */
.spelling-drill-panel .nr-progress-fill {
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--sd-accent) 72%, #fff),
    var(--sd-accent)) !important;
}

/* Primary action ("下一题") — a top-lit accent gradient for a
   more finished fill; existing white label is kept. */
.spelling-drill-panel .nr-btn-primary {
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--sd-accent) 90%, #fff),
    var(--sd-accent)) !important;
  border-color: color-mix(in srgb, var(--sd-accent) 64%, #000) !important;
}

/* Active scope pill — same accent gradient so the toggle matches the action. */
.spelling-drill-panel .spelling-scope-switch button.is-active {
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--sd-accent) 90%, #fff),
    var(--sd-accent)) !important;
}

/* Final authority: P1/P3 intensity switches and the P1 pressure header effect.
   Kept at EOF because earlier historical switch blocks are numerous and broad. */
.exam-actions .p1-mode-switch,
.p3-mode-row .p3-mode-switch {
  --p3-switch-pad: 6px;
  --p3-switch-gap: 6px;
  isolation: isolate;
  position: relative !important;
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: var(--p3-switch-gap) !important;
  padding: var(--p3-switch-pad) !important;
  overflow: hidden !important;
  border-radius: 16px !important;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(248, 250, 252, 0.94)) !important;
  border: 1px solid rgba(148, 163, 184, 0.34) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    inset 0 -1px 0 rgba(15, 23, 42, 0.04) !important;
}

.exam-actions .p1-mode-switch {
  --p3-switch-pad: 5px;
  --p3-switch-gap: 5px;
  width: 214px !important;
  min-width: 214px !important;
  max-width: 214px !important;
  flex: 0 0 auto !important;
  transition:
    width 260ms ease,
    min-width 260ms ease,
    max-width 260ms ease,
    opacity 220ms ease,
    transform 220ms ease,
    margin 220ms ease,
    padding 220ms ease !important;
}

.exam-actions .p1-mode-switch.hidden {
  display: none !important;
}

.exam-actions .p1-mode-help {
  --p1-help-opacity: 0.78;
  flex: 0 0 auto !important;
  max-width: 112px !important;
  color: color-mix(in srgb, var(--muted) 86%, transparent) !important;
  font-size: 12px !important;
  font-weight: 760 !important;
  line-height: 1.2 !important;
  letter-spacing: 0 !important;
  white-space: nowrap !important;
  opacity: var(--p1-help-opacity) !important;
  transform: translateY(0) !important;
  will-change: opacity, transform, color, text-shadow, filter !important;
  transition:
    max-width 240ms ease,
    opacity 260ms ease,
    color 520ms ease,
    text-shadow 520ms ease,
    filter 320ms ease,
    transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1),
    margin 220ms ease !important;
}

.exam-actions .p1-mode-help.hidden {
  display: none !important;
}

.exam-actions .p1-mode-help.is-high {
  --p1-help-opacity: 0.96;
  color: color-mix(in srgb, #fecaca 82%, #ffffff) !important;
  text-shadow: 0 1px 8px rgba(15, 23, 42, 0.28) !important;
}

.exam-actions .p1-mode-help.is-switching {
  opacity: 0.24 !important;
  transform: translateY(2px) scale(0.985) !important;
  filter: brightness(1.18) saturate(1.2) !important;
  text-shadow: 0 0 14px rgba(34, 211, 238, 0.22) !important;
}

.exam-actions .p1-mode-help.is-entering {
  animation: p1ModeHelpGlowIn 320ms cubic-bezier(0.2, 0.8, 0.2, 1) both !important;
}

@keyframes p1ModeHelpGlowIn {
  from {
    opacity: 0.34;
    transform: translateY(-2px) scale(0.985);
    filter: brightness(1.45) saturate(1.28);
    text-shadow: 0 0 18px rgba(45, 212, 191, 0.34);
  }
  64% {
    opacity: 1;
    filter: brightness(1.22) saturate(1.14);
  }
  to {
    opacity: var(--p1-help-opacity);
    transform: translateY(0) scale(1);
    filter: brightness(1) saturate(1);
  }
}

.practice-panel.p1-started .p1-mode-help,
