.exam-status.pressure-header-shell {
  isolation: isolate !important;
  overflow: visible !important;
  margin: -18px -18px 0 !important;
  padding: 18px 18px 8px !important;
  width: calc(100% + 36px) !important;
  height: 82px !important;
  min-height: 82px !important;
  border-radius: 12px 12px 0 0 !important;
  border-bottom-color: color-mix(in srgb, var(--accent) 28%, var(--line)) !important;
  background-color: transparent !important;
  transition:
    background-color 620ms ease,
    border-color 520ms ease,
    box-shadow 520ms ease !important;
  box-shadow: none !important;
}

.exam-status.p1-pixel-flow {
  isolation: isolate !important;
  /* Pressure-header-shell makes the background transparent, so in LIGHT theme the
     page bleeds through the canvas's 2px grid gaps and turns the pixel-flow grey —
     which is why light pressure mode looked different from dark. Lay a solid dark
     backdrop (same in both themes) so the pixel grid always renders on dark, exactly
     like dark mode. The backdrop is gated on .p1-pixel-flow-visible (below) with the
     transition living HERE on the persistent class, so it FADES out instead of
     snapping when the flow ends. */
  transition: background-color 1180ms ease !important;
}

.exam-status.p1-pixel-flow.p1-pixel-flow-visible {
  background-color: #0a1322 !important;
}

.exam-status.p1-pixel-flow .p2-pixel-flow-canvas {
  top: 0 !important;
  right: auto !important;
  bottom: auto !important;
  left: 0 !important;
  z-index: 1 !important;
  opacity: 0 !important;
  width: 100% !important;
  height: 100% !important;
  inline-size: 100% !important;
  block-size: 100% !important;
  image-rendering: pixelated;
  filter: saturate(2.15) brightness(1.95) contrast(1.18);
  transition: opacity 1180ms ease !important;
  /* The header keeps overflow:visible (for floating bits), so the rectangular
     canvas corner pokes past the rounded top corners. Round the canvas itself to
     the header's radius so no stray pixel escapes the corner. */
  border-radius: 12px 12px 0 0 !important;
}

.exam-status.p1-pixel-flow.p1-pixel-flow-visible .p2-pixel-flow-canvas {
  opacity: 1 !important;
  animation: p1PixelFlowIgnite 3000ms linear both !important;
}

.exam-status.p1-pixel-flow::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: 2 !important;
  pointer-events: none !important;
  opacity: 0 !important;
