/* ── Final: Brainstorm-only pixel-flow parity + compact report filters (2026-06-30)
   Mirror the proven P1/P3 pressure-mode pixel treatment, but scope it only to
   the P2 Brainstorm header. Do not touch the P1/P3 selectors here. */
.p2-brainstorm-entry-card[data-category="brainstorm"] > header {
  background-color: #0a1322 !important;
  background-image: none !important;
  transition: background-color 1180ms ease !important;
}

.p2-brainstorm-entry-card[data-category="brainstorm"] > header::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(90deg, rgba(8, 14, 24, 0.32), rgba(8, 14, 24, 0.02) 46%, rgba(8, 14, 24, 0.26)),
    linear-gradient(180deg, rgba(8, 14, 24, 0.12), rgba(8, 14, 24, 0.24)),
    rgba(6, 16, 28, 0.36);
  opacity: 1;
}

.p2-brainstorm-head-field::before {
  display: none !important;
}

.p2-brainstorm-head-field .p2-pixel-flow-canvas {
  opacity: 1 !important;
  filter: saturate(2.15) brightness(1.95) contrast(1.18) !important;
  animation: p1PixelFlowIgnite 3000ms linear both !important;
  image-rendering: pixelated;
}

@keyframes p2BrainstormPixelFlowIgniteLight {
  0% {
    filter: saturate(1.85) brightness(1.34) contrast(1.08);
  }
  33.33% {
    filter: saturate(4.2) brightness(4.45) contrast(1.42);
  }
  48% {
    filter: saturate(3.35) brightness(3.18) contrast(1.34);
  }
  66% {
    filter: saturate(3.05) brightness(2.86) contrast(1.3);
  }
  84% {
    filter: saturate(2.9) brightness(2.7) contrast(1.28);
  }
  100% {
    filter: saturate(2.82) brightness(2.62) contrast(1.26);
  }
}

