  min-height: 42px;
  box-sizing: border-box;
  display: inline-grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 48%, var(--line));
  border-radius: 50%;
  color: var(--accent);
  background: color-mix(in srgb, var(--panel) 82%, var(--accent) 18%);
}

.writing-custom-add-icon svg,
.writing-custom-prompt-menu-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
}

.writing-custom-prompt-choice {
  position: relative;
  overflow: visible;
}

.writing-custom-prompt-choice .writing-prompt-choice-body {
  min-width: 0;
}

.writing-custom-prompt-choice .writing-prompt-preview {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  line-height: 1.55;
}

.writing-custom-prompt-choice .writing-prompt-preview > :first-child { margin-top: 0; }
.writing-custom-prompt-choice .writing-prompt-preview > :last-child { margin-bottom: 0; }

.writing-custom-prompt-choice .writing-prompt-choice-main {
  width: 100%;
  min-height: inherit;
  padding: inherit;
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  text-align: left;
}

.writing-custom-prompt-menu-wrap {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 8;
}

.writing-custom-prompt-menu-button {
  width: 32px;
  height: 32px;
  min-width: 32px;
  min-height: 32px;
  box-sizing: border-box;
  padding: 0;
  display: inline-grid;
  place-items: center;
  border-radius: 6px;
}

.writing-custom-prompt-menu-button svg {
  fill: currentColor;
  stroke: none;
}

.writing-custom-prompt-menu {
  top: 38px;
  right: 0;
  z-index: 90;
  min-width: 112px;
}

.custom-writing-prompt-card {
  width: min(760px, calc(100vw - 32px));
  max-height: min(820px, calc(100vh - 36px));
  overflow: auto;
}

.custom-writing-prompt-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.custom-writing-prompt-form {
  display: grid;
  gap: 16px;
  padding: 18px 22px 22px;
}

.custom-writing-prompt-meta-row {
  display: grid;
  grid-template-columns: minmax(150px, .7fr) minmax(260px, 1.3fr);
  gap: 14px;
}

.custom-writing-prompt-form label {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.custom-writing-prompt-form label small {
  font-weight: 500;
  opacity: .72;
}

.custom-writing-prompt-form input,
.custom-writing-prompt-form select {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--panel);
  color: var(--ink);
  padding: 0 12px;
}

.custom-writing-prompt-editor-label .corpus-markdown-editor-frame,
.custom-writing-prompt-editor-label textarea {
  min-height: 300px;
}

.custom-writing-prompt-error {
  min-height: 18px;
  margin: 0;
  color: var(--danger);
  font-size: 13px;
}

.custom-writing-prompt-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

body.theme-dark .writing-custom-add-card,
body.theme-dark .custom-writing-prompt-card {
  background: color-mix(in srgb, var(--panel) 94%, #000 6%);
}

@media (max-width: 680px) {
  .custom-writing-prompt-meta-row { grid-template-columns: 1fr; }
  .custom-writing-prompt-form { padding: 14px; }
  .custom-writing-prompt-editor-label .corpus-markdown-editor-frame,
  .custom-writing-prompt-editor-label textarea { min-height: 250px; }
}

/* ── Custom practice picker: clean cards, unified with the bank cards ── */

/* Add card: same body rhythm as a bank Task 2 card, dashed to signal "new". */
.writing-custom-add-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 210px;
  border: 1.5px dashed color-mix(in srgb, var(--accent) 42%, var(--line));
  border-radius: var(--radius-lg);
  background: color-mix(in srgb, var(--accent) 4%, var(--panel));
  text-align: left;
  transition: border-color var(--motion-fast), background var(--motion-fast), box-shadow var(--motion-fast), transform var(--motion-fast);
}

.writing-custom-add-card:hover {
  border-color: color-mix(in srgb, var(--accent) 78%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
  box-shadow: 0 8px 22px color-mix(in srgb, var(--accent) 14%, transparent);
}

.writing-custom-add-card .writing-custom-add-body {
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 8px;
  width: 100%;
  height: 100%;
  padding: 18px 16px;
  background: transparent;
  text-align: center;
}

.writing-custom-add-icon {
  width: 32px;
  height: 32px;
  min-width: 32px;
  min-height: 32px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--line));
  border-radius: 9px;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
  color: var(--accent-dark);
  transition: background var(--motion-fast), border-color var(--motion-fast), color var(--motion-fast);
}

.writing-custom-add-card:hover .writing-custom-add-icon {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.writing-custom-add-icon svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
}

.writing-custom-add-titles {
  display: grid;
  gap: 2px;
  justify-items: center;
  min-width: 0;
}

.writing-custom-add-body .writing-custom-add-titles strong {
  color: var(--ink);
  font-size: 15px;
  font-weight: 860;
  line-height: 1.3;
}

.writing-custom-add-body .writing-custom-add-titles small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.writing-custom-add-hint {
  max-width: 260px;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.55;
}

/* Custom prompt cards: same strong → meta → preview rhythm as bank cards. */
.writing-custom-prompt-choice {
  background: var(--panel);
  border-color: var(--line);
  border-radius: var(--radius-lg);
  /* Clip EVERYTHING to the rounded card — no child or pseudo-element (e.g. the
     dark-theme left accent strip) may paint square corners over the radius.
     The dropdown menu escapes only while the card is open. */
  overflow: hidden;
}

.writing-custom-prompt-choice.is-menu-open {
  overflow: visible;
}

.writing-custom-prompt-choice .writing-prompt-choice-body {
  padding: 14px 46px 14px 16px;
  gap: 6px;
  background: transparent;
}

/* Clip the inner content to the card's rounded corners (kebab menu stays
   outside the button, so its dropdown is not clipped). */
.writing-custom-prompt-choice .writing-prompt-choice-main {
  overflow: hidden;
}

/* The kebab blends into the card until hovered — no square patch on the
   rounded corner. */
.writing-custom-prompt-choice .writing-custom-prompt-menu-button {
  border-color: transparent;
  background: transparent;
  color: var(--muted);
}

.writing-custom-prompt-choice .writing-custom-prompt-menu-button:hover,
.writing-custom-prompt-choice.is-menu-open .writing-custom-prompt-menu-button {
  border-color: rgba(100, 116, 139, 0.22);
  background: var(--panel);
  color: var(--ink);
}

.writing-custom-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.writing-custom-meta em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.writing-custom-meta .writing-prompt-status {
  flex: 0 0 auto;
  padding: 3px 8px;
  font-size: 10.5px;
}

.writing-custom-prompt-choice .writing-prompt-preview {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
}

/* Filter chips polish */
.writing-source-filter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 800;
  white-space: nowrap;
  transition: border-color var(--motion-fast), background var(--motion-fast), color var(--motion-fast), box-shadow var(--motion-fast);
}

.writing-source-filter span,
.writing-type-filter span {
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--ink) 7%, transparent);
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  margin-left: 0;
}

.writing-source-filter:hover {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
}

.writing-source-filter.active {
  border-color: var(--accent);
  background: var(--accent);
  color: #fff;
  box-shadow: 0 3px 10px color-mix(in srgb, var(--accent) 32%, transparent);
}

.writing-source-filter.active span {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

.writing-type-filter {
  min-height: 32px;
  padding: 6px 13px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 800;
  white-space: nowrap;
  transition: border-color var(--motion-fast), background var(--motion-fast), color var(--motion-fast);
}

.writing-type-filter:hover {
  border-color: color-mix(in srgb, var(--accent) 50%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
}

.writing-type-filter.active {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
  background: color-mix(in srgb, var(--accent) 11%, var(--panel));
  color: var(--accent-dark);
}

.writing-type-filter.active span {
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  color: var(--accent-dark);
}

.writing-source-filter:focus-visible,
.writing-type-filter:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 24%, transparent);
  outline-offset: 2px;
}

/* Dark theme */
body.theme-dark .writing-custom-add-card {
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
}

body.theme-dark .writing-custom-add-card:hover {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
}

body.theme-dark .writing-custom-add-card .writing-custom-add-body {
  background: transparent;
}

body.theme-dark .writing-custom-prompt-choice,
body.theme-dark .writing-custom-prompt-choice .writing-prompt-choice-body {
  background: var(--panel);
}

/* =====================================================================
   UI POLISH (2026-10-05) — finish and texture only; layout, behaviour and
   the per-theme colour tokens (--accent, --ink, --muted, --line …) stay.
   ===================================================================== */

/* ---------- Corpus landing ---------- */
body:not(.font-popular) #corpusPanel .corpus-home-title {
  font-family: "Noto Serif SC", "Songti SC", "STSong", Georgia, serif;
  font-weight: 800;
  letter-spacing: 0;
}

#corpusPanel .corpus-home-card {
  position: relative;
  min-height: 228px;
  height: auto;
  border-width: 1px;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 16px 40px rgba(49, 59, 73, 0.07);
  transition: transform 200ms ease, box-shadow 200ms ease, border-color 200ms ease;
}

#corpusPanel .corpus-home-card::before {
  width: 3px;
  top: 22px;
  bottom: 22px;
  border-radius: 0 3px 3px 0;
}

#corpusPanel .corpus-home-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 24px 52px rgba(49, 59, 73, 0.11);
}

#corpusPanel .corpus-home-card strong {
  letter-spacing: 0;
}

#corpusPanel .corpus-card-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: max-content;
  padding: 7px 14px;
  font-weight: 700;
  transition: background 200ms ease, color 200ms ease, border-color 200ms ease;
}

#corpusPanel .corpus-card-cta::after {
  content: "→";
  transition: transform 200ms ease;
}

#corpusPanel .corpus-home-card:hover .corpus-card-cta {
  border-color: transparent;
  background: var(--corpus-accent, var(--accent));
  color: #fff;
}

#corpusPanel .corpus-card-p2:hover .corpus-card-cta {
  background: var(--p2-corpus-accent, var(--accent));
}

#corpusPanel .corpus-home-card:hover .corpus-card-cta::after {
  transform: translateX(3px);
}

#corpusPanel .corpus-review-lane {
  border-radius: 20px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03), 0 12px 32px rgba(15, 23, 42, 0.05);
}

#corpusPanel .corpus-review-link {
  transition: background 180ms ease, transform 180ms ease;
}

#corpusPanel .corpus-review-link:hover {
  transform: translateY(-1px);
}

body.theme-dark #corpusPanel .corpus-home-card {
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 18px 44px rgba(0, 0, 0, 0.3);
}

@media (prefers-reduced-motion: reduce) {
  #corpusPanel .corpus-home-card,
  #corpusPanel .corpus-review-link {
    transition: none;
  }
}

/* Narrow screens: the review lane stacked its head beside three 54px columns
   (text ran vertically). Stack the head above, links share the full width. */
@media (max-width: 900px) {
  .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-review-lane {
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 14px;
  }

  .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-review-links {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }
}

@media (max-width: 480px) {
  .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-review-links {
    grid-template-columns: minmax(0, 1fr) !important;
  }
}

/* The draggable sidebar writes --sidebar-width inline on <html>, which beat the
   980px breakpoint's 0px and left a 176px blank strip once the nav moved to the
   top bar. !important in the stylesheet outranks a non-important inline value. */
@media (max-width: 980px) {
  html {
    --sidebar-width: 0px !important;
  }
}

/* ≤980px the nav carries its own avatar (.nav-user-mobile); hide the floating
   top-bar copy so the account button is not shown twice. */
@media (max-width: 980px) {
  .global-topbar-actions > .avatar-settings-button {
    display: none !important;
  }
}

/* ---------- Writing report: AI coaching rewrites ----------
   "original → better" pairs were grey monospace boxes; read them as text:
   the original quietly struck through, the suggestion tinted with the accent. */
.coaching-content li > code {
  padding: 1px 7px;
  border: 0;
  border-radius: 6px;
  font-family: inherit;
  font-size: 0.95em;
  line-height: 1.7;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.coaching-content li > code:first-child {
  background: color-mix(in srgb, var(--muted) 10%, transparent);
  color: color-mix(in srgb, var(--ink) 62%, transparent);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--danger) 55%, transparent);
  text-decoration-thickness: 1px;
}

.coaching-content li > code:nth-of-type(2) {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent-dark);
  font-weight: 600;
}

body.theme-dark .coaching-content li > code:nth-of-type(2) {
  color: var(--accent);
}

.coaching-content li + li {
  margin-top: 4px;
}

/* Corpus cards: earlier rules pin height with !important at :has(#corpusPanel)
   specificity; match it so the cards size to their content. */
.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-card-p1,
.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-card-p2 {
  height: auto !important;
  min-height: 228px !important;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-home-card {
  border-width: 1px;
  border-radius: 20px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 16px 40px rgba(49, 59, 73, 0.07) !important;
}

.workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-home-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 24px 52px rgba(49, 59, 73, 0.11) !important;
}

body.theme-dark .workspace.corpus-workspace:has(#corpusPanel:not(.hidden)) #corpusPanel .corpus-home-card {
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 18px 44px rgba(0, 0, 0, 0.3) !important;
}

