}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell {
  position: relative;
  padding: 2px 22px 24px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell:first-child {
  padding-left: 0 !important;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell + .score-cell {
  border-left: 1px solid var(--line) !important;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell.has-meter:hover {
  transform: none;
  box-shadow: none !important;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell span {
  color: var(--muted) !important;
  font-family: var(--ed-mono) !important;
  font-size: 11.5px !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell span small {
  font-family: var(--ed-sans);
  letter-spacing: 0;
  text-transform: none;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell strong {
  display: block;
  margin-top: 8px;
  color: var(--ink) !important;
  font-family: var(--ed-serif) !important;
  font-size: 44px !important;
  font-weight: 400 !important;
  line-height: 1;
  text-align: left !important;
}

:is(.speaking-score-summary-grid, .writing-score-summary-grid) .score-cell.has-meter::after {
