/* shared sketch parts */
#corpusPanel .cca text {
  fill: var(--muted);
  font-family: var(--ed-mono);
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: middle;
}

#corpusPanel .cca .cca-tag {
  font-size: 9.5px;
  letter-spacing: 0.08em;
  text-anchor: start;
  text-transform: uppercase;
}

#corpusPanel .cca-sheet {
  fill: var(--panel);
  stroke: var(--line);
  stroke-width: 1;
}

#corpusPanel .cca :is(.cca-lines rect, .cca-bullets rect) {
  fill: color-mix(in srgb, var(--ink) 13%, transparent);
}

/* P1: a topic gets picked, its short answer writes itself out, then you speak it */
#corpusPanel .cca-chip {
  fill: none;
  stroke: var(--line);
}

#corpusPanel .cca-hl {
  fill: color-mix(in srgb, var(--accent) 12%, transparent);
  stroke: var(--accent);
  animation: cca-pick 7.2s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}

#corpusPanel .cca-link {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.5;
  stroke-dasharray: 3 4;
  animation: cca-flow 1.2s linear infinite;
}

#corpusPanel .cca-lines rect {
  transform-box: fill-box;
  transform-origin: left center;
  animation: cca-type 2.4s ease-out infinite;
}

#corpusPanel .cca-lines .l2 { animation-delay: 0.15s; }
#corpusPanel .cca-lines .l3 { animation-delay: 0.3s; }
#corpusPanel .cca-lines .l4 { animation-delay: 0.45s; }

#corpusPanel .cca-wave rect {
  fill: var(--accent);
  transform-box: fill-box;
  transform-origin: center;
  animation: cca-wave 1.1s ease-in-out infinite;
}

#corpusPanel .cca-wave rect:nth-child(2) { animation-delay: -0.9s; }
#corpusPanel .cca-wave rect:nth-child(3) { animation-delay: -0.3s; }
#corpusPanel .cca-wave rect:nth-child(4) { animation-delay: -0.7s; }
#corpusPanel .cca-wave rect:nth-child(5) { animation-delay: -0.1s; }
#corpusPanel .cca-wave rect:nth-child(6) { animation-delay: -0.5s; }
#corpusPanel .cca-wave rect:nth-child(7) { animation-delay: -0.8s; }

#corpusPanel .cca-mic {
  fill: var(--accent);
  transform-box: fill-box;
  transform-origin: center;
  animation: cca-pulse 2.4s ease-out infinite;
}

@keyframes cca-pick {
  0%, 28% { transform: translateY(0); }
  33%, 61% { transform: translateY(42px); }
  66%, 94% { transform: translateY(84px); }
  100% { transform: translateY(0); }
}

@keyframes cca-flow {
  to { stroke-dashoffset: -14; }
}

@keyframes cca-type {
  0%, 8% { transform: scaleX(0); opacity: 0.3; }
  40%, 88% { transform: scaleX(1); opacity: 1; }
  100% { transform: scaleX(1); opacity: 0; }
}

@keyframes cca-wave {
  0%, 100% { transform: scaleY(0.25); }
  50% { transform: scaleY(1); }
}

@keyframes cca-pulse {
  0% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.75; transform: scale(0.88); }
  100% { opacity: 1; transform: scale(1); }
}

/* P2: one cue card branches into the P3 follow-ups it can answer */
#corpusPanel .cca-bar {
  fill: color-mix(in srgb, var(--ink) 55%, transparent);
}

#corpusPanel .cca-bullets circle {
  fill: var(--accent);
}

#corpusPanel .cca-branches path {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-dasharray: 90;
  stroke-dashoffset: 90;
}

#corpusPanel .cca-branches .b1 { animation: cca-draw-1 6s ease-in-out infinite; }
#corpusPanel .cca-branches .b2 { animation: cca-draw-2 6s ease-in-out infinite; }
#corpusPanel .cca-branches .b3 { animation: cca-draw-3 6s ease-in-out infinite; }

#corpusPanel .cca-q {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: left center;
}

#corpusPanel .cca-q rect {
  fill: color-mix(in srgb, var(--accent) 9%, var(--panel));
  stroke: var(--accent);
}

#corpusPanel .cca-q text {
  fill: var(--accent);
}

#corpusPanel .cca-q.q1 { animation: cca-pop-1 6s cubic-bezier(0.34, 1.56, 0.64, 1) infinite; }
#corpusPanel .cca-q.q2 { animation: cca-pop-2 6s cubic-bezier(0.34, 1.56, 0.64, 1) infinite; }
#corpusPanel .cca-q.q3 { animation: cca-pop-3 6s cubic-bezier(0.34, 1.56, 0.64, 1) infinite; }

@keyframes cca-draw-1 { 0%, 4% { stroke-dashoffset: 90; opacity: 1; } 16%, 86% { stroke-dashoffset: 0; opacity: 1; } 96%, 100% { stroke-dashoffset: 0; opacity: 0; } }
@keyframes cca-draw-2 { 0%, 22% { stroke-dashoffset: 90; opacity: 1; } 34%, 86% { stroke-dashoffset: 0; opacity: 1; } 96%, 100% { stroke-dashoffset: 0; opacity: 0; } }
@keyframes cca-draw-3 { 0%, 40% { stroke-dashoffset: 90; opacity: 1; } 52%, 86% { stroke-dashoffset: 0; opacity: 1; } 96%, 100% { stroke-dashoffset: 0; opacity: 0; } }
@keyframes cca-pop-1 { 0%, 15% { opacity: 0; transform: scale(0.6); } 21%, 86% { opacity: 1; transform: scale(1); } 96%, 100% { opacity: 0; transform: scale(1); } }
@keyframes cca-pop-2 { 0%, 33% { opacity: 0; transform: scale(0.6); } 39%, 86% { opacity: 1; transform: scale(1); } 96%, 100% { opacity: 0; transform: scale(1); } }
@keyframes cca-pop-3 { 0%, 51% { opacity: 0; transform: scale(0.6); } 57%, 86% { opacity: 1; transform: scale(1); } 96%, 100% { opacity: 0; transform: scale(1); } }

@media (prefers-reduced-motion: reduce) {
  #corpusPanel .cca * {
    animation: none !important;
  }

  #corpusPanel .cca-branches path {
    stroke-dashoffset: 0;
  }

