body:not(#_):not(#__) .history-item:is(.tone-p1, .tone-p2, .tone-p3, .tone-mock) .history-item-band {
  color: color-mix(in srgb, var(--rail-tone) 62%, #fff) !important;
}

body:not(#_):not(#__) .history-item.active {
  border-color: color-mix(in srgb, var(--rail-tone, var(--ink)) 45%, var(--line)) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--rail-tone, var(--ink)) 45%, var(--line)) !important;
}

body.theme-dark:not(#_):not(#__) .history-item:is(.tone-p1, .tone-p2, .tone-p3, .tone-mock) :is(.history-item-tag, .history-item-band) {
  color: color-mix(in srgb, var(--rail-tone) 55%, #fff) !important;
}

body.theme-dark:not(#_):not(#__) .history-item:is(.tone-p1, .tone-p2, .tone-p3, .tone-mock) .history-item-tag {
  background: color-mix(in srgb, var(--rail-tone) 16%, transparent) !important;
}

body:not(#_):not(#__) .history-item:is(.tone-p1, .tone-p2, .tone-p3, .tone-mock) .history-item-band .history-item-band-value {
  color: color-mix(in srgb, var(--rail-tone) 62%, #fff) !important;
}

body.theme-dark:not(#_):not(#__) .history-item:is(.tone-p1, .tone-p2, .tone-p3, .tone-mock) .history-item-band .history-item-band-value {
  color: color-mix(in srgb, var(--rail-tone) 55%, #fff) !important;
}

/* =====================================================================
   MOCK INTERVIEW (desktop only) — mode switcher + interview workspace.
   Same editorial language as the home dashboard: mono kickers with gold
   rules, serif display type, hairline-ruled cards, pill actions.
   ===================================================================== */

/* ---------- Mode switcher: the brand grows into a card in place (detail.design corner morph) ---------- */
.studio-mode-control { position: relative; width: 100%; min-width: 0; }
.studio-mode-control.hidden { display: none !important; }
.nav-top-left:has(.studio-mode-control:not(.hidden)) > .brand { display: none !important; }

.studio-mode-control {
  /* --switch-surface / --switch-ink are read from the sidebar at runtime (interview.js syncSwitchPalette). */
  --switch-surface: #171717;
  --switch-ink: #eef5f3;
  /* Lighter than the rail it grows out of, so the card reads on a near-black sidebar. */
  --switch-bg: color-mix(in srgb, var(--switch-surface) 88%, #fff);
  --switch-closed: var(--switch-surface);
  --switch-line: color-mix(in srgb, var(--switch-ink) 12%, transparent);
  --switch-soft: color-mix(in srgb, var(--switch-ink) 7%, transparent);
  --switch-hover: color-mix(in srgb, var(--switch-ink) 6%, var(--switch-surface));
  --switch-shadow: 0 22px 60px rgba(0, 0, 0, 0.42), 0 2px 8px rgba(0, 0, 0, 0.28);
}

.studio-mode-control[data-switch-tone="light"] {
  --switch-bg: color-mix(in srgb, var(--switch-surface) 55%, #fff);
  --switch-shadow: 0 22px 60px rgba(15, 23, 42, 0.16), 0 2px 8px rgba(15, 23, 42, 0.08);
}

.studio-switch-trigger,
.studio-switch-head {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.studio-switch-trigger { color: inherit; }
.studio-switch-head { color: var(--switch-ink); }

body:not(#_) .studio-switch-trigger {
  position: relative;
  width: calc(100% + 8px);
  height: 46px;
  box-sizing: border-box;
  margin: 0 -4px;
  padding: 4px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  box-shadow: none;
  text-align: left;
  cursor: pointer;
}

body:not(#_) .studio-switch-trigger:hover,
body:not(#_) .studio-mode-control.is-open .studio-switch-trigger {
  background: var(--switch-hover);
}

body:not(#_) .studio-switch-trigger:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 70%, transparent);
  outline-offset: 2px;
}

body:not(#_) :is(.studio-switch-trigger, .studio-switch-head) .brand-mark {
  flex: none;
  width: clamp(28px, calc(var(--sidebar-width, 176px) * 0.18), 34px);
  height: auto;
  padding: 0;
  border: 0;
  background: transparent;
}

body:not(#_) :is(.studio-switch-trigger, .studio-switch-head) > span {
  min-width: 0;
  overflow: visible;
  font-family: "Instrument Serif", "Charter", Georgia, serif;
  font-size: clamp(22px, calc(var(--sidebar-width, 176px) * 0.145), 26px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.01em;
  white-space: nowrap;
  text-overflow: clip;
}

body.interview-mode:not(#_) :is(.studio-switch-trigger, .studio-switch-head) > span {
  font-family: var(--ed-serif);
  font-size: clamp(17px, calc(var(--sidebar-width, 176px) * 0.1), 21px);
  letter-spacing: 0.02em;
}

.studio-switch-chevron {
  position: absolute;
  right: 5px;
  top: 50%;
  width: 22px;
  height: 22px;
  padding: 4px;
  box-sizing: border-box;
  border-radius: 7px;
  --chevron-bg: var(--switch-hover);
  background: var(--chevron-bg);
  box-shadow: -12px 0 10px var(--chevron-bg);
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  transform: translateY(-50%);
  transition: opacity 200ms ease;
}

/* The wordmark keeps the full sidebar width at rest; the affordance appears on intent. */
.studio-switch-trigger:is(:hover, :focus-visible) .studio-switch-chevron,
.studio-mode-control.is-open .studio-switch-chevron { opacity: 0.85; }

body:not(#_) .studio-switch-card {
  position: fixed;
  z-index: 1200;
  width: 272px;
  box-sizing: border-box;
  overflow: hidden;
  padding: 0;
  border: 1px solid var(--switch-line);
  border-radius: 18px;
  background: var(--switch-bg);
  box-shadow: var(--switch-shadow);
  color: var(--switch-ink);
  transform-origin: top left;
}

body:not(#_) .studio-switch-card[hidden] { display: none !important; }
body:not(#_) .studio-switch-card[inert] { pointer-events: none; }

body:not(#_) .studio-switch-head,
body:not(#_) .studio-switch-body { width: 270px; box-sizing: border-box; }

body:not(#_) .studio-switch-head {
  /* Same box as the trigger (46px incl. its 1px border, 4px inset) so the brand does not move when the card takes over. */
  height: 44px;
  padding: 4.5px 12px 3.5px 4px; /* a <button> centres half a pixel lower than a <div>; match it exactly */
  box-sizing: border-box;
  border-bottom: 1px solid transparent;
  cursor: pointer;
}

.studio-switch-head kbd {
  margin-left: auto;
  flex: none;
}

.studio-switch-card kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  box-sizing: border-box;
  border-radius: 5px;
  background: color-mix(in srgb, var(--switch-ink) 8%, transparent);
  color: color-mix(in srgb, var(--switch-ink) 62%, transparent);
  font-family: var(--ed-mono);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1;
}

.studio-switch-body { padding: 4px 8px 10px; }

.studio-switch-label {
  margin: 6px 8px 8px;
  color: color-mix(in srgb, var(--switch-ink) 50%, transparent);
  font-family: var(--ed-mono);
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

body:not(#_) .studio-switch-body [role="menuitemradio"] {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 54px;
  margin: 0 0 2px;
  padding: 8px 10px 8px 8px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  box-shadow: none;
  color: var(--switch-ink);
  text-align: left;
  cursor: pointer;
  transition: background-color 160ms ease;
}

body:not(#_) .studio-switch-body [role="menuitemradio"]:is(:hover, :focus-visible) {
  outline: none;
  background: color-mix(in srgb, var(--switch-ink) 7%, transparent);
}

.studio-switch-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--switch-ink) 6%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--switch-ink) 7%, transparent);
}

.studio-switch-icon svg,
.studio-switch-check {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

[role="menuitemradio"][aria-checked="true"] .studio-switch-icon {
  background: color-mix(in srgb, var(--accent) 24%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
  color: color-mix(in srgb, var(--accent) 55%, #fff);
}

.studio-switch-text { display: grid; gap: 3px; min-width: 0; }
.studio-switch-text strong { font-size: 14px; font-weight: 500; line-height: 1.2; }
.studio-switch-text small { overflow: hidden; color: color-mix(in srgb, var(--switch-ink) 55%, transparent); font-size: 12px; line-height: 1.3; white-space: nowrap; text-overflow: ellipsis; }

.studio-switch-check { opacity: 0; color: color-mix(in srgb, var(--accent) 55%, #fff); }
[role="menuitemradio"][aria-checked="true"] .studio-switch-check { opacity: 1; }

/* ---------- Sidebar in interview mode: the IELTS rows step aside, interview rows reuse .nav-button ---------- */
body.interview-mode .nav-primary:not(#interviewNav),
body.interview-mode .nav-secondary,
body.interview-mode #bankStatus,
body.interview-mode .nav-bottom > .nav-divider { display: none !important; }
#interviewNav.hidden { display: none !important; }

.shell .nav .nav-button[data-interview-pane="home"] { --nav-icon: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='black'%20stroke-width='1.8'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d='M3%2010.5%2012%203l9%207.5'/%3E%3Cpath%20d='M5%209.5V20h14V9.5'/%3E%3Cpath%20d='M10%2020v-5h4v5'/%3E%3C/svg%3E"); }
