.shell .nav .nav-button[data-interview-pane="custom"] { --nav-icon: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='black'%20stroke-width='1.8'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d='M14%203H6a1%201%200%200%200-1%201v16a1%201%200%200%200%201%201h12a1%201%200%200%200%201-1V8z'/%3E%3Cpath%20d='M14%203v5h5'/%3E%3Ccircle%20cx='12'%20cy='12.5'%20r='2'/%3E%3Cpath%20d='M8.5%2018a3.5%203.5%200%200%201%207%200'/%3E%3C/svg%3E"); }
