/* ---------- Page chrome ---------- */
/* Like the IELTS practice pages: the window does not scroll. Headings, filters and action docks stay put;
   each pane names one region that scrolls (the question list, the records, the transcript…). */
body:not(#_) .workspace:has(#interviewPanel:not(.hidden)) {
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
}

body:not(#_) .workspace:has(#interviewPanel:not(.hidden)) > .topbar { flex: none; margin-bottom: 0; }

body:not(#_) #interviewPanel:not(.hidden) {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: auto;
  overflow: hidden;
}

#interviewPanel .iv-pane { flex: 1 1 auto; display: flex; flex-direction: column; min-height: 0; }
#interviewPanel .iv-pane > * { flex: none; }

/* Scroll regions: home, report and corpus scroll as a whole pane; practice keeps its header and
   scrolls inside each column; reports scroll the list; tailored scrolls each sheet. */
#interviewPanel :is(.iv-pane--home, .iv-pane--corpus) { overflow-y: auto; overscroll-behavior: contain; }

/* Resume / JD: the #writingPanel shell (aliased); the switch sits above it instead of in the top bar. */
#interviewPanel .iv-pane > #interviewCustom { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: 12px; }
#interviewCustom > .writing-shell { flex: 1 1 auto; min-height: 0; }
#interviewCustom .writing-checkin-top { min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
/* The editor card fills the shell height and the textarea takes what the prompt card leaves. */
body:not(#_) #interviewCustom .writing-editor-card { height: 100%; min-height: 0; grid-template-rows: auto auto minmax(0, 1fr); overflow: hidden; }
/* Only the two cards are surfaces; the section around them (and the switch row) stays page-coloured. */
body:not(#_):not(#__) #interviewCustom { border: 0; border-radius: 0; background: transparent; box-shadow: none; }
body:not(#_) #interviewCustom .writing-answer { height: 100% !important; min-height: 140px !important; }
#interviewCustom .iv-custom-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; }
#interviewCustom .iv-custom-bar p { color: var(--muted); font-size: 13px; }
#interviewCustom .iv-custom-switch { width: 220px; }
#interviewCustom .iv-file-pick { position: relative; cursor: pointer; }
#interviewCustom .iv-file-pick input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
#interviewCustom .iv-custom-list { display: grid; gap: 6px; margin-top: 10px; padding: 0; list-style: none; }
#interviewCustom .iv-custom-list li { padding: 8px 12px; border-radius: 8px; background: color-mix(in srgb, var(--ink) 4%, transparent); font-size: 14px; }
#interviewCustom .iv-custom-role { margin-top: 10px; font-weight: 600; }
#interviewCustom .iv-custom-empty { margin-top: 10px; color: var(--muted); font-size: 13.5px; line-height: 1.6; }

body.interview-bare:has(#interviewPanel:not(.hidden)) .topbar,
body.interview-bare:has(#interviewPanel:not(.hidden)) #viewTitleBlock { display: none !important; }
body[data-interview-pane]:has(#interviewPanel:not(.hidden)) { --ed-eyebrow: "Interview"; }
body.interview-mode[data-interview-pane="practice"][data-interview-part="full"]:has(#practicePanel:not(.hidden)) { --ed-eyebrow: "Interview · Mock"; }
body.interview-mode[data-interview-pane="practice"][data-interview-part="project"]:has(#practicePanel:not(.hidden)) { --ed-eyebrow: "Interview · Projects"; }
body.interview-mode[data-interview-pane="practice"][data-interview-part="knowledge"]:has(#practicePanel:not(.hidden)) { --ed-eyebrow: "Interview · Knowledge"; }
body.interview-mode[data-interview-pane="practice"][data-interview-part="reverse"]:has(#practicePanel:not(.hidden)) { --ed-eyebrow: "Interview · Your questions"; }
body[data-interview-pane="reports"]:has(#interviewPanel:not(.hidden)) { --ed-eyebrow: "Interview · Reports"; }
body[data-interview-pane="custom"]:has(#interviewPanel:not(.hidden)) { --ed-eyebrow: "Interview · Tailored"; }
body[data-interview-pane="assistant"]:has(#interviewPanel:not(.hidden)) { --ed-eyebrow: "Interview · Assistant"; }

body:not(#_) #interviewPanel {
  --iv-rule: var(--line);
  --iv-card: var(--panel);
  --iv-link: var(--accent);
  width: min(100%, 1320px);
  margin: 0 auto;
  padding: 0 0 16px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--ink);
}

body.theme-dark:not(#_) #interviewPanel { --iv-link: color-mix(in srgb, var(--accent) 55%, #fff); }
#interviewPanel.hidden { display: none !important; }
#interviewPanel :is(h2, h3, p, ol, ul, dl, dd) { margin: 0; }
#interviewPanel :is(ol, ul) { padding: 0; list-style: none; }
#interviewPanel .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

.iv-spinner { width: 12px; height: 12px; border: 1.5px solid color-mix(in srgb, var(--accent) 25%, transparent); border-top-color: var(--accent); border-radius: 50%; animation: ivSpin 700ms linear infinite; }
@keyframes ivSpin { to { transform: rotate(360deg); } }

/* Kickers / eyebrows */
#interviewPanel :is(.iv-kicker, .iv-eyebrow) {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--ed-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#interviewPanel .iv-kicker::before,
#interviewPanel .iv-kicker::after,
#interviewPanel .iv-eyebrow::before { content: ""; width: 22px; height: 1px; background: var(--ed-gold); }

/* Buttons */
body:not(#_) #interviewPanel .iv-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 44px;
  padding: 0 20px;
  border: 1px solid color-mix(in srgb, var(--ink) 28%, transparent);
  border-radius: 999px;
  background: transparent;
  box-shadow: none;
  color: var(--ink);
  font-size: 14.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 250ms var(--ed-ease), color 250ms var(--ed-ease), border-color 250ms var(--ed-ease), transform 250ms var(--ed-ease);
}

body:not(#_) #interviewPanel .iv-btn:hover:not(:disabled) { border-color: var(--ink); }
body:not(#_) #interviewPanel .iv-btn:active:not(:disabled) { transform: scale(0.98); }
body:not(#_) #interviewPanel .iv-btn--solid { border-color: var(--ink); background: var(--ink); color: var(--panel); }
body:not(#_) #interviewPanel .iv-btn--solid:hover:not(:disabled) { border-color: var(--accent); background: var(--accent); color: #fff; }
#interviewPanel .iv-arrow { transition: transform 250ms var(--ed-ease); }
#interviewPanel :is(.iv-btn, .iv-link):hover:not(:disabled) .iv-arrow { transform: translateX(3px); }

body:not(#_) #interviewPanel :is(button, a):disabled { opacity: 0.45; cursor: default; }

body:not(#_) #interviewPanel .iv-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: auto;
  min-height: 32px;
  padding: 0 2px;
  border: 0;
  background: transparent;
  box-shadow: none;
  color: var(--iv-link);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}

body:not(#_) #interviewPanel .iv-link:hover:not(:disabled) { text-decoration: underline; text-underline-offset: 4px; }
body:not(#_) #interviewPanel :is(button, input, textarea, label):focus-visible { outline: 2px solid color-mix(in srgb, var(--accent) 60%, transparent); outline-offset: 3px; }

#interviewPanel .iv-voice-note { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 12.5px; line-height: 1.6; }
#interviewPanel .iv-dot { flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--ed-gold); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ed-gold) 20%, transparent); }

#interviewPanel .iv-title { display: flex; flex-direction: column; font-weight: 400; }

#interviewPanel .iv-title-main {
  display: inline-block;
  align-self: flex-start;
  margin: 6px 0 -0.14em -0.06em;
  padding: 0 0.12em 0.14em 0.06em;
  font-family: "Instrument Serif", var(--ed-serif);
  font-size: clamp(54px, 5.4vw, 88px);
  font-style: italic;
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.025em;
  white-space: nowrap;
  background: linear-gradient(100deg, var(--ink) 30%, var(--accent) 115%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

#interviewPanel .iv-title-main::after { content: "."; font-style: normal; color: var(--accent); -webkit-text-fill-color: var(--accent); }

#interviewPanel .iv-empty { padding: 22px; color: var(--muted); font-size: 14px; line-height: 1.7; }

#interviewPanel .iv-empty-card { display: grid; justify-items: start; gap: 18px; padding: 32px; border: 1px dashed color-mix(in srgb, var(--ink) 20%, transparent); border-radius: 18px; color: var(--muted); }

/* ---------- Guest ---------- */
#interviewPanel .iv-guest { display: grid; justify-items: start; gap: 22px; max-width: 640px; padding: clamp(40px, 8vh, 96px) 0; }
#interviewPanel .iv-guest > p:not(.iv-kicker):not(.iv-voice-note) { color: var(--muted); font-size: 16px; line-height: 1.7; }

/* ---------- Responsive + motion ---------- */
@media (max-width: 1100px) {
  #interviewPanel .iv-hero,
  #interviewPanel .iv-custom,
}

@media (prefers-reduced-motion: reduce) {
  #interviewPanel *,
  .studio-switch-trigger,
