.iv-card-dialog .iv-card-excerpt-field textarea {
  width: 100%; min-height: 64px; max-height: 140px; resize: vertical; padding: 10px 12px; border: 1px solid var(--line);
  border-radius: 12px; background: var(--panel); color: var(--ink); font: inherit; font-size: 14px; line-height: 1.55;
}
.iv-card-dialog .iv-card-excerpt-field textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent); }
.iv-card-dialog .iv-card-text-row { display: flex; align-items: center; gap: 8px; }
.iv-card-dialog .iv-card-text-row .p1-corpus-label { margin-right: auto; }
.iv-card-dialog .iv-card-star.hidden { display: none; }
.iv-card-dialog .p1-corpus-dialog-actions { display: flex; align-items: center; gap: 12px; }
.iv-card-dialog #ivCardDialogStatus { color: var(--muted); font-size: 13px; }
.iv-card-dialog .iv-danger.hidden { display: none; }
body:not(#_) .iv-card-dialog .iv-danger { color: var(--danger, #d9534f); }
#interviewResume .iv-card-summary { margin: 4px 0 0; color: var(--muted); font-size: 13.5px; line-height: 1.45; }
#interviewResume .iv-card-summary.is-empty { opacity: 0.7; font-style: italic; }
#interviewResume .iv-card-excerpt.is-empty p { color: var(--muted); font-size: 13px; }

/* Card dialog: 名称 / 简述 split evenly; 简历原文 and STAR are both Markdown editors (excerpt shorter). */
.iv-card-dialog .p2-corpus-form-grid { grid-template-columns: minmax(0, 1fr); }
/* Wider question fields in the corpus editor. */
.iv-corpus-editor .corpus-dialog-title-line { display: flex; align-items: center; gap: 10px; width: 100%; }
.iv-corpus-editor .p1-corpus-dialog-head > div:first-child { flex: 1 1 auto; min-width: 0; }
.iv-corpus-editor .iv-corpus-question { flex: 1 1 auto; min-width: min(640px, 60vw); }
/* The resume card grid keeps three columns, so a single card stays a third wide. */
#interviewResume .p2-seasonal-card-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
@media (max-width: 1180px) { #interviewResume .p2-seasonal-card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 760px) { #interviewResume .p2-seasonal-card-grid { grid-template-columns: minmax(0, 1fr); } }

/* Card dialog: 简述 on top, then 简历原文 | STAR 正文 side by side, each a full-height Markdown editor. */
.iv-card-dialog .iv-card-dialog-card { grid-template-rows: auto auto minmax(340px, 1fr) auto; }
.iv-card-dialog .iv-card-columns { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr); gap: 16px; min-height: 0; }
.iv-card-dialog .iv-card-col { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 6px; min-height: 0; }
.iv-card-dialog .iv-card-col-head { display: flex; align-items: center; gap: 8px; min-height: 34px; }
.iv-card-dialog .iv-card-col-head .p1-corpus-label { margin: 0 auto 0 0; }
.iv-card-dialog .iv-card-col .corpus-editor-frame { height: 100%; min-height: 0; }
.iv-card-dialog .iv-card-col textarea.p1-corpus-textarea { height: 100%; min-height: 240px; }
@media (max-width: 900px) {
  .iv-card-dialog .iv-card-columns { grid-template-columns: minmax(0, 1fr); grid-auto-rows: minmax(240px, auto); }
}

/* Resume card: the 简历原文 box renders Markdown, capped with a soft fade so long excerpts don't stretch the card. */
#interviewResume .iv-card-excerpt:not(.is-empty) {
  display: block; max-height: 12.5em; overflow: hidden; font-size: 13.5px; line-height: 1.6;
  -webkit-mask-image: linear-gradient(to bottom, #000 78%, transparent); mask-image: linear-gradient(to bottom, #000 78%, transparent);
}
#interviewResume .iv-card-excerpt p { margin: 0 0 4px; }
#interviewResume .iv-card-excerpt ul, #interviewResume .iv-card-excerpt ol { margin: 2px 0 4px; padding-left: 18px; }
#interviewResume .iv-card-excerpt li { margin: 0 0 2px; list-style: disc; }
#interviewResume .iv-card-excerpt ol li { list-style: decimal; }
#interviewResume .iv-card-excerpt strong { color: var(--ink); font-weight: 700; }
#interviewResume .iv-card-excerpt code { font-family: var(--ed-mono, ui-monospace); font-size: 0.92em; }
/* JD card dialog: one column, the JD itself. */
.iv-card-dialog.is-jd .iv-card-columns { grid-template-columns: minmax(0, 1fr); }
.iv-card-dialog.is-jd .iv-card-excerpt-field { display: none; }


/* Interview home: "Mock Interview" is a word longer than the IELTS wordmark; a little smaller keeps it calm. */
body.interview-mode:not(#_):not(#__) #homePanel .hx-title-main { font-size: clamp(44px, 4vw, 58px) !important; }

/* ---------- AI 助手 page: no frame — the thread rail and the chat column sit straight on the workspace ---------- */
/* The page is its own view (shared by both modes): no title block, no card around it. A hairline separates the rail
   from the chat; the chat column centres its messages and composer at reading width; the avatar circle floats over the
   top-right corner, so the slim header leaves it room. */
#assistantPanel { padding: 0; border: 0; background: transparent; }
body.view-assistant:not(#_):not(#__) .workspace { padding-top: var(--safe-top) !important; padding-bottom: var(--safe-bottom) !important; padding-right: 0 !important; }
#ivAssistant {
  display: grid; grid-template-columns: 248px minmax(0, 1fr); height: calc(100dvh - var(--safe-top) - var(--safe-bottom)); min-height: 480px;
  border: 0; border-radius: 0; background: transparent; box-shadow: none; overflow: hidden;
}
#ivAssistant button { box-shadow: none; text-transform: none; letter-spacing: normal; min-height: 0; }
#ivAssistant .iv-as-side {
  display: flex; flex-direction: column; gap: 10px; min-height: 0; padding: 18px 12px 14px 0;
  border-right: 1px solid var(--line); background: transparent;
}
#ivAssistant .iv-as-side-head { display: flex; align-items: center; justify-content: space-between; padding: 0 2px 0 8px; }
#ivAssistant .iv-as-brand { display: inline-flex; align-items: center; gap: 8px; color: var(--ink); font-size: 14px; font-weight: 650; }
#ivAssistant .iv-as-brand svg { color: var(--accent); }
:is(#ivAssistant, #ivDock) .iv-as-icon {
  display: grid; place-items: center; flex: none; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px;
  background: transparent; color: var(--muted); cursor: pointer;
}
:is(#ivAssistant, #ivDock) .iv-as-icon:hover, :is(#ivAssistant, #ivDock) .iv-as-icon[aria-expanded="true"] { background: color-mix(in srgb, var(--ink) 7%, transparent); color: var(--ink); }
#ivAssistant .iv-as-search {
  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 10px; border: 1px solid transparent; border-radius: 9px;
  background: color-mix(in srgb, var(--ink) 5%, transparent); color: var(--muted); transition: border-color var(--motion-fast), background-color var(--motion-fast);
}
#ivAssistant .iv-as-search:focus-within { border-color: color-mix(in srgb, var(--accent) 55%, var(--line)); background: transparent; }
body:not(#_) #ivAssistant .iv-as-search input,
body:not(#_) #ivAssistant .iv-as-search input:focus {
  /* the workspace's global field style (border, panel fill, focus ring) is !important; the search box is the label */
  flex: 1; min-width: 0; height: 100%; min-height: 0; padding: 0; outline: none;
  border: 0 !important; border-radius: 0 !important; background-color: transparent !important; box-shadow: none !important;
  color: var(--ink); font-size: 13px;
}
#ivAssistant .iv-as-search input::-webkit-search-cancel-button { display: none; }
#ivAssistant .iv-as-threads { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 1px; overflow-y: auto; margin: 0 -4px; padding: 0 4px; }
#ivAssistant .iv-as-group { margin: 12px 10px 4px; color: var(--muted); font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; }
#ivAssistant .iv-as-group:first-child { margin-top: 2px; }
#ivAssistant .iv-as-thread { position: relative; display: flex; align-items: center; border-radius: 8px; }
#ivAssistant .iv-as-thread:hover { background: color-mix(in srgb, var(--ink) 5%, transparent); }
#ivAssistant .iv-as-thread.active { background: color-mix(in srgb, var(--ink) 8.5%, transparent); }
#ivAssistant .iv-as-thread-open {
  flex: 1; min-width: 0; height: 34px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: var(--ink);
  font-size: 13.5px; text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer;
}
#ivAssistant .iv-as-thread.active .iv-as-thread-open { font-weight: 600; }
#ivAssistant .iv-as-thread-actions { position: absolute; right: 4px; display: none; gap: 2px; }
#ivAssistant .iv-as-thread:is(:hover, :focus-within) .iv-as-thread-actions { display: flex; }
#ivAssistant .iv-as-thread:is(:hover, :focus-within) .iv-as-thread-open { padding-right: 64px; }
#ivAssistant .iv-as-thread-actions button {
  display: grid; place-items: center; width: 26px; height: 26px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--muted); cursor: pointer;
}
#ivAssistant .iv-as-thread-actions button:hover { background: color-mix(in srgb, var(--ink) 9%, transparent); color: var(--ink); }
#ivAssistant .iv-as-thread-actions button[data-iv-assistant="delete"]:hover { color: #dc2626; }
body:not(#_) #ivAssistant .iv-as-rename,
body:not(#_) #ivAssistant .iv-as-rename:focus {
  flex: 1; min-width: 0; height: 30px; min-height: 0; margin: 2px 4px; padding: 0 8px; outline: none; color: var(--ink); font-size: 13.5px;
  border: 1px solid var(--accent) !important; border-radius: 6px !important; background-color: var(--panel) !important; box-shadow: none !important;
}
#ivAssistant .iv-as-note { margin: 0; padding: 8px 10px; color: var(--muted); font-size: 12.5px; }
#ivAssistant .iv-as-foot-meta { display: grid; gap: 5px; padding: 10px 10px 0; border-top: 1px solid var(--line); }
#ivAssistant .iv-as-engine {
  display: flex; align-items: center; gap: 7px; min-height: 16px; color: var(--muted); font-size: 11.5px; white-space: nowrap; overflow: hidden;
}
#ivAssistant .iv-as-engine span:last-child { overflow: hidden; text-overflow: ellipsis; }
#ivAssistant .iv-as-engine:empty { display: none; }
#ivAssistant .iv-as-engine-dot { flex: none; width: 7px; height: 7px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 0 3px color-mix(in srgb, #22c55e 18%, transparent); }
#ivAssistant .iv-as-main { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
#ivAssistant .iv-as-bar { display: flex; align-items: center; flex: none; height: 64px; padding: 0 84px 0 28px; }
#ivAssistant .iv-as-title {
  min-width: 0; margin: 0; overflow: hidden; color: var(--muted); font-family: inherit; font-size: 14px; font-style: normal; font-weight: 500;
  letter-spacing: 0; white-space: nowrap; text-overflow: ellipsis;
}
#ivAssistant .iv-as-chat { flex: 1; min-height: 0; display: flex; }
#ivAssistant .iv-as-chat deep-chat, #ivDock .iv-dock-chat deep-chat { flex: 1; min-width: 0; height: 100%; }
/* composer + footnote share the messages' reading width (760px) */
#ivAssistant .iv-as-dock { flex: none; width: min(760px, calc(100% - 40px)); margin: 0 auto; padding: 0 0 12px; }
#ivAssistant .iv-as-foot { margin: 8px 0 0; color: var(--muted); font-size: 11.5px; text-align: center; opacity: 0.85; }
.iv-assistant-loading { margin: auto; color: var(--muted); font-size: 13px; }
/* drop anywhere on the column */
:is(#ivAssistant, #ivDock) .iv-as-drop {
  position: absolute; inset: 10px; z-index: 5; display: none; place-items: center; border: 1.5px dashed color-mix(in srgb, var(--accent) 70%, transparent);
  border-radius: 16px; background: color-mix(in srgb, var(--accent) 9%, color-mix(in srgb, var(--bg) 88%, transparent)); pointer-events: none;
}
:is(#ivAssistant, #ivDock) .iv-as-drop span { display: inline-flex; align-items: center; gap: 8px; color: var(--ink); font-size: 14px; font-weight: 600; }
#ivAssistantMain.is-dropping .iv-as-drop, #ivDockCard.is-dropping .iv-as-drop { display: grid; }
#ivDock .iv-dock-body { position: relative; }

/* ---------- Composer (page and dock): grows with its text; files above, toolbar below ---------- */
.iv-composer {
  display: grid; gap: 2px; padding: 10px 10px 8px 14px; border: 1px solid color-mix(in srgb, var(--ink) 13%, transparent); border-radius: 20px;
  background: var(--panel); box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05), 0 10px 30px -12px rgba(15, 23, 42, 0.16);
  transition: border-color 160ms ease, box-shadow 160ms ease;
}
body.theme-dark .iv-composer { background: color-mix(in srgb, var(--panel) 88%, #fff 3%); box-shadow: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 14px 34px -14px rgba(0, 0, 0, 0.6); }
.iv-composer:focus-within { border-color: color-mix(in srgb, var(--ink) 26%, transparent); }
/* auto-grow: the textarea and an invisible copy of its text (::after) share one grid cell, so the copy sets the height */
.iv-composer-grow { display: grid; min-width: 0; --iv-grow-max: 240px; }
.iv-composer.is-compact .iv-composer-grow { --iv-grow-max: 132px; }
.iv-composer-grow::after { content: attr(data-value) " "; visibility: hidden; pointer-events: none; overflow: hidden; }
body:not(#_):not(#__) .iv-composer .iv-composer-input,
body:not(#_):not(#__) .iv-composer .iv-composer-input:focus,
.iv-composer-grow::after {
  /* the workspace's global field style is !important; textarea and copy must wrap identically */
  grid-area: 1 / 1 / 2 / 2; display: block; width: 100%; height: auto !important; min-height: 26px !important; max-height: var(--iv-grow-max) !important;
  box-sizing: border-box; margin: 0; padding: 4px 2px 6px !important; resize: none; outline: none;
  border: 0 !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important;
  color: var(--ink); font: inherit; font-size: 15px; line-height: 1.6; white-space: pre-wrap; overflow-wrap: anywhere; word-break: normal;
}
body:not(#_):not(#__) .iv-composer .iv-composer-input { overflow-y: auto; scrollbar-width: thin; }
.iv-composer .iv-composer-input::placeholder { color: color-mix(in srgb, var(--muted) 85%, transparent); }
.iv-composer-files { display: flex; flex-wrap: wrap; gap: 8px; padding: 2px 0 8px; }
.iv-composer-files[hidden] { display: none; }
.iv-file {
  position: relative; display: flex; align-items: center; gap: 9px; max-width: 240px; height: 48px; padding: 0 30px 0 6px; border: 1px solid var(--line);
  border-radius: 12px; background: color-mix(in srgb, var(--ink) 3%, var(--panel));
}
.iv-file img { width: 36px; height: 36px; border-radius: 8px; object-fit: cover; flex: none; }
.iv-file-badge {
  display: grid; place-items: center; width: 36px; height: 36px; flex: none; border-radius: 8px; background: #dc2626; color: #fff; font-size: 10.5px; font-weight: 700; letter-spacing: 0.04em;
}
.iv-file-text { display: grid; min-width: 0; line-height: 1.3; }
.iv-file-text b { overflow: hidden; color: var(--ink); font-size: 12.5px; font-weight: 600; white-space: nowrap; text-overflow: ellipsis; }
.iv-file-text em { color: var(--muted); font-size: 11.5px; font-style: normal; }
.iv-composer .iv-file-remove {
  position: absolute; top: 50%; right: 6px; display: grid; place-items: center; width: 20px; height: 20px; min-height: 0; padding: 0; border: 0; border-radius: 50%;
  background: color-mix(in srgb, var(--ink) 10%, transparent); color: var(--ink); cursor: pointer; transform: translateY(-50%); box-shadow: none;
}
.iv-composer .iv-file-remove:hover { background: color-mix(in srgb, var(--ink) 18%, transparent); }
.iv-composer-bar { display: flex; align-items: center; gap: 8px; min-width: 0; }
.iv-composer button { box-shadow: none; text-transform: none; letter-spacing: normal; min-height: 0; }
.iv-composer .iv-composer-tool {
  display: grid; place-items: center; flex: none; width: 34px; height: 34px; margin-left: -6px; padding: 0; border: 0; border-radius: 10px;
  background: transparent; color: var(--muted); cursor: pointer; transition: background-color 140ms ease, color 140ms ease;
}
.iv-composer .iv-composer-tool:hover { background: color-mix(in srgb, var(--ink) 7%, transparent); color: var(--ink); }
.iv-composer-note { flex: 1; min-width: 0; overflow: hidden; color: var(--muted); font-size: 12px; white-space: nowrap; text-overflow: ellipsis; }
.iv-composer-count { color: var(--muted); font-size: 11.5px; font-variant-numeric: tabular-nums; }
.iv-composer-count[hidden] { display: none; }
.iv-composer .iv-composer-send {
  position: relative; display: grid; place-items: center; flex: none; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%;
  margin-left: auto; background: var(--ink); color: var(--bg); cursor: pointer; transition: background-color 160ms ease, opacity 160ms ease, transform 120ms ease;
}
.iv-composer .iv-composer-send:not(:disabled):hover { transform: translateY(-1px); }
.iv-composer .iv-composer-send:disabled { background: color-mix(in srgb, var(--ink) 16%, transparent); color: color-mix(in srgb, var(--ink) 45%, transparent); cursor: default; }
.iv-composer-spinner { display: none; position: absolute; inset: 8px; border: 2px solid color-mix(in srgb, var(--ink) 30%, transparent); border-top-color: var(--ink); border-radius: 50%; animation: iv-spin 0.8s linear infinite; }
.iv-composer .iv-composer-send.is-busy svg { display: none; }
.iv-composer .iv-composer-send.is-busy .iv-composer-spinner { display: block; }
@keyframes iv-spin { to { transform: rotate(360deg); } }
.iv-composer.is-compact { gap: 0; padding: 8px 8px 6px 12px; border-radius: 16px; }
:is(body:not(#_):not(#__) .iv-composer.is-compact .iv-composer-input, .iv-composer.is-compact .iv-composer-grow::after) { font-size: 13.5px !important; }
.iv-composer.is-compact :is(.iv-composer-tool, .iv-composer-send) { width: 30px; height: 30px; }
.iv-composer.is-compact .iv-composer-spinner { inset: 7px; }

/* 聊天 / Agent: the 标准模式 / 追问压力 sliding pill — blue for 聊天, orange for Agent (it writes to your corpus) */
.iv-mode-switch {
  --iv-pad: 3px;
  position: relative; isolation: isolate; display: inline-grid; grid-template-columns: repeat(2, minmax(0, 1fr)); flex: none; padding: var(--iv-pad);
  border: 1px solid rgba(148, 163, 184, 0.34); border-radius: 11px; background: linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(248, 250, 252, 0.94));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.78), inset 0 -1px 0 rgba(15, 23, 42, 0.04);
}
body.theme-dark .iv-mode-switch { border-color: rgba(125, 211, 252, 0.16); background: linear-gradient(180deg, rgba(11, 20, 31, 0.7), rgba(7, 13, 22, 0.86)); box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05); }
.iv-mode-switch::before {
  content: ""; position: absolute; z-index: 0; top: var(--iv-pad); bottom: var(--iv-pad); left: var(--iv-pad); width: calc((100% - var(--iv-pad) * 2) / 2);
  box-sizing: border-box; border: 1px solid rgba(255, 255, 255, 0.36); border-radius: 8px; background: linear-gradient(135deg, #0ea5e9 0%, #14b8a6 100%);
  box-shadow: 0 6px 14px rgba(14, 165, 233, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.28);
  transform: translateX(0); transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1), background 220ms ease, box-shadow 220ms ease;
}
.iv-mode-switch[data-mode="agent"]::before {
  background: linear-gradient(135deg, #f97316 0%, #ef4444 100%); box-shadow: 0 6px 14px rgba(239, 68, 68, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.28);
  transform: translateX(100%);
}
:is(.iv-composer, #ivDock) .iv-mode-option {
  position: relative; z-index: 1; min-width: 58px; height: 26px; min-height: 0; padding: 0 12px; border: 0; border-radius: 8px; background: transparent;
  color: #5d6f78; font-size: 12.5px; font-weight: 650; white-space: nowrap; cursor: pointer; transition: color 200ms ease;
}
body.theme-dark :is(.iv-composer, #ivDock) .iv-mode-option { color: #9fb0c2; }
:is(.iv-composer, #ivDock) .iv-mode-option.active, body.theme-dark :is(.iv-composer, #ivDock) .iv-mode-option.active { color: #fff; text-shadow: 0 1px 6px rgba(0, 0, 0, 0.25); }
:is(.iv-composer, #ivDock) .iv-mode-option:focus-visible { outline: 2px solid color-mix(in srgb, var(--accent) 70%, transparent); outline-offset: 1px; }
.iv-composer.is-compact .iv-mode-option { min-width: 50px; height: 24px; padding: 0 10px; font-size: 12px; }
@media (prefers-reduced-motion: reduce) { .iv-mode-switch::before { transition: none; } }

@media (max-width: 860px) {
  #ivAssistant { grid-template-columns: 1fr; height: auto; }
  #ivAssistant .iv-as-side { max-height: 200px; padding-right: 0; border-right: 0; border-bottom: 1px solid var(--line); }
  #ivAssistant .iv-as-main { height: 78vh; }
  #ivAssistant .iv-as-bar { padding-left: 16px; }
  #ivAssistant .iv-as-dock { width: calc(100% - 24px); }
  .iv-composer-note { display: none; }
}

/* ---------- AI 助手 dock: a small corner button that grows into a compact chat (corner-morph.js) ---------- */
#ivDock {
  /* --dock-surface is the colour under the dock, read at runtime (interview-assistant.js liftDock); the card is lifted
     off it the way the mode switcher's card is lifted off the sidebar, so it never blends into the page. */
  --dock-surface: var(--bg);
  --dock-bg: color-mix(in srgb, var(--dock-surface) 86%, #fff);
  --dock-raised: color-mix(in srgb, var(--dock-surface) 78%, #fff);
  --dock-line: color-mix(in srgb, var(--ink) 14%, transparent);
  --dock-closed: var(--dock-bg);
  --dock-hover: color-mix(in srgb, var(--accent) 14%, var(--dock-bg));
  /* corner-morph animates to these */
  --switch-bg: var(--dock-bg);
  --switch-line: var(--dock-line);
  --switch-shadow: 0 28px 72px rgba(0, 0, 0, 0.5), 0 2px 10px rgba(0, 0, 0, 0.32), 0 0 0 1px rgba(255, 255, 255, 0.04) inset;
  position: fixed; right: calc(18px + var(--safe-right)); bottom: calc(18px + var(--safe-bottom)); z-index: 900;
}
#ivDock[data-tone="light"] {
  --dock-bg: #fff;
  --dock-raised: #fff;
  --dock-line: color-mix(in srgb, var(--ink) 11%, transparent);
  --switch-shadow: 0 28px 72px rgba(15, 23, 42, 0.2), 0 2px 10px rgba(15, 23, 42, 0.1);
}
/* Hidden while a practice session runs (the sidebar lock marks the title block), so it never covers the exam. */
#ivDock[hidden], body:has(#viewTitleBlock.locked-flow) #ivDock { display: none; }
#ivDock button { box-shadow: none; text-transform: none; letter-spacing: normal; min-height: 0; }
#ivDock .iv-dock-trigger {
  display: grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 1px solid var(--dock-line); border-radius: 10px;
  background: var(--dock-closed); color: var(--accent); cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12), 0 8px 20px rgba(0, 0, 0, 0.18);
}
#ivDock .iv-dock-trigger:hover, #ivDock.is-open .iv-dock-trigger { background: var(--dock-hover); border-color: color-mix(in srgb, var(--accent) 45%, var(--dock-line)); }
#ivDock .iv-dock-trigger svg { width: 17px; height: 17px; }
#ivDock .iv-dock-card {
  position: fixed; z-index: 901; display: flex; width: min(420px, calc(100vw - 32px)); height: min(640px, calc(100vh - 40px));
  overflow: hidden; border: 1px solid var(--switch-line); border-radius: 16px; background: var(--switch-bg); box-shadow: var(--switch-shadow);
}
#ivDock .iv-dock-card[hidden] { display: none; }
#ivDock .iv-dock-card.is-morphing { pointer-events: none; }
#ivDock .iv-dock-body { display: flex; flex-direction: column; flex: 1; min-width: 0; min-height: 0; }
#ivDock .iv-dock-head {
  position: relative; display: flex; align-items: center; gap: 6px; flex: none; height: 48px; padding: 0 8px 0 14px; border-bottom: 1px solid var(--dock-line);
}
#ivDock .iv-dock-mark { display: grid; place-items: center; color: var(--accent); }
#ivDock .iv-dock-title { flex: 1; min-width: 0; overflow: hidden; color: var(--ink); font-size: 13.5px; font-weight: 600; white-space: nowrap; text-overflow: ellipsis; }
#ivDock .iv-dock-menu {
  position: absolute; top: 44px; right: 8px; z-index: 3; display: grid; grid-template-columns: minmax(0, 1fr); width: 240px; max-height: 360px; overflow-y: auto; padding: 6px;
  border: 1px solid var(--dock-line); border-radius: 12px; background: var(--dock-raised); box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28);
}
#ivDock .iv-dock-menu[hidden] { display: none; }
#ivDock .iv-dock-menu-label { margin: 4px 8px 6px; color: var(--muted); font-size: 11.5px; font-weight: 600; }
#ivDock .iv-dock-menu-empty { margin: 2px 8px 6px; color: var(--muted); font-size: 12.5px; }
#ivDock .iv-dock-menu button {
  display: flex; align-items: center; gap: 8px; width: 100%; height: 32px; padding: 0 8px; border: 0; border-radius: 7px;
  background: transparent; color: var(--ink); font-size: 13px; text-align: left; cursor: pointer;
}
#ivDock .iv-dock-menu button span { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
#ivDock .iv-dock-menu button svg { flex: none; color: var(--muted); }
#ivDock .iv-dock-menu button[aria-checked="true"] { font-weight: 600; }
#ivDock .iv-dock-menu button[aria-checked="true"] svg { color: var(--accent); }
#ivDock .iv-dock-menu button:hover { background: color-mix(in srgb, var(--ink) 6%, transparent); }
#ivDock .iv-dock-menu hr { margin: 6px 4px; border: 0; border-top: 1px solid var(--dock-line); }
#ivDock .iv-dock-chat { flex: 1; min-height: 0; display: flex; padding: 0 2px; }
#ivDock .iv-dock-composer { flex: none; padding: 0 10px 10px; }
#ivDock .iv-composer { border-color: var(--dock-line); background: var(--dock-raised); box-shadow: none; }
#ivDock[data-tone="light"] .iv-composer { background: color-mix(in srgb, var(--ink) 3%, #fff); }

/* ---------- 追问压力 pixel flow (canvas.is-themed): the same look in light and dark ----------
   No ignite keyframes (the bright flash at switch-on). Switching on, the navy backdrop and the darkening wash arrive
   fast (260ms) and only the pixels fade in slowly, so it never shows bright pixels on the page first and then darkens;
   switching off keeps the slow 1180ms fade (set on the persistent classes). */
body:not(#_):not(#__) .p2-pixel-flow-canvas.is-themed {
  animation: none !important;
}
/* the pre-built (paused) canvas rests at opacity 0, so switching on is one 0 → 1 fade; resting at 1 it would show at
   full brightness the moment it plays and only then start its fade */
body:not(#_) .p2-pixel-flow-canvas.is-themed {
  opacity: 0;
}
body:not(#_):not(#__) #practicePanel .exam-status.p1-pixel-flow.p1-pixel-flow-visible,
body:not(#_):not(#__) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row.p3-pixel-flow.p3-pixel-flow-visible {
  transition: background-color 260ms ease !important;
}
body:not(#_) .exam-status.p1-pixel-flow.p1-pixel-flow-visible::before,
body:not(#_) .p3-mode-row.p3-pixel-flow.p3-pixel-flow-visible::after {
  transition: opacity 260ms ease, background 260ms ease !important;
}

/* 标准 / 追问 hint beside the switch (「每题最多追问一次」 / 「面试官会连续追问」): readable size and contrast */
body:not(#_):not(#__) #practicePanel .p1-mode-help {
  --p1-help-opacity: 1;
  font-size: 13px !important;
  letter-spacing: 0.02em;
  color: color-mix(in srgb, var(--ink) 80%, transparent) !important;
}
body:not(#_):not(#__):not(#___) #practicePanel .exam-status.p1-pixel-flow-visible .p1-mode-help {
  color: #f1f5f9 !important;
  text-shadow: 0 1px 6px rgba(2, 6, 23, 0.55) !important;
}

/* light theme: the 追问压力 pixels a touch brighter and the navy wash over them lighter, so the flow reads clearly */
body:not(.theme-dark):not(#_):not(#__) :is(.exam-status.p1-pixel-flow, .p3-mode-row.p3-pixel-flow) .p2-pixel-flow-canvas.is-themed {
  filter: saturate(2.3) brightness(2.6) contrast(1.2) !important;
}
body:not(.theme-dark):not(#_) .exam-status.p1-pixel-flow::before,
body:not(.theme-dark):not(#_) .p3-mode-row.p3-pixel-flow::after {
  background:
    linear-gradient(90deg, rgba(8, 14, 24, 0.3), rgba(8, 14, 24, 0) 40%, rgba(8, 14, 24, 0.2)),
    rgba(6, 16, 28, 0.14) !important;
}

/* 还没有报告 card in the report rail: the size of a normal report card, plain white (panel in dark), no glow */
body:not(#_):not(#__) .history-list .report-empty-rail-card {
  width: 200px !important;
  min-width: 200px !important;
  max-width: 200px !important;
  min-height: 118px;
  padding: 14px 16px !important;
  border: 1px solid var(--line) !important;
  background: #fff !important;
  background-image: none !important;
  box-shadow: none !important;
}
body.theme-dark:not(#_):not(#__) .history-list .report-empty-rail-card {
  background: var(--panel) !important;
}
body:not(#_):not(#__) .history-list .report-empty-rail-card :is(strong, small) {
  white-space: normal;
}

/* P3 训练强度 box: the hint under the switch (「每个主问题后追加追问…」) and the step label read clearly — a sans face at a
   readable size; on the 追问压力 pixel flow the hint sits on a small dark pill, white, so the pixels never cut through it */
body:not(#_):not(#__):not(#___) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row :is(.p3-mode-help, .p3-launch-label) {
  font-family: "PingFang SC", "Hiragino Sans GB", -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif !important;
  letter-spacing: 0.02em !important;
}
body:not(#_):not(#__):not(#___) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row .p3-mode-help {
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.5 !important;
}
body:not(#_):not(#__):not(#___) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row .p3-launch-label {
  font-size: 14px !important;
  font-weight: 500 !important;
}
body:not(#_):not(#__):not(#___):not(#____) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row.p3-pixel-flow-visible .p3-mode-help {
  align-self: center;
  width: fit-content;
  max-width: calc(100% - 24px);
  padding: 4px 14px;
  border-radius: 999px;
  background: rgba(6, 12, 22, 0.62);
  color: #ffffff !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45) !important;
}
body:not(#_):not(#__):not(#___):not(#____) :is(#p3TopicPanel, #ivLaunch) .p3-mode-row.p3-pixel-flow-visible .p3-launch-label {
  color: #f1f5f9 !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5) !important;
}
